import React, { useState, useEffect, useCallback } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    // State for date range filtering
    const [dateRange, setDateRange] = useState('all'); // 'all', '24h', '7d', 'custom'
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');


    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            setSearchResult(null);
            alert("El número de contenedor debe tener 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements } = await getAllDataForExport();

        if (dateRange === 'all') {
            return { sessions, craneUsages, movements };
        }

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [year, month, day] = startDate.split('-').map(Number);
                    startDateFilter = new Date(year, month - 1, day, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [year, month, day] = endDate.split('-').map(Number);
                    endDateFilter = new Date(year, month - 1, day, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(session => {
                const sessionDate = new Date(session.startTime);
                return sessionDate >= startDateFilter! && sessionDate <= endDateFilter!;
            });
            const filteredSessionIds = new Set(filteredSessions.map(s => s.id));

            const filteredCraneUsages = craneUsages.filter(cu => filteredSessionIds.has(cu.sessionId));
            const filteredMovements = movements.filter(m => filteredSessionIds.has(m.sessionId));

            return { sessions: filteredSessions, craneUsages: filteredCraneUsages, movements: filteredMovements };
        }

        return { sessions: [], craneUsages: [], movements: [] }; // Return empty if date range is invalid
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();

        if (craneUsages.length === 0) {
            alert("No hay datos para exportar en el rango de fechas seleccionado.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const dataForExport = [];

        for (const usage of craneUsages) {
            const session = sessionMap.get(usage.sessionId);
            if (!session) continue;

            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter).toFixed(2) : '0.00';

            // Dynamic Yard Counting based on current configuration
            const yardColumns: Record<string, number> = {};
            config.YARDS.forEach(yardName => {
                yardColumns[`MOV X ${yardName}`] = usageMovements.filter(m => m.yard === yardName).length;
            });

            const clientMovementCounts = usageMovements.reduce((acc, mov) => {
                let client = mov.client.toUpperCase();
                if (client.includes('COSIARMA')) client = 'ORSERO';

                const knownClients = ['MARFRET', 'ORSERO'];
                const clientCategory = knownClients.includes(client) ? client : 'OTROS';

                const reason = mov.reason.toUpperCase();
                let type = 'OTROS';
                if (reason.includes('RECEPCION') || reason.includes('RECEPCIÓN')) type = 'RECEPCION';
                else if (reason.includes('DESPACHO')) type = 'DESPACHO';
                else if (reason.includes('RE-ESTIBAS') || reason.includes('REESTIBA')) type = 'REESTIBA';

                const key = `${type}_${clientCategory}`;
                acc[key] = (acc[key] || 0) + 1;
                return acc;
            }, {} as Record<string, number>);

