                'HOROMETRO INICIAL': usage.startHourMeter,
                'HOROMETRO FINAL': usage.endHourMeter || '',
                'HRS GRUA': hrsCrane,
                ...yardColumns, // Insert dynamic yard columns here
                'TOTAL POR PREDIO': usageMovements.length,
                'RECEPCION MARFRET': getCount('RECEPCION', 'MARFRET'),
                'DESPACHO MARFRET': getCount('DESPACHO', 'MARFRET'),
                'REESTIBA MARFRET': getCount('REESTIBA', 'MARFRET'),
                'RECEPCION ORSERO': getCount('RECEPCION', 'ORSERO'),
                'DESPACHO ORSERO': getCount('DESPACHO', 'ORSERO'),
                'REESTIBA ORSERO': getCount('REESTIBA', 'ORSERO'),
                'RECEPCION OTROS': getCount('RECEPCION', 'OTROS'),
                'DESPACHO OTROS': getCount('DESPACHO', 'OTROS'),
                'REESTIBA OTROS': getCount('REESTIBA', 'OTROS'),
                'Total Mov': usageMovements.length,
            };
            dataForExport.push(row);
        }

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Reporte Consolidado');
        XLSX.writeFile(workbook, 'ReporteConsolidado.xlsx');
    };

    const handleExportDetailed = async () => {
        const { movements } = await getFilteredData();

        if (movements.length === 0) {
            alert("No hay datos para exportar en el rango de fechas seleccionado.");
            return;
        }

        const dataForExport = movements.map(m => ({
            'FECHA': new Date(m.timestamp).toLocaleDateString(),
            'HORA': new Date(m.timestamp).toLocaleTimeString(),
            'OPERADOR': m.operator,
            'GRUA': m.crane,
            'PREDIO': m.yard,
            'CLIENTE': m.client,
            'CONTENEDOR': m.containerNumber,
            'RAZON MOVIMIENTO': m.reason,
        }));

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Reporte Detallado');
        XLSX.writeFile(workbook, 'ReporteDetallado.xlsx');
    };

    return (
        <div className="container mx-auto p-4 space-y-8">
            <header className="flex justify-between items-center">
                <h1 className="text-3xl font-bold">Panel de Administración</h1>
                <button
                    onClick={() => setView('LOGIN')}
                    className="flex items-center px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                    </svg>
                    Salir
                </button>
            </header>

            <AdminSection title="Consulta de Contenedor">
                <form onSubmit={handleSearch} className="flex items-end gap-4">
                    <div className="flex-grow">
                        <label htmlFor="container-search" className="block text-sm font-medium text-gray-700">Número de Contenedor (7 dígitos)</label>
                        <input
                            id="container-search"
                            type="text"
                            value={containerNumber}
                            onChange={(e) => {
                                const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 7);
                                setContainerNumber(value);
                            }}
                            className="w-full mt-1 p-2 border border-gray-300 rounded-md"
                            placeholder="Ingrese 7 dígitos"
                        />
                    </div>
                    <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700" disabled={isLoading}>
                        {isLoading ? 'Buscando...' : 'Buscar'}
                    </button>
                </form>
                {searchResult !== undefined && (
                    <div className="mt-4 p-4 bg-gray-50 border rounded-md">
                        {searchResult === null && <p>No se encontraron movimientos para este contenedor.</p>}
                        {searchResult && (
                            <div>
                                <h4 className="font-semibold">Último Movimiento:</h4>
                                <p><strong>Fecha y Hora:</strong> {new Date(searchResult.timestamp).toLocaleString()}</p>
                                <p><strong>Operador:</strong> {searchResult.operator}</p>
                                <p><strong>Razón:</strong> {searchResult.reason}</p>
                                <p><strong>Cliente:</strong> {searchResult.client}</p>
                            </div>
                        )}
                    </div>
