            </AdminSection>

            <AdminSection title="Exportar Datos">
                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Rango de Fechas</label>
                        <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full md:w-auto mt-1 p-2 border border-gray-300 rounded-md">
                            <option value="all">Todos los tiempos</option>
                            <option value="24h">Últimas 24 horas</option>
                            <option value="7d">Últimos 7 días</option>
                            <option value="custom">Rango personalizado</option>
