const AdminSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <section className="bg-white p-6 rounded-lg shadow-md border">
        <h2 className="text-2xl font-bold mb-4">{title}</h2>
        {children}
    </section>
);


interface ConfigManagerProps {
    config: Record<AppConfigKey, string[]>;
    onConfigChange: () => void;
}

const ConfigManager: React.FC<ConfigManagerProps> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);

    useEffect(() => {
        setEditableConfig(config);
    }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            const newValues = [...editableConfig[key], value];
            setEditableConfig(prev => ({ ...prev, [key]: newValues }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        const newValues = editableConfig[key].filter(item => item !== value);
        setEditableConfig(prev => ({ ...prev, [key]: newValues }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`'${key}' guardado correctamente.`);
            onConfigChange(); // Re-fetch config from DB to confirm changes
        } catch (error) {
            alert(`Error al guardar '${key}'.`);
            console.error(error);
        }
    };

    return (
        <AdminSection title="Gestión de Variables">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection
                        key={key}
                        configKey={key as AppConfigKey}
                        values={editableConfig[key as AppConfigKey]}
                        onAddItem={handleAddItem}
                        onRemoveItem={handleRemoveItem}
                        onSave={handleSave}
                    />
                ))}
            </div>
        </AdminSection>
    );
};

interface ConfigSectionProps {
    configKey: AppConfigKey;
    values: string[];
    onAddItem: (key: AppConfigKey, value: string) => void;
    onRemoveItem: (key: AppConfigKey, value: string) => void;
    onSave: (key: AppConfigKey) => void;
}

const ConfigSection: React.FC<ConfigSectionProps> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');

    const handleAdd = () => {
        onAddItem(configKey, newItem);
        setNewItem('');
    };

    const titleMap: Record<AppConfigKey, string> = {
        OPERATORS: 'Operadores', SHIFTS: 'Turnos', WORK_TYPES: 'Jornadas',
        CRANES: 'Grúas', YARDS: 'Predios', CLIENTS: 'Clientes',
        MOVEMENT_REASONS: 'Razones de Movimiento',
        CRANE_CHANGE_REASONS: 'Razones de Cambio de Grúa'
    };

    return (
        <div className="p-4 border rounded-lg bg-gray-50">
            <h3 className="font-semibold text-lg mb-2">{titleMap[configKey]}</h3>
            <ul className="space-y-1 h-40 overflow-y-auto mb-2 pr-2">
                {values.map((item) => (
                    <li key={item} className="flex justify-between items-center bg-white p-1 rounded">
                        <span className="text-sm">{item}</span>
                        <button onClick={() => onRemoveItem(configKey, item)} className="text-red-500 hover:text-red-700 text-xl">&times;</button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-2">
                <input
                    type="text"
                    value={newItem}
                    onChange={(e) => setNewItem(e.target.value)}
                    className="flex-grow p-1 border rounded-md"
                    placeholder="Nuevo valor..."
                />
                <button onClick={handleAdd} className="px-3 py-1 bg-blue-500 text-white rounded-md text-sm hover:bg-blue-600">+</button>
            </div>
            <button onClick={() => onSave(configKey)} className="w-full mt-3 px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">Guardar Cambios</button>
        </div>
    );
};

