                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'MOTIVO / ACCIÓN': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': ''
                }
            });
        });

        // Add Crane Changes (detected when a usage has an endTime and changeReason)
        craneUsages.forEach(cu => {
            if (cu.endTime && cu.changeReason) {
                const session = sessionMap.get(cu.sessionId);
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO DE EVENTO': 'CAMBIO DE GRÚA',
                        'OPERADOR': session?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': 'SISTEMA',
                        'CONTENEDOR/REF': `CAMBIO: ${cu.changeReason}`,
                        'MOTIVO / ACCIÓN': 'Finalización de uso por cambio',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason
                    }
                });
            }
        });

        // Sort chronologically
        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());

        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Reporte Detallado');
        XLSX.writeFile(workbook, 'ReporteDetallado_Completo.xlsx');
    };

    return (
        <div className="container mx-auto p-4 space-y-8">
            <header className="flex justify-between items-center">
                <h1 className="text-3xl font-bold">Panel de Administración</h1>
                <button
                    onClick={() => setView('LOGIN')}
                    className="flex items-center px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                    </svg>
                    Salir
                </button>
            </header>

            <AdminSection title="Consulta de Contenedor">
                <form onSubmit={handleSearch} className="flex items-end gap-4">
                    <div className="flex-grow">
