import React, { useState, useEffect, useCallback } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');


    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements };

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(s => {
                const d = new Date(s.startTime);
                return d >= startDateFilter! && d <= endDateFilter!;
            });
            const sIds = new Set(filteredSessions.map(s => s.id));
            return { 
                sessions: filteredSessions, 
                craneUsages: craneUsages.filter(cu => sIds.has(cu.sessionId)), 
                movements: movements.filter(m => sIds.has(m.sessionId)) 
            };
        }
        return { sessions: [], craneUsages: [], movements: [] };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter).toFixed(2) : '0.00';

            return {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TOTAL MOVIMIENTOS': usageMovements.length,
                'HORAS GRÚA': hrsCrane,
            };
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado');
        XLSX.writeFile(workbook, 'ReporteConsolidado.xlsx');
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': ''
                }
            });
        });

        craneUsages.forEach(cu => {
            if (cu.endTime && cu.changeReason) {
                const s = sessionMap.get(cu.sessionId);
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'CAMBIO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': 'SISTEMA',
                        'CONTENEDOR/REF': `CAMBIO: ${cu.changeReason}`,
                        'ACCION': 'Finalización de uso',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detallado');
        XLSX.writeFile(workbook, 'ReporteDetallado_Completo.xlsx');
    };

    return (
        <div className="container mx-auto p-4 space-y-8">
            <header className="flex justify-between items-center bg-green-50 p-4 rounded-lg shadow-sm border border-green-100">
                <h1 className="text-3xl font-extrabold text-green-900">Panel Admin</h1>
                <button onClick={() => setView('LOGIN')} className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-bold">Salir</button>
            </header>

            <AdminSection title="Consulta Contenedor">
                <form onSubmit={handleSearch} className="flex gap-2">
                    <input type="text" value={containerNumber} onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} className="flex-grow p-2 border rounded-md" placeholder="7 dígitos"/>
                    <button type="submit" className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700" disabled={isLoading}>Buscar</button>
                </form>
                {searchResult !== undefined && (
                    <div className="mt-4 p-4 bg-white border-l-4 border-green-500 rounded shadow-sm">
                        {searchResult === null ? <p>No encontrado.</p> : (
                            <div>
                                <h4 className="font-bold mb-2">Último registro:</h4>
                                <p><strong>Fecha:</strong> {new Date(searchResult.timestamp).toLocaleString()}</p>
                                <p><strong>Operador:</strong> {searchResult.operator}</p>
                                <p><strong>Motivo:</strong> {searchResult.reason}</p>
                            </div>
                        )}
                    </div>
                )}
            </AdminSection>

            <AdminSection title="Reportes">
                <div className="space-y-4">
                    <div className="flex gap-4 items-end">
                        <div className="flex-grow">
                            <label className="block text-sm font-bold text-gray-700">Período</label>
                            <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full mt-1 p-2 border rounded-md shadow-sm">
                                <option value="all">Todo el historial</option>
                                <option value="24h">Últimas 24h</option>
                                <option value="7d">Últimos 7 días</option>
                                <option value="custom">Personalizado</option>
                            </select>
                        </div>
                        {dateRange === 'custom' && (
                            <>
                                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="p-2 border rounded-md shadow-sm"/>
                                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="p-2 border rounded-md shadow-sm"/>
                            </>
                        )}
                    </div>
                    <div className="flex gap-4">
                         <button onClick={handleExportConsolidated} className="flex-1 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 font-bold shadow-md">Exportar Consolidado</button>
                        <button onClick={handleExportDetailed} className="flex-1 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 font-bold shadow-md">Exportar Detallado</button>
                    </div>
                </div>
            </AdminSection>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

const AdminSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <section className="bg-white p-6 rounded-lg shadow-md border border-gray-100">
        <h2 className="text-xl font-bold mb-4 text-green-800 border-b pb-2">{title}</h2>
        {children}
    </section>
);

const ConfigManager: React.FC<{ config: Record<AppConfigKey, string[]>; onConfigChange: () => void }> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);
    useEffect(() => { setEditableConfig(config); }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            setEditableConfig(prev => ({ ...prev, [key]: [...prev[key], value] }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        setEditableConfig(prev => ({ ...prev, [key]: prev[key].filter(i => i !== value) }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`"${key}" actualizado correctamente.`);
            onConfigChange();
        } catch (e) { alert("Error al guardar."); }
    };

    return (
        <AdminSection title="Configuración de Variables">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection key={key} configKey={key as AppConfigKey} values={editableConfig[key as AppConfigKey]} onAddItem={handleAddItem} onRemoveItem={handleRemoveItem} onSave={handleSave} />
                ))}
            </div>
        </AdminSection>
    );
};

const ConfigSection: React.FC<{ configKey: AppConfigKey; values: string[]; onAddItem: any; onRemoveItem: any; onSave: any }> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');
    const titleMap: any = { OPERATORS: 'Operadores', SHIFTS: 'Turnos', WORK_TYPES: 'Jornadas', CRANES: 'Grúas', YARDS: 'Predios', CLIENTS: 'Clientes', MOVEMENT_REASONS: 'Razones Movimiento', CRANE_CHANGE_REASONS: 'Razones Cambio Grúa' };

    return (
        <div className="p-4 border rounded-lg bg-gray-50 flex flex-col">
            <h3 className="font-bold mb-3 text-gray-700">{titleMap[configKey]}</h3>
            <ul className="flex-grow h-40 overflow-y-auto mb-3 space-y-1 pr-1">
                {values.map(item => (
                    <li key={item} className="flex justify-between items-center bg-white p-2 rounded border shadow-sm text-sm">
                        <span>{item}</span>
                        <button onClick={() => onRemoveItem(configKey, item)} className="text-red-500 font-bold hover:scale-110">✖</button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-1 mb-2">
                <input type="text" value={newItem} onChange={e => setNewItem(e.target.value)} className="flex-grow p-1 border rounded text-sm" placeholder="Añadir..."/>
                <button onClick={() => { onAddItem(configKey, newItem); setNewItem(''); }} className="px-3 bg-blue-600 text-white rounded font-bold">+</button>
            </div>
            <button onClick={() => onSave(configKey)} className="w-full py-2 bg-green-600 text-white rounded font-bold text-sm shadow-sm">Guardar {titleMap[configKey]}</button>
        </div>
    );
};

