import React, { useState, useEffect, useCallback } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');


    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(s => {
                const d = new Date(s.startTime);
                return d >= startDateFilter! && d <= endDateFilter!;
            });
            const sIds = new Set(filteredSessions.map(s => s.id));
            return { 
                sessions: filteredSessions, 
                craneUsages: craneUsages.filter(cu => sIds.has(cu.sessionId)), 
                movements: movements.filter(m => sIds.has(m.sessionId)),
                workshopRecords: workshopRecords.filter(wr => sIds.has(wr.sessionId))
            };
        }
        return { sessions: [], craneUsages: [], movements: [], workshopRecords: [] };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter).toFixed(2) : '0.00';

            return {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TOTAL MOVIMIENTOS': usageMovements.length,
                'HORAS GRÚA': hrsCrane,
            };
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado');
        XLSX.writeFile(workbook, 'ReporteConsolidado.xlsx');
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0 && workshopRecords.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });
        });

        workshopRecords.forEach(wr => {
            const s = sessionMap.get(wr.sessionId);
            allEvents.push({
                timestamp: new Date(wr.timestamp),
                data: {
                    'FECHA': new Date(wr.timestamp).toLocaleDateString(),
                    'HORA': new Date(wr.timestamp).toLocaleTimeString(),
                    'TIPO': 'TALLER MECÁNICO',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': wr.crane,
                    'PREDIO': 'TALLER',
                    'CLIENTE': 'SISTEMA',
                    'CONTENEDOR/REF': 'SERVICIO TÉCNICO',
                    'ACCION': 'Reparación / Mantenimiento',
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': wr.details
                }
            });
        });

        craneUsages.forEach(cu => {
            if (cu.endTime && cu.changeReason) {
                const s = sessionMap.get(cu.sessionId);
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'CAMBIO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': 'SISTEMA',
                        'CONTENEDOR/REF': `CAMBIO: ${cu.changeReason}`,
                        'ACCION': 'Finalización de uso',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason,
                        'NOTAS MECÁNICO / TALLER': ''
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detallado');
        XLSX.writeFile(workbook, 'ReporteDetallado_Completo.xlsx');
    };

    return (
        <div className="container mx-auto p-4 space-y-8">
            <header className="flex justify-between items-center bg-green-50 p-4 rounded-lg shadow-sm border border-green-100">
                <h1 className="text-3xl font-extrabold text-green-900">Panel Admin</h1>
                <button onClick={() => setView('LOGIN')} className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-bold">Salir</button>
            </header>

            <AdminSection title="Consulta Contenedor">
                <form onSubmit={handleSearch} className="flex gap-2">
                    <input type="text" value={containerNumber} onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} className="flex-grow p-2 border rounded-md" placeholder="7 dígitos"/>
                    <button type="submit" className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700" disabled={isLoading}>Buscar</button>
                </form>
                {searchResult !== undefined && (
                    <div className="mt-4 p-4 bg-white border-l-4 border-green-500 rounded shadow-sm">
                        {searchResult === null ? <p>No encontrado.</p> : (
                            <div>
                                <h4 className="font-bold mb-2">Último registro:</h4>
                                <p><strong>Fecha:</strong> {new Date(searchResult.timestamp).toLocaleString()}</p>
                                <p><strong>Operador:</strong> {searchResult.operator}</p>
                                <p><strong>Motivo:</strong> {searchResult.reason}</p>
                            </div>
                        )}
                    </div>
                )}
            </AdminSection>

            <AdminSection title="Reportes">
                <div className="space-y-4">
                    <div className="flex gap-4 items-end">
                        <div className="flex-grow">
                            <label className="block text-sm font-bold text-gray-700">Período</label>
                            <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full mt-1 p-2 border rounded-md shadow-sm">
                                <option value="all">Todo el historial</option>
                                <option value="24h">Últimas 24h</option>
                                <option value="7d">Últimos 7 días</option>
                                <option value="custom">Personalizado</option>
                            </select>
                        </div>
                        {dateRange === 'custom' && (
                            <>
                                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="p-2 border rounded-md shadow-sm"/>
                                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="p-2 border rounded-md shadow-sm"/>
                            </>
                        )}
                    </div>
                    <div className="flex gap-4">
                         <button onClick={handleExportConsolidated} className="flex-1 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 font-bold shadow-md">Exportar Consolidado</button>
                        <button onClick={handleExportDetailed} className="flex-1 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 font-bold shadow-md">Exportar Detallado</button>
                    </div>
                </div>
            </AdminSection>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

const AdminSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <section className="bg-white p-6 rounded-lg shadow-md border border-gray-100">
        <h2 className="text-xl font-bold mb-4 text-green-800 border-b pb-2">{title}</h2>
        {children}
    </section>
);

const ConfigManager: React.FC<{ config: Record<AppConfigKey, string[]>; onConfigChange: () => void }> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);
    useEffect(() => { setEditableConfig(config); }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            setEditableConfig(prev => ({ ...prev, [key]: [...prev[key], value] }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        setEditableConfig(prev => ({ ...prev, [key]: prev[key].filter(i => i !== value) }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`"${key}" actualizado correctamente.`);
            onConfigChange();
        } catch (e) { alert("Error al guardar."); }
    };

    return (
        <AdminSection title="Configuración de Variables">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection key={key} configKey={key as AppConfigKey} values={editableConfig[key as AppConfigKey]} onAddItem={handleAddItem} onRemoveItem={handleRemoveItem} onSave={handleSave} />
                ))}
            </div>
        </AdminSection>
    );
};

const ConfigSection: React.FC<{ configKey: AppConfigKey; values: string[]; onAddItem: any; onRemoveItem: any; onSave: any }> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');
    const titleMap: any = { OPERATORS: 'Operadores', SHIFTS: 'Turnos', WORK_TYPES: 'Jornadas', CRANES: 'Grúas', YARDS: 'Predios', CLIENTS: 'Clientes', MOVEMENT_REASONS: 'Razones Movimiento', CRANE_CHANGE_REASONS: 'Razones Cambio Grúa' };

    return (
        <div className="p-4 border rounded-lg bg-gray-50 flex flex-col">
            <h3 className="font-bold mb-3 text-gray-700">{titleMap[configKey]}</h3>
            <ul className="flex-grow h-40 overflow-y-auto mb-3 space-y-1 pr-1">
                {values.map(item => (
                    <li key={item} className="flex justify-between items-center bg-white p-2 rounded border shadow-sm text-sm">
                        <span>{item}</span>
                        <button onClick={() => onRemoveItem(configKey, item)} className="text-red-500 font-bold hover:scale-110">✖</button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-1 mb-2">
                <input type="text" value={newItem} onChange={e => setNewItem(e.target.value)} className="flex-grow p-1 border rounded text-sm" placeholder="Añadir..."/>
                <button onClick={() => { onAddItem(configKey, newItem); setNewItem(''); }} className="px-3 bg-blue-600 text-white rounded font-bold">+</button>
            </div>
            <button onClick={() => onSave(configKey)} className="w-full py-2 bg-green-600 text-white rounded font-bold text-sm shadow-sm">Guardar {titleMap[configKey]}</button>
        </div>
    );
};

import React, { useState, useContext, useEffect } from 'react';
import { SessionContext } from '../contexts/SessionContext';
import { startNewSession, getAppConfig, getLastHourMeterForCrane } from '../services/db';
import { ADMIN_USER } from '../constants';
import { AppConfigKey } from '../types';

interface LoginPageProps {
  setView: (view: 'OPERATOR' | 'ADMIN') => void;
}

export default function LoginPage({ setView }: LoginPageProps) {
  const { setActiveSession } = useContext(SessionContext);

  const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
      OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
      MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
  });

  const [operator, setOperator] = useState('');
  const [shift, setShift] = useState('');
  const [workType, setWorkType] = useState('');
  const [client, setClient] = useState('');
  const [crane, setCrane] = useState('');
  const [yard, setYard] = useState('');
  const [startHourMeter, setStartHourMeter] = useState('');
  const [adminPassword, setAdminPassword] = useState('');
  const [lastMeter, setLastMeter] = useState<number | undefined>(undefined);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchConfig = async () => {
      const appConfig = await getAppConfig();
      setConfig(appConfig);
      if (appConfig.OPERATORS?.length > 0) setOperator(appConfig.OPERATORS[0]);
      if (appConfig.SHIFTS?.length > 0) setShift(appConfig.SHIFTS[0]);
      if (appConfig.WORK_TYPES?.length > 0) setWorkType(appConfig.WORK_TYPES[0]);
      if (appConfig.CLIENTS?.length > 0) setClient(appConfig.CLIENTS[0]);
      if (appConfig.CRANES?.length > 0) setCrane(appConfig.CRANES[0]);
      if (appConfig.YARDS?.length > 0) setYard(appConfig.YARDS[0]);
    };
    fetchConfig();
  }, []);

  useEffect(() => {
      if (crane && operator !== ADMIN_USER) {
          getLastHourMeterForCrane(crane).then(setLastMeter);
      }
  }, [crane, operator]);

  const handleStartSession = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!operator || !shift || !workType || !crane || !yard || !startHourMeter) {
      setError('Todos los campos son obligatorios.');
      return;
    }

    const currentMeter = Number(startHourMeter);
    if (lastMeter !== undefined && currentMeter < lastMeter) {
        const confirmMsg = `ADVERTENCIA: El horómetro ingresado (${currentMeter}) es MENOR al último registro de esta grúa (${lastMeter}). ¿Está seguro que es correcto?`;
        if (!window.confirm(confirmMsg)) return;
    }

    try {
      setError('');
      const { session, craneUsage } = await startNewSession(
        operator,
        shift,
        workType,
        crane,
        yard,
        currentMeter,
        client
      );
      setActiveSession({ session, craneUsage });
      setView('OPERATOR');
    } catch (err) {
      setError('Error al iniciar la sesión. Intente de nuevo.');
      console.error(err);
    }
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminPassword === 'admin') {
      setError('');
      setView('ADMIN');
    } else {
      setError('Contraseña de administrador incorrecta.');
    }
  };

  const isOperatorSelected = operator && operator !== ADMIN_USER;

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-50 p-4">
      <div className="w-full max-w-md p-8 space-y-6 bg-white rounded-xl shadow-lg border border-gray-100">
        <div className="text-center">
          <h1 className="text-4xl font-extrabold text-green-700 tracking-tight">TG - Limon</h1>
          <h2 className="mt-2 text-xl font-medium text-gray-600 uppercase tracking-widest">Control de Movimientos</h2>
        </div>

        <div className="space-y-4">
          <SelectControl label="Seleccionar Usuario" value={operator} onChange={setOperator} options={config.OPERATORS} />

          {isOperatorSelected ? (
            <form className="space-y-4 animate-in fade-in duration-300" onSubmit={handleStartSession}>
              <SelectControl label="Turno" value={shift} onChange={setShift} options={config.SHIFTS} />
              <SelectControl label="Jornada" value={workType} onChange={setWorkType} options={config.WORK_TYPES} />
              {workType === 'Operación de Barco' && (
                <SelectControl label="Cliente" value={client} onChange={setClient} options={config.CLIENTS} />
              )}
              <SelectControl label="Grúa" value={crane} onChange={setCrane} options={config.CRANES} />
              <SelectControl label="Predio" value={yard} onChange={setYard} options={config.YARDS} />

              <div>
                <InputControl
                    label="Horómetro Inicial"
                    type="number"
                    value={startHourMeter}
                    onChange={setStartHourMeter}
                    placeholder="0000.00"
                    required
                    step="any"
                />
                {lastMeter !== undefined && (
                    <p className="mt-1 text-xs text-blue-600 font-bold bg-blue-50 p-1 rounded">
                        Último registro en sistema: {lastMeter}
                    </p>
                )}
              </div>

              {error && <p className="text-sm text-red-600 font-bold text-center bg-red-50 p-2 rounded">{error}</p>}

              <button
                type="submit"
                className="w-full px-4 py-3 text-white bg-green-600 rounded-lg hover:bg-green-700 transition-all font-bold shadow-md active:scale-95"
              >
                Iniciar Jornada Laboral
              </button>
            </form>
          ) : operator === ADMIN_USER ? (
            <form className="space-y-4 animate-in fade-in duration-300 pt-4 border-t" onSubmit={handleAdminLogin}>
              <InputControl
                label="Contraseña de Administrador"
                type="password"
                value={adminPassword}
                onChange={setAdminPassword}
                placeholder="Ingrese clave de acceso"
                required
              />
              {error && <p className="text-sm text-red-600 font-bold text-center bg-red-50 p-2 rounded">{error}</p>}
              <button
                type="submit"
                className="w-full px-4 py-3 text-white bg-green-800 rounded-lg hover:bg-green-900 transition-all font-bold shadow-md active:scale-95"
              >
                Acceder al Panel de Control
              </button>
            </form>
          ) : null}
        </div>
      </div>
    </div>
  );
}

interface SelectProps { label: string; value: string; onChange: (value: string) => void; options: string[]; }
const SelectControl: React.FC<SelectProps> = ({ label, value, onChange, options }) => (
    <div>
        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{label}</label>
        <select
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full px-3 py-2 text-gray-900 bg-gray-50 border border-gray-200 rounded-lg shadow-sm focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none transition-all"
        >
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

interface InputProps { label: string; type: string; value: string; onChange: (value: string) => void; placeholder: string; required?: boolean; step?: string; }
const InputControl: React.FC<InputProps> = ({ label, type, value, onChange, placeholder, required, step }) => (
    <div>
        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{label}</label>
        <input
            type={type}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder={placeholder}
            required={required}
            step={step}
            className="w-full px-3 py-2 text-gray-900 bg-gray-50 border border-gray-200 rounded-lg shadow-sm focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none transition-all"
        />
    </div>
);

import React, { useState, useContext, useEffect, useCallback } from 'react';
import { SessionContext } from '../contexts/SessionContext';
import { Movement, AppConfigKey, WorkshopRecord } from '../types';
import { addMovement, getRecentMovements, changeCrane, changeYard, endCurrentSession, countSessionMovements, getAppConfig, getLastHourMeterForCrane, addWorkshopRecord } from '../services/db';

interface OperatorDashboardProps {
    setView: (view: 'LOGIN' | 'ADMIN') => void;
}

const getReasonStyle = (reason: string): { emoji: string; color: string } => {
    switch (reason) {
        case "Recepción": return { emoji: "📥", color: "bg-green-500 hover:bg-green-600" };
        case "Despacho": return { emoji: "📤", color: "bg-blue-500 hover:bg-blue-600" };
        case "Re-estibas": return { emoji: "🔄", color: "bg-yellow-500 hover:bg-yellow-600" };
        case "Cambios de chasis": return { emoji: "🚚", color: "bg-purple-500 hover:bg-purple-600" };
        case "Revisión en Racks": return { emoji: "✅", color: "bg-teal-500 hover:bg-teal-600" };
        case "Otro": return { emoji: "❓", color: "bg-gray-500 hover:bg-gray-600" };
        default: return { emoji: "🔘", color: "bg-gray-500 hover:bg-gray-600" };
    }
};

export default function OperatorDashboard({ setView }: OperatorDashboardProps) {
    const { activeSession, setActiveSession, logout } = useContext(SessionContext);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
        MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });
    const [client, setClient] = useState('');
    const [containerNumber, setContainerNumber] = useState('');
    const [recentMovements, setRecentMovements] = useState<Movement[]>([]);
    const [totalMovements, setTotalMovements] = useState(0);
    const [isCraneModalOpen, setCraneModalOpen] = useState(false);
    const [isYardModalOpen, setYardModalOpen] = useState(false);
    const [isWorkshopModalOpen, setWorkshopModalOpen] = useState(false);
    const [isEndSessionModalOpen, setEndSessionModalOpen] = useState(false);
    const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });

    useEffect(() => {
        const fetchConfig = async () => {
            const appConfig = await getAppConfig();
            setConfig(appConfig);
        };
        fetchConfig();
    }, []);

    const fetchMovements = useCallback(async () => {
        if (activeSession?.session.id) {
            const movements = await getRecentMovements(activeSession.session.id, 5);
            setRecentMovements(movements);
            const count = await countSessionMovements(activeSession.session.id);
            setTotalMovements(count);
        }
    }, [activeSession]);

    useEffect(() => {
        if (activeSession) {
            if (config.CLIENTS.length > 0) {
              setClient(activeSession.session.client || config.CLIENTS[0]);
            }
            fetchMovements();
        } else {
            setView('LOGIN');
        }
    }, [activeSession, fetchMovements, setView, config.CLIENTS]);

    const showStatusMessage = (type: 'success' | 'error', text: string) => {
        setStatusMessage({ type, text });
        setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
    };

    const handleLogMovement = async (reason: string) => {
        if (!activeSession) return;
        if (!/^\d{7}$/.test(containerNumber)) {
            showStatusMessage('error', 'El número de contenedor debe tener 7 dígitos.');
            return;
        }

        try {
            // Creamos una función para generar el objeto base para evitar mutaciones accidentales
            const getBaseMovement = () => ({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                client,
                containerNumber,
                reason,
                yard: activeSession.craneUsage.yard,
                crane: activeSession.craneUsage.crane,
                operator: activeSession.session.operator,
            });

            // Primer movimiento
            await addMovement(getBaseMovement());

            // Si es Revisión en Racks, registramos un segundo movimiento idéntico
            if (reason === "Revisión en Racks") {
                // Pequeño delay de 1ms para que el timestamp sea ligeramente distinto si se desea, 
                // pero lo más importante es que sea un objeto nuevo sin propiedad 'id'
                await addMovement(getBaseMovement());
            }

            showStatusMessage('success', `Movimiento '${reason}' registrado.`);
            setContainerNumber('');
            fetchMovements();
        } catch (error) {
            showStatusMessage('error', 'Error al registrar el movimiento.');
            console.error(error);
        }
    };

    if (!activeSession) return null;

    const { session, craneUsage } = activeSession;

    return (
        <div className="container mx-auto p-4 space-y-6 text-gray-900">
             <header className="flex justify-between items-center">
                <h1 className="text-3xl font-bold">Panel del Operador</h1>
                <div>
                    <button onClick={() => setEndSessionModalOpen(true)} className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700">Cerrar Sesión</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-1 bg-white p-6 rounded-lg shadow-md border">
                    <h3 className="text-xl font-semibold mb-4">Información</h3>
                    <p><strong>Operador:</strong> {session.operator}</p>
                    <p><strong>Turno:</strong> {session.shift}</p>
                    <p><strong>Grúa:</strong> {craneUsage.crane}</p>
                    <p><strong>Predio:</strong> {craneUsage.yard}</p>
                    <div className="mt-4 bg-blue-100 p-3 rounded-lg text-center">
                        <p className="text-lg font-bold text-blue-800">Total Movimientos Hoy</p>
                        <p className="text-4xl font-extrabold text-blue-600">{totalMovements}</p>
                    </div>
                    <div className="mt-4 flex flex-col gap-2">
                        <button onClick={() => setCraneModalOpen(true)} className="w-full px-3 py-1.5 bg-green-600 text-white rounded-md text-sm hover:bg-green-700">Cambiar Grúa</button>
                        <button onClick={() => setYardModalOpen(true)} className="w-full px-3 py-1.5 bg-green-600 text-white rounded-md text-sm hover:bg-green-700">Cambiar Predio</button>
                        <button onClick={() => setWorkshopModalOpen(true)} className="w-full px-3 py-1.5 bg-orange-500 text-white rounded-md text-sm hover:bg-orange-600 flex items-center justify-center font-bold">
                            <span className="mr-2">🔧</span> TALLER MEC
                        </button>
                    </div>
                </div>

                <div className="md:col-span-2 bg-white p-6 rounded-lg shadow-md border">
                    <h3 className="text-xl font-semibold mb-4">Registrar Movimiento</h3>
                    <div className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium">Cliente</label>
                                <select value={client} onChange={(e) => setClient(e.target.value)} disabled={session.workType === 'Operación de Barco'} className="w-full mt-1 p-2 border rounded-md bg-white border-gray-300 disabled:opacity-50">
                                    {(config.CLIENTS || []).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium"># Contenedor (7 dígitos)</label>
                                <input type="text" value={containerNumber} onChange={(e) => {
                                        const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 7);
                                        setContainerNumber(value);
                                    }} pattern="\d{7}" title="Debe contener 7 dígitos numéricos" required className="w-full mt-1 p-2 border rounded-md bg-white border-gray-300"/>
                            </div>
                        </div>
                        <div>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                                {(config.MOVEMENT_REASONS || []).map((reason) => {
                                    const { emoji, color } = getReasonStyle(reason);
                                    return (
                                        <button
                                            key={reason}
                                            type="button"
                                            onClick={() => handleLogMovement(reason)}
                                            className={`p-2 rounded-md text-white flex flex-col items-center justify-center transition-transform transform active:scale-95 ${color}`}
                                        >
                                            <span className="text-2xl">{emoji}</span>
                                            <span className="text-xs font-semibold mt-1 text-center">{reason}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                    {statusMessage.text && <div className={`mt-4 p-2 rounded-md text-center text-white ${statusMessage.type === 'success' ? 'bg-green-500' : 'bg-red-500'}`}>{statusMessage.text}</div>}
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-md border">
                <h3 className="text-xl font-semibold mb-4">Últimos 5 Movimientos</h3>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Hora</th>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Contenedor</th>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Cliente</th>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Razón</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {recentMovements.length > 0 ? recentMovements.map(m => (
                                <tr key={m.id}>
                                    <td className="px-6 py-4 whitespace-nowrap">{new Date(m.timestamp).toLocaleTimeString()}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{m.containerNumber}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{m.client}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{m.reason}</td>
                                </tr>
                            )) : (
                                <tr><td colSpan={4} className="text-center py-4">No hay movimientos registrados.</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {isCraneModalOpen && <ChangeCraneModal onClose={() => setCraneModalOpen(false)} fetchMovements={fetchMovements} config={config} />}
            {isYardModalOpen && <ChangeYardModal onClose={() => setYardModalOpen(false)} config={config} />}
            {isWorkshopModalOpen && <WorkshopModal onClose={() => setWorkshopModalOpen(false)} showStatus={showStatusMessage} />}
            {isEndSessionModalOpen && <EndSessionModal onClose={() => setEndSessionModalOpen(false)} />}
        </div>
    );
}

function WorkshopModal({ onClose, showStatus }: { onClose: () => void, showStatus: (type: 'success' | 'error', text: string) => void }) {
    const { activeSession } = useContext(SessionContext);
    const [details, setDetails] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession || !details) return;

        try {
            await addWorkshopRecord({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                crane: activeSession.craneUsage.crane,
                details
            });
            showStatus('success', 'Reporte técnico guardado.');
            onClose();
        } catch (err) {
            setError('Error al guardar reporte técnico.');
        }
    };

    return (
        <Modal title="Reporte Técnico (TALLER MEC)" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <p className="text-sm text-gray-600">Registre los arreglos o mantenimientos realizados a la grúa <strong>{activeSession?.craneUsage.crane}</strong>.</p>
                <div>
                    <label className="block text-sm font-medium">Comentarios / Arreglos realizados</label>
                    <textarea 
                        value={details} 
                        onChange={e => setDetails(e.target.value)} 
                        required 
                        className="w-full mt-1 p-2 border rounded-md border-gray-300 shadow-sm" 
                        rows={5} 
                        placeholder="Describa el trabajo del mecánico..."
                    />
                </div>
                {error && <p className="text-red-500 text-sm">{error}</p>}
                <div className="flex justify-end space-x-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-orange-600 text-white rounded-md font-bold">Guardar Reporte</button>
                </div>
            </form>
        </Modal>
    );
}

function EndSessionModal({ onClose }: { onClose: () => void }) {
    const { activeSession, logout } = useContext(SessionContext);
    const [finalHourMeter, setFinalHourMeter] = useState('');
    const [error, setError] = useState('');

    const handleEndSession = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession) return;

        const finalValue = Number(finalHourMeter);
        const initialValue = activeSession.craneUsage.startHourMeter;

        if (!finalHourMeter || isNaN(finalValue)) {
            setError(`Ingrese un valor numérico.`);
            return;
        }

        if (finalValue < initialValue) {
            const confirmMsg = `ADVERTENCIA: El horómetro final (${finalValue}) es MENOR al inicial (${initialValue}). ¿Desea confirmar de todos modos?`;
            if (!window.confirm(confirmMsg)) return;
        }

        try {
            await endCurrentSession(
                activeSession.session.id!,
                activeSession.craneUsage.id!,
                finalValue
            );
            logout();
        } catch (err) {
            setError('Error al finalizar sesión.');
            console.error(err);
        }
    };

    if (!activeSession) return null;

    return (
        <Modal title="Finalizar Jornada" onClose={onClose}>
            <form onSubmit={handleEndSession} className="space-y-4">
                <p><strong>Grúa en uso:</strong> {activeSession.craneUsage.crane}</p>
                <p><strong>Horómetro Inicial:</strong> {activeSession.craneUsage.startHourMeter}</p>
                <Input label="Horómetro Final" type="number" value={finalHourMeter} onChange={setFinalHourMeter} required step="any" />
                {error && <p className="text-sm text-red-500">{error}</p>}
                <div className="flex justify-end space-x-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-red-600 text-white rounded-md">Confirmar y Cerrar</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeCraneModal({ onClose, fetchMovements, config }: { onClose: () => void, fetchMovements: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [endHourMeter, setEndHourMeter] = useState('');
    const [reason, setReason] = useState(config.CRANE_CHANGE_REASONS?.[0] || '');
    const [reasonDetails, setReasonDetails] = useState('');
    const [newCrane, setNewCrane] = useState(() => {
        if (!activeSession) return '';
        const availableCranes = config.CRANES.filter(c => c !== activeSession.craneUsage.crane);
        return availableCranes[0] || '';
    });
    const [newStartHourMeter, setNewStartHourMeter] = useState('');
    const [lastMeterForNew, setLastMeterForNew] = useState<number | undefined>(undefined);
    const [error, setError] = useState('');

    useEffect(() => {
        if (newCrane) {
            getLastHourMeterForCrane(newCrane).then(setLastMeterForNew);
        }
    }, [newCrane]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession || !endHourMeter || !reason || !newCrane || !newStartHourMeter) {
            setError('Todos los campos son obligatorios.');
            return;
        }

        const initialMeterOld = activeSession.craneUsage.startHourMeter;
        const currentEndMeter = Number(endHourMeter);
        if (currentEndMeter < initialMeterOld) {
            if (!window.confirm(`El horómetro final (${currentEndMeter}) es menor al inicial (${initialMeterOld}). ¿Desea continuar?`)) return;
        }

        const newStartVal = Number(newStartHourMeter);
        if (lastMeterForNew !== undefined && newStartVal < lastMeterForNew) {
            if (!window.confirm(`El horómetro inicial de la nueva grúa (${newStartVal}) es menor al último registro (${lastMeterForNew}). ¿Desea continuar?`)) return;
        }

        try {
            const newCraneUsage = await changeCrane(
                activeSession.craneUsage.id!,
                currentEndMeter,
                reason,
                newCrane,
                activeSession.craneUsage.yard,
                newStartVal,
                activeSession.session.id!,
                reason === 'Falla mecánica' ? reasonDetails : undefined
            );
            setActiveSession({ ...activeSession, craneUsage: newCraneUsage });
            fetchMovements();
            onClose();
        } catch (err) {
            setError('Error al cambiar de grúa.');
            console.error(err);
        }
    };

    return (
        <Modal title="Cambiar de Grúa" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <p>Grúa actual: <strong>{activeSession?.craneUsage.crane}</strong> (Ini: {activeSession?.craneUsage.startHourMeter})</p>
                <Input label="Último Horómetro (máquina actual)" type="number" value={endHourMeter} onChange={setEndHourMeter} required step="any" />
                <Select label="Razón del Cambio" value={reason} onChange={setReason} options={config.CRANE_CHANGE_REASONS || []} />
                {reason === 'Falla mecánica' && (
                     <div>
                        <label className="block text-sm font-medium">Descripción de la Falla</label>
                        <textarea value={reasonDetails} onChange={e => setReasonDetails(e.target.value)} required className="w-full mt-1 p-2 border rounded-md border-gray-300" rows={3} placeholder="Describa la falla..."/>
                    </div>
                )}
                <hr className="border-gray-300"/>
                <Select label="Nueva Grúa" value={newCrane} onChange={setNewCrane} options={(config.CRANES || []).filter(c => c !== activeSession?.craneUsage.crane)} />
                <div>
                    <Input label="Horómetro Inicial (nueva máquina)" type="number" value={newStartHourMeter} onChange={setNewStartHourMeter} required step="any" />
                    {lastMeterForNew !== undefined && <p className="text-xs text-blue-600 font-semibold mt-1">Último registro de {newCrane}: {lastMeterForNew}</p>}
                </div>
                {error && <p className="text-red-500">{error}</p>}
                <div className="flex justify-end space-x-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-md">Confirmar Cambio</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeYardModal({ onClose, config }: { onClose: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newYard, setNewYard] = useState(() => {
        if (!activeSession) return '';
        const availableYards = config.YARDS.filter(y => y !== activeSession.craneUsage.yard);
        return availableYards[0] || '';
    });

    const handleSubmit = async () => {
        if (!activeSession) return;
        await changeYard(activeSession.craneUsage.id!, newYard);
        setActiveSession(prev => prev ? ({ ...prev, craneUsage: { ...prev.craneUsage, yard: newYard } }) : null);
        onClose();
    };

    return (
         <Modal title="Cambiar de Predio" onClose={onClose}>
            <div className="space-y-4">
                <Select label="Nuevo Predio" value={newYard} onChange={setNewYard} options={(config.YARDS || []).filter(y => y !== activeSession?.craneUsage.yard)} />
                <div className="flex justify-end space-x-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button onClick={handleSubmit} className="px-4 py-2 bg-green-600 text-white rounded-md">Confirmar</button>
                </div>
            </div>
        </Modal>
    );
}

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
