import React, { useState, useContext, useEffect, useCallback } from 'react';
import { SessionContext } from '../contexts/SessionContext';
import { Movement, AppConfigKey, WorkshopRecord } from '../types';
import { addMovement, getRecentMovements, changeCrane, changeYard, endCurrentSession, countSessionMovements, getAppConfig, getLastHourMeterForCrane, addWorkshopRecord, getLatestUsageInSession } from '../services/db';

interface OperatorDashboardProps {
    setView: (view: 'LOGIN' | 'ADMIN') => void;
}

const getReasonStyle = (reason: string): { emoji: string; color: string } => {
    switch (reason) {
        case "Recepción": return { emoji: "📥", color: "bg-green-500 hover:bg-green-600" };
        case "Despacho": return { emoji: "📤", color: "bg-blue-500 hover:bg-blue-600" };
        case "Re-estibas": return { emoji: "🔄", color: "bg-yellow-500 hover:bg-yellow-600" };
        case "Cambios de chasis": return { emoji: "🚚", color: "bg-purple-500 hover:bg-purple-600" };
        case "Revisión en Racks": return { emoji: "✅", color: "bg-teal-500 hover:bg-teal-600" };
        case "Otro": return { emoji: "❓", color: "bg-gray-500 hover:bg-gray-600" };
        default: return { emoji: "🔘", color: "bg-gray-500 hover:bg-gray-600" };
    }
};

export default function OperatorDashboard({ setView }: OperatorDashboardProps) {
    const { activeSession, setActiveSession, logout } = useContext(SessionContext);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
        MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });
    const [client, setClient] = useState('');
    const [containerNumber, setContainerNumber] = useState('');
    const [recentMovements, setRecentMovements] = useState<Movement[]>([]);
    const [totalMovements, setTotalMovements] = useState(0);
    const [isCraneModalOpen, setCraneModalOpen] = useState(false);
    const [isYardModalOpen, setYardModalOpen] = useState(false);
    const [isWorkshopModalOpen, setWorkshopModalOpen] = useState(false);
    const [isEndSessionModalOpen, setEndSessionModalOpen] = useState(false);
    const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });

    useEffect(() => {
        const fetchConfig = async () => {
            const appConfig = await getAppConfig();
            setConfig(appConfig);
        };
        fetchConfig();
    }, []);

    const fetchMovements = useCallback(async () => {
        if (activeSession?.session.id) {
            const movements = await getRecentMovements(activeSession.session.id, 5);
            setRecentMovements(movements);
            const count = await countSessionMovements(activeSession.session.id);
            setTotalMovements(count);
        }
    }, [activeSession]);

    useEffect(() => {
        if (activeSession) {
            if (config.CLIENTS.length > 0) {
              setClient(activeSession.session.client || config.CLIENTS[0]);
            }
            fetchMovements();
        } else {
            setView('LOGIN');
        }
    }, [activeSession, fetchMovements, setView, config.CLIENTS]);

    const showStatusMessage = (type: 'success' | 'error', text: string) => {
        setStatusMessage({ type, text });
        setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
    };

    const handleLogMovement = async (reason: string) => {
        if (!activeSession) return;
        if (!/^\d{7}$/.test(containerNumber)) {
            showStatusMessage('error', 'El número de contenedor debe tener 7 dígitos.');
            return;
        }

        try {
            const getBaseMovement = () => ({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                client,
                containerNumber,
                reason,
                yard: activeSession.craneUsage.yard,
                crane: activeSession.craneUsage.crane,
                operator: activeSession.session.operator,
            });

            await addMovement(getBaseMovement());

            if (reason === "Revisión en Racks") {
                await addMovement(getBaseMovement());
            }

            showStatusMessage('success', `Movimiento '${reason}' registrado.`);
            setContainerNumber('');
            fetchMovements();
        } catch (error) {
            showStatusMessage('error', 'Error al registrar el movimiento.');
            console.error(error);
        }
    };

    if (!activeSession) return null;

    const { session, craneUsage } = activeSession;

    return (
        <div className="container mx-auto p-4 space-y-6 text-gray-900">
             <header className="flex justify-between items-center">
                <h1 className="text-3xl font-bold">Panel del Operador</h1>
                <div>
                    <button onClick={() => setEndSessionModalOpen(true)} className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700">Cerrar Sesión</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-1 bg-white p-6 rounded-lg shadow-md border">
                    <h3 className="text-xl font-semibold mb-4">Información</h3>
                    <p><strong>Operador:</strong> {session.operator}</p>
                    <p><strong>Turno:</strong> {session.shift}</p>
                    <p><strong>Grúa:</strong> {craneUsage.crane}</p>
                    <p><strong>Predio:</strong> {craneUsage.yard}</p>
                    <div className="mt-4 bg-blue-100 p-3 rounded-lg text-center">
                        <p className="text-lg font-bold text-blue-800">Total Movimientos Hoy</p>
                        <p className="text-4xl font-extrabold text-blue-600">{totalMovements}</p>
                    </div>
                    <div className="mt-4 flex flex-col gap-2">
                        <button onClick={() => setCraneModalOpen(true)} className="w-full px-3 py-1.5 bg-green-600 text-white rounded-md text-sm hover:bg-green-700">Cambiar Grúa</button>
                        <button onClick={() => setYardModalOpen(true)} className="w-full px-3 py-1.5 bg-green-600 text-white rounded-md text-sm hover:bg-green-700">Cambiar Predio</button>
                        <button onClick={() => setWorkshopModalOpen(true)} className="w-full px-3 py-1.5 bg-orange-500 text-white rounded-md text-sm hover:bg-orange-600 flex items-center justify-center font-bold">
                            <span className="mr-2">🔧</span> TALLER MEC
                        </button>
                    </div>
                </div>

                <div className="md:col-span-2 bg-white p-6 rounded-lg shadow-md border">
                    <h3 className="text-xl font-semibold mb-4">Registrar Movimiento</h3>
                    <div className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium">Cliente</label>
                                <select value={client} onChange={(e) => setClient(e.target.value)} disabled={session.workType === 'Operación de Barco'} className="w-full mt-1 p-2 border rounded-md bg-white border-gray-300 disabled:opacity-50">
                                    {(config.CLIENTS || []).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium"># Contenedor (7 dígitos)</label>
                                <input type="text" value={containerNumber} onChange={(e) => {
                                        const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 7);
                                        setContainerNumber(value);
                                    }} pattern="\d{7}" title="Debe contener 7 dígitos numéricos" required className="w-full mt-1 p-2 border rounded-md bg-white border-gray-300"/>
                            </div>
                        </div>
                        <div>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                                {(config.MOVEMENT_REASONS || []).map((reason) => {
                                    const { emoji, color } = getReasonStyle(reason);
                                    return (
                                        <button
                                            key={reason}
                                            type="button"
                                            onClick={() => handleLogMovement(reason)}
                                            className={`p-2 rounded-md text-white flex flex-col items-center justify-center transition-transform transform active:scale-95 ${color}`}
                                        >
                                            <span className="text-2xl">{emoji}</span>
                                            <span className="text-xs font-semibold mt-1 text-center">{reason}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                    {statusMessage.text && <div className={`mt-4 p-2 rounded-md text-center text-white ${statusMessage.type === 'success' ? 'bg-green-500' : 'bg-red-500'}`}>{statusMessage.text}</div>}
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-md border">
                <h3 className="text-xl font-semibold mb-4">Últimos 5 Movimientos</h3>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Hora</th>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Contenedor</th>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Cliente</th>
                                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider">Razón</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {recentMovements.length > 0 ? recentMovements.map(m => (
                                <tr key={m.id}>
                                    <td className="px-6 py-4 whitespace-nowrap">{new Date(m.timestamp).toLocaleTimeString()}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{m.containerNumber}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{m.client}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{m.reason}</td>
                                </tr>
                            )) : (
                                <tr><td colSpan={4} className="text-center py-4">No hay movimientos registrados.</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {isCraneModalOpen && <ChangeCraneModal onClose={() => setCraneModalOpen(false)} fetchMovements={fetchMovements} config={config} />}
            {isYardModalOpen && <ChangeYardModal onClose={() => setYardModalOpen(false)} config={config} />}
            {isWorkshopModalOpen && <WorkshopModal onClose={() => setWorkshopModalOpen(false)} showStatus={showStatusMessage} />}
            {isEndSessionModalOpen && <EndSessionModal onClose={() => setEndSessionModalOpen(false)} />}
        </div>
    );
}

function WorkshopModal({ onClose, showStatus }: { onClose: () => void, showStatus: (type: 'success' | 'error', text: string) => void }) {
    const { activeSession } = useContext(SessionContext);
    const [details, setDetails] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession || !details) return;

        try {
            await addWorkshopRecord({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                crane: activeSession.craneUsage.crane,
                details
            });
            showStatus('success', 'Reporte técnico guardado.');
            onClose();
        } catch (err) {
            setError('Error al guardar reporte técnico.');
        }
    };

    return (
        <Modal title="Reporte Técnico (TALLER MEC)" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <p className="text-sm text-gray-600">Registre los arreglos o mantenimientos realizados a la grúa <strong>{activeSession?.craneUsage.crane}</strong>.</p>
                <div>
                    <label className="block text-sm font-medium">Comentarios / Arreglos realizados</label>
                    <textarea 
                        value={details} 
                        onChange={e => setDetails(e.target.value)} 
                        required 
                        className="w-full mt-1 p-2 border rounded-md border-gray-300 shadow-sm" 
                        rows={5} 
                        placeholder="Describa el trabajo del mecánico..."
                    />
                </div>
                {error && <p className="text-red-500 text-sm">{error}</p>}
                <div className="flex justify-end space-x-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-orange-600 text-white rounded-md font-bold">Guardar Reporte</button>
                </div>
            </form>
        </Modal>
    );
}

function EndSessionModal({ onClose }: { onClose: () => void }) {
    const { activeSession, logout } = useContext(SessionContext);
    const [finalHourMeter, setFinalHourMeter] = useState('');
    const [error, setError] = useState('');

    const handleEndSession = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession) return;

        const finalValue = Number(finalHourMeter);
        const initialValue = activeSession.craneUsage.startHourMeter;

        if (!finalHourMeter || isNaN(finalValue)) {
            setError(`Ingrese un valor numérico.`);
            return;
        }

        if (finalValue < initialValue) {
            const confirmMsg = `ADVERTENCIA: El horómetro final (${finalValue}) es MENOR al inicial (${initialValue}). ¿Desea confirmar de todos modos?`;
            if (!window.confirm(confirmMsg)) return;
        }

        try {
            await endCurrentSession(
                activeSession.session.id!,
                activeSession.craneUsage.id!,
                finalValue
            );
            logout();
        } catch (err) {
            setError('Error al finalizar sesión.');
            console.error(err);
        }
    };

    if (!activeSession) return null;

    return (
        <Modal title="Finalizar Jornada" onClose={onClose}>
            <form onSubmit={handleEndSession} className="space-y-4">
                <p><strong>Grúa en uso:</strong> {activeSession.craneUsage.crane}</p>
                <p><strong>Horómetro Inicial:</strong> {activeSession.craneUsage.startHourMeter}</p>
                <Input label="Horómetro Final" type="number" value={finalHourMeter} onChange={setFinalHourMeter} required step="any" />
                {error && <p className="text-sm text-red-500">{error}</p>}
                <div className="flex justify-end space-x-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-red-600 text-white rounded-md">Confirmar y Cerrar</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeCraneModal({ onClose, fetchMovements, config }: { onClose: () => void, fetchMovements: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [endHourMeter, setEndHourMeter] = useState('');
    const [reason, setReason] = useState(config.CRANE_CHANGE_REASONS?.[0] || '');
    const [reasonDetails, setReasonDetails] = useState('');
    const [newCrane, setNewCrane] = useState(() => {
        if (!activeSession) return '';
        const availableCranes = config.CRANES.filter(c => c !== activeSession.craneUsage.crane);
        return availableCranes[0] || '';
    });
    const [newStartHourMeter, setNewStartHourMeter] = useState('');
    const [lastMeterForNew, setLastMeterForNew] = useState<number | undefined>(undefined);
    const [isContinuing, setIsContinuing] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (newCrane && activeSession) {
            getLatestUsageInSession(activeSession.session.id!, newCrane).then(usage => {
                if (usage && usage.endHourMeter !== undefined) {
                    setNewStartHourMeter(usage.endHourMeter.toString());
                    setLastMeterForNew(usage.endHourMeter);
                    setIsContinuing(true);
                } else {
                    setIsContinuing(false);
                    getLastHourMeterForCrane(newCrane).then(setLastMeterForNew);
                }
            });
        }
    }, [newCrane, activeSession]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        // Si la razón es 'Cambio de predio', el horómetro final es opcional
        const isYardChange = reason === 'Cambio de predio';

        if (!activeSession || (!isYardChange && !endHourMeter) || !reason || !newCrane || !newStartHourMeter) {
            setError('Todos los campos son obligatorios.');
            return;
        }

        const initialMeterOld = activeSession.craneUsage.startHourMeter;
        let currentEndMeter = endHourMeter ? Number(endHourMeter) : initialMeterOld;

        if (endHourMeter && currentEndMeter < initialMeterOld) {
            if (!window.confirm(`El horómetro final (${currentEndMeter}) es menor al inicial (${initialMeterOld}). ¿Desea continuar?`)) return;
        }

        const newStartVal = Number(newStartHourMeter);
        if (!isContinuing && lastMeterForNew !== undefined && newStartVal < lastMeterForNew) {
            if (!window.confirm(`El horómetro inicial de la nueva grúa (${newStartVal}) es menor al último registro (${lastMeterForNew}). ¿Desea continuar?`)) return;
        }

        try {
            const newCraneUsage = await changeCrane(
                activeSession.craneUsage.id!,
                currentEndMeter,
                reason,
                newCrane,
                activeSession.craneUsage.yard,
                newStartVal,
                activeSession.session.id!,
                reason === 'Falla mecánica' ? reasonDetails : undefined
            );
            setActiveSession({ ...activeSession, craneUsage: newCraneUsage });
            fetchMovements();
            onClose();
        } catch (err) {
            setError('Error al cambiar de grúa.');
            console.error(err);
        }
    };

    const isYardChange = reason === 'Cambio de predio';

    return (
        <Modal title="Cambiar de Grúa" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <p>Grúa actual: <strong>{activeSession?.craneUsage.crane}</strong> (Ini: {activeSession?.craneUsage.startHourMeter})</p>
                <Input 
                    label="Último Horómetro (máquina actual)" 
                    type="number" 
                    value={endHourMeter} 
                    onChange={setEndHourMeter} 
                    required={!isYardChange} 
                    step="any" 
                    placeholder={isYardChange ? "Opcional para cambio de predio" : ""}
                />
                <Select label="Razón del Cambio" value={reason} onChange={setReason} options={config.CRANE_CHANGE_REASONS || []} />
                {reason === 'Falla mecánica' && (
                     <div>
                        <label className="block text-sm font-medium">Descripción de la Falla</label>
                        <textarea value={reasonDetails} onChange={e => setReasonDetails(e.target.value)} required className="w-full mt-1 p-2 border rounded-md border-gray-300" rows={3} placeholder="Describa la falla..."/>
                    </div>
                )}
                <hr className="border-gray-300"/>
                <Select label="Nueva Grúa" value={newCrane} onChange={setNewCrane} options={(config.CRANES || []).filter(c => c !== activeSession?.craneUsage.crane)} />
                <div>
                    <label className="block text-sm font-medium">Horómetro Inicial (nueva máquina)</label>
                    <input 
                        type="number" 
                        value={newStartHourMeter} 
                        onChange={e => setNewStartHourMeter(e.target.value)} 
                        required 
                        step="any" 
                        readOnly={isContinuing}
                        className={`w-full mt-1 p-2 border rounded-md border-gray-300 shadow-sm ${isContinuing ? 'bg-gray-100 cursor-not-allowed' : 'bg-white'}`}
                    />
                    {isContinuing && <p className="text-xs text-green-600 font-bold mt-1">✓ Continuando uso anterior en esta sesión.</p>}
                    {!isContinuing && lastMeterForNew !== undefined && <p className="text-xs text-blue-600 font-semibold mt-1">Último registro de {newCrane}: {lastMeterForNew}</p>}
                </div>
                {error && <p className="text-red-500">{error}</p>}
                <div className="flex justify-end space-x-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-md">Confirmar Cambio</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeYardModal({ onClose, config }: { onClose: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newYard, setNewYard] = useState(() => {
        if (!activeSession) return '';
        const availableYards = config.YARDS.filter(y => y !== activeSession.craneUsage.yard);
        return availableYards[0] || '';
    });

    const handleSubmit = async () => {
        if (!activeSession) return;
        await changeYard(activeSession.craneUsage.id!, newYard);
        setActiveSession(prev => prev ? ({ ...prev, craneUsage: { ...prev.craneUsage, yard: newYard } }) : null);
        onClose();
    };

    return (
         <Modal title="Cambiar de Predio" onClose={onClose}>
            <div className="space-y-4">
                <Select label="Nuevo Predio" value={newYard} onChange={setNewYard} options={(config.YARDS || []).filter(y => y !== activeSession?.craneUsage.yard)} />
                <div className="flex justify-end space-x-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 rounded-md">Cancelar</button>
                    <button onClick={handleSubmit} className="px-4 py-2 bg-green-600 text-white rounded-md">Confirmar</button>
                </div>
            </div>
        </Modal>
    );
}

