                                onClick={() => { processMovementExecution("Revisión en Racks", 2); setRackMultiplierModalOpen(false); }}
                                className="flex flex-col items-center justify-center p-6 bg-teal-600 text-white rounded-2xl shadow-lg hover:bg-teal-700 transition-all active:scale-95 group"
                            >
