                <div className="flex justify-end gap-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-orange-600 text-white rounded-lg font-black shadow-md hover:bg-orange-700 transition-all">Guardar Reporte</button>
                </div>
            </form>
        </Modal>
    );
}

function EndSessionModal({ onClose }: { onClose: () => void }) {
    const { activeSession, logout } = useContext(SessionContext);
    const [finalHourMeter, setFinalHourMeter] = useState('');
    const [error, setError] = useState('');

    const handleEndSession = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession) return;

        const finalValue = Number(finalHourMeter);
        const initialValue = activeSession.craneUsage.startHourMeter;

        if (!finalHourMeter || isNaN(finalValue)) {
            setError(`Ingrese un valor numérico.`);
            return;
        }

        // VALIDACIÓN DE HORÓMETRO AL CERRAR
        const finalDigits = finalHourMeter.replace('.', '').length;
        const initialDigits = initialValue.toString().replace('.', '').length;
        let warnings = [];

        if (finalValue < initialValue) {
            warnings.push(`• El valor final (${finalValue}) es MENOR al inicial (${initialValue}).`);
        }
        if (finalDigits !== initialDigits) {
            warnings.push(`• La cantidad de dígitos (${finalDigits}) es DIFERENTE a la inicial (${initialDigits}).`);
        }

        if (warnings.length > 0) {
            const confirmMsg = `ADVERTENCIA DE SEGURIDAD:\n\n${warnings.join('\n')}\n\n¿Está seguro que el horómetro final es correcto?`;
            if (!window.confirm(confirmMsg)) return;
        }

        try {
            await endCurrentSession(
                activeSession.session.id!,
                activeSession.craneUsage.id!,
                finalValue
            );
            localStorage.removeItem('staktrak_draft_container');
            logout();
        } catch (err) {
            setError('Error al finalizar sesión.');
            console.error(err);
        }
    };

    if (!activeSession) return null;

    return (
        <Modal title="🛑 Finalizar Jornada" onClose={onClose}>
            <form onSubmit={handleEndSession} className="space-y-4">
                <div className="bg-gray-50 p-3 rounded-lg border border-gray-100 text-sm space-y-1">
                    <div className="flex justify-between items-center">
                        <span className="text-gray-500 font-bold">GRÚA:</span>
                        <span className="font-black text-green-700">{activeSession.craneUsage.crane}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-gray-500 font-bold">LECTURA INICIAL:</span>
                        <span className="font-black text-blue-600">{activeSession.craneUsage.startHourMeter}</span>
                    </div>
                </div>
                <Input label="Lectura de Horómetro Final" type="number" value={finalHourMeter} onChange={setFinalHourMeter} required step="any" placeholder="0000.00" />
                {error && <p className="text-sm text-red-600 font-bold">{error}</p>}
                <div className="flex justify-end gap-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-red-600 text-white rounded-lg font-black shadow-md hover:bg-red-700 transition-all">Cerrar Sesión</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeCraneModal({ onClose, fetchMovements, config }: { onClose: () => void, fetchMovements: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [endHourMeter, setEndHourMeter] = useState('');
    const [reason, setReason] = useState(config.CRANE_CHANGE_REASONS?.[0] || '');
    const [reasonDetails, setReasonDetails] = useState('');
    const [newCrane, setNewCrane] = useState(() => {
        if (!activeSession) return '';
        const availableCranes = config.CRANES.filter(c => c !== activeSession.craneUsage.crane);
        return availableCranes[0] || '';
    });
    const [newStartHourMeter, setNewStartHourMeter] = useState('');
    const [lastMeterForNew, setLastMeterForNew] = useState<number | undefined>(undefined);
    const [isContinuing, setIsContinuing] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (newCrane && activeSession) {
            getLatestUsageInSession(activeSession.session.id!, newCrane).then(usage => {
                if (usage && usage.endHourMeter !== undefined) {
                    setNewStartHourMeter(usage.endHourMeter.toString());
                    setLastMeterForNew(usage.endHourMeter);
                    setIsContinuing(true);
                } else {
                    setIsContinuing(false);
                    getLastHourMeterForCrane(newCrane).then(setLastMeterForNew);
                }
            });
        }
    }, [newCrane, activeSession]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const isYardChange = reason === 'Cambio de predio';
        if (!activeSession || (!isYardChange && !endHourMeter) || !reason || !newCrane || !newStartHourMeter) {
            setError('Todos los campos son obligatorios.');
            return;
        }

        const initialMeterOld = activeSession.craneUsage.startHourMeter;
        let currentEndMeter = endHourMeter ? Number(endHourMeter) : initialMeterOld;

        // VALIDACIÓN EQUIPO SALIENTE
        if (endHourMeter) {
            const currentEndDigits = endHourMeter.replace('.', '').length;
            const initialOldDigits = initialMeterOld.toString().replace('.', '').length;
            let warningsOld = [];

            if (currentEndMeter < initialMeterOld) {
                warningsOld.push(`• Valor final (${currentEndMeter}) es MENOR al inicial (${initialMeterOld}).`);
            }
            if (currentEndDigits !== initialOldDigits) {
                warningsOld.push(`• Dígitos (${currentEndDigits}) DIFERENTES a los iniciales (${initialOldDigits}).`);
            }

            if (warningsOld.length > 0) {
                if (!window.confirm(`ADVERTENCIA (Equipo Saliente):\n\n${warningsOld.join('\n')}\n\n¿Desea continuar?`)) return;
            }
        }

        // VALIDACIÓN EQUIPO ENTRANTE
        const newStartVal = Number(newStartHourMeter);
        if (!isContinuing && lastMeterForNew !== undefined) {
            const newStartDigits = newStartHourMeter.replace('.', '').length;
            const lastNewDigits = lastMeterForNew.toString().replace('.', '').length;
            let warningsNew = [];

            if (newStartVal < lastMeterForNew) {
                warningsNew.push(`• Valor inicial (${newStartVal}) es MENOR al último registro (${lastMeterForNew}).`);
            }
            if (newStartDigits !== lastNewDigits) {
                warningsNew.push(`• Dígitos (${newStartDigits}) DIFERENTES a los habituales (${lastNewDigits}).`);
            }

            if (warningsNew.length > 0) {
                if (!window.confirm(`ADVERTENCIA (Equipo Entrante):\n\n${warningsNew.join('\n')}\n\n¿Desea continuar?`)) return;
            }
        }

        try {
            const newCraneUsage = await changeCrane(
                activeSession.craneUsage.id!,
                currentEndMeter,
                reason,
                newCrane,
                activeSession.craneUsage.yard,
                newStartVal,
                activeSession.session.id!,
                reason === 'Falla mecánica' ? reasonDetails : undefined
            );
            setActiveSession({ ...activeSession, craneUsage: newCraneUsage });
            fetchMovements();
            onClose();
        } catch (err) {
            setError('Error al cambiar de grúa.');
            console.error(err);
        }
    };

    const isYardChange = reason === 'Cambio de predio';

    return (
        <Modal title="🔄 Cambio de Equipo" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="bg-red-50 p-3 rounded-lg border border-red-100 text-xs">
                    <p className="font-bold text-red-800 mb-1 uppercase tracking-tight">Equipo Saliente</p>
                    <div className="flex justify-between">
                        <span>GRÚA: <strong className="text-red-700">{activeSession?.craneUsage.crane}</strong></span>
                        <span>INICIAL: <strong className="text-red-700">{activeSession?.craneUsage.startHourMeter}</strong></span>
                    </div>
                </div>
                <Input 
                    label="Lectura Final (máquina actual)" 
                    type="number" 
                    value={endHourMeter} 
                    onChange={setEndHourMeter} 
                    required={!isYardChange} 
                    step="any" 
                    placeholder={isYardChange ? "Opcional para cambio de predio" : "Ingrese horómetro"}
                />
                <Select label="Razón del Cambio" value={reason} onChange={setReason} options={config.CRANE_CHANGE_REASONS || []} />
                {reason === 'Falla mecánica' && (
                     <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Detalle de la Falla</label>
                        <textarea value={reasonDetails} onChange={e => setReasonDetails(e.target.value)} required className="w-full p-2 border rounded-lg bg-gray-50 border-gray-200 text-sm outline-none focus:ring-2 focus:ring-red-500" rows={2} placeholder="Describa brevemente la falla..."/>
                    </div>
                )}
                <div className="w-full h-px bg-gray-100 my-2"></div>

                <div className="bg-green-50 p-3 rounded-lg border border-green-100 text-xs">
                    <p className="font-bold text-green-800 mb-1 uppercase tracking-tight">Equipo Entrante</p>
                    <Select label="Nueva Grúa a Utilizar" value={newCrane} onChange={setNewCrane} options={(config.CRANES || []).filter(c => c !== activeSession?.craneUsage.crane)} />
                </div>

                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Horómetro Inicial (nueva)</label>
                    <input 
                        type="number" 
                        value={newStartHourMeter} 
                        onChange={e => setNewStartHourMeter(e.target.value)} 
                        required 
                        step="any" 
                        readOnly={isContinuing}
                        className={`w-full p-2.5 border rounded-lg shadow-sm font-bold ${isContinuing ? 'bg-green-50 text-green-700 border-green-200 cursor-not-allowed' : 'bg-gray-50 border-gray-200 outline-none focus:ring-2 focus:ring-green-500'}`}
                    />
                    {isContinuing && <p className="text-[10px] text-green-600 font-black mt-1 uppercase tracking-tighter">✓ Continuando sesión previa en este equipo</p>}
                    {!isContinuing && lastMeterForNew !== undefined && (
                        <p className="text-[10px] text-blue-700 font-bold mt-1 bg-blue-50 p-1 rounded flex justify-between">
                            <span>ÚLTIMO REGISTRO:</span>
                            <span>{lastMeterForNew}</span>
                        </p>
                    )}
                </div>
                {error && <p className="text-red-600 text-xs font-bold">{error}</p>}
                <div className="flex justify-end gap-2 pt-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-lg font-black shadow-md hover:bg-green-700 transition-all">Confirmar Cambio</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeYardModal({ onClose, config }: { onClose: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newYard, setNewYard] = useState(activeSession?.craneUsage.yard || '');

    const handleYardChange = async () => {
        if (!activeSession) return;
        try {
            await changeYard(activeSession.craneUsage.id!, newYard);
            setActiveSession({
                ...activeSession,
                craneUsage: { ...activeSession.craneUsage, yard: newYard }
            });
            onClose();
        } catch (error) {
            console.error(error);
        }
    };

    return (
        <Modal title="📍 Cambiar Predio" onClose={onClose}>
            <div className="space-y-4">
                <Select label="Nuevo Predio" value={newYard} onChange={setNewYard} options={config.YARDS || []} />
                <div className="flex justify-end gap-2 pt-4">
                    <button onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button onClick={handleYardChange} className="px-4 py-2 bg-green-600 text-white rounded-lg font-black shadow-md hover:bg-green-700 transition-all">Actualizar Predio</button>
                </div>
            </div>
        </Modal>
    );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session, CraneUsage } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [viewMode, setViewMode] = useState<'main' | 'efficiency'>('main');
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(s => {
                const d = new Date(s.startTime);
                return d >= startDateFilter! && d <= endDateFilter!;
            });
            const sIds = new Set(filteredSessions.map(s => s.id));
            return { 
                sessions: filteredSessions, 
                craneUsages: craneUsages.filter(cu => sIds.has(cu.sessionId)), 
                movements: movements.filter(m => sIds.has(m.sessionId)),
                workshopRecords: workshopRecords.filter(wr => sIds.has(wr.sessionId))
            };
        }
        return { sessions: [], craneUsages: [], movements: [], workshopRecords: [] };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("No hay datos para exportar en este rango.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const clients = config.CLIENTS || [];
        const reasons = config.MOVEMENT_REASONS || [];

        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter) : 0;

            const row: any = {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TURNO': session?.shift || 'N/A',
                'GRÚA': usage.crane,
                'HORÓMETRO INICIAL': usage.startHourMeter,
                'HORÓMETRO FINAL': usage.endHourMeter || 'PENDIENTE',
                'HORAS DE USO': hrsCrane.toFixed(2),
            };

            // Columnas por cliente
            let totalMovs = 0;
            clients.forEach(client => {
                const count = usageMovements.filter(m => m.client === client).length;
                row[`CLIENTE: ${client}`] = count;
                totalMovs += count;
            });
            row['TOTAL MOVIMIENTOS X CLIENTE'] = totalMovs;

            // Columnas por tipo/razón
            reasons.forEach(reason => {
                const count = usageMovements.filter(m => m.reason === reason).length;
                row[`MOTIVO: ${reason}`] = count;
            });
            row['TOTAL MOVIMIENTOS GENERAL'] = usageMovements.length;

            return row;
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado_Maestro');
        XLSX.writeFile(workbook, `Reporte_Consolidado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0 && workshopRecords.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });
        });

        workshopRecords.forEach(wr => {
            const s = sessionMap.get(wr.sessionId);
            allEvents.push({
                timestamp: new Date(wr.timestamp),
                data: {
                    'FECHA': new Date(wr.timestamp).toLocaleDateString(),
                    'HORA': new Date(wr.timestamp).toLocaleTimeString(),
                    'TIPO': 'TALLER MECÁNICO',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': wr.crane,
                    'PREDIO': 'TALLER',
                    'CLIENTE': 'SISTEMA',
                    'CONTENEDOR/REF': 'SERVICIO TÉCNICO',
                    'ACCION': 'Reparación / Mantenimiento',
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': wr.details
                }
            });
        });

        craneUsages.forEach(cu => {
            if (cu.endTime && cu.changeReason) {
                const s = sessionMap.get(cu.sessionId);
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'CAMBIO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': 'SISTEMA',
                        'CONTENEDOR/REF': `CAMBIO: ${cu.changeReason}`,
                        'ACCION': 'Finalización de uso',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason,
                        'NOTAS MECÁNICO / TALLER': ''
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detallado');
        XLSX.writeFile(workbook, 'ReporteDetallado_Completo.xlsx');
    };

    if (viewMode === 'efficiency') {
        return <EfficiencyDashboard onBack={() => setViewMode('main')} />;
    }

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-green-600">
                <div className="flex items-center gap-4">
                    <div className="bg-green-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Panel Administrativo</h1>
                        <p className="text-sm font-bold text-green-600">Gestión de Operaciones Portuarias</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setViewMode('efficiency')} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center gap-2">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         DASHBOARD EFICIENCIA
                    </button>
                    <button onClick={() => setView('LOGIN')} className="px-6 py-2.5 bg-gray-100 text-gray-600 rounded-xl hover:bg-gray-200 font-bold transition-all">Regresar</button>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Consulta de Contenedor" icon="🔍">
                    <form onSubmit={handleSearch} className="flex gap-3 mb-6">
                        <input type="text" value={containerNumber} onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} className="flex-grow p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-mono text-xl font-bold tracking-widest focus:border-green-500 outline-none" placeholder="7 DÍGITOS"/>
                        <button type="submit" className="px-8 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all" disabled={isLoading}>BUSCAR</button>
                    </form>
                    {searchResult !== undefined && (
                        <div className="p-6 bg-green-50/50 border-2 border-green-100 rounded-2xl animate-in fade-in zoom-in duration-300">
                            {searchResult === null ? (
                                <p className="text-center text-gray-500 font-bold py-4">No se encontraron registros para este contenedor.</p>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex justify-between items-center border-b border-green-100 pb-2">
                                        <span className="text-xs font-black text-green-800 uppercase">Último Movimiento</span>
                                        <span className="text-sm font-bold bg-green-600 text-white px-2 py-1 rounded">{new Date(searchResult.timestamp).toLocaleDateString()}</span>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <MetricItem label="Operador" value={searchResult.operator} />
                                        <MetricItem label="Hora" value={new Date(searchResult.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} />
                                        <MetricItem label="Grúa" value={searchResult.crane} />
                                        <MetricItem label="Motivo" value={searchResult.reason} />
                                        <div className="col-span-2">
                                            <MetricItem label="Cliente" value={searchResult.client} />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </AdminSection>

                <AdminSection title="Generación de Reportes Excel" icon="📊">
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-gray-500 uppercase mb-2">Período de Análisis</label>
                                <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-bold text-gray-700 focus:border-green-500 outline-none">
                                    <option value="all">Todo el Historial</option>
                                    <option value="24h">Últimas 24 Horas</option>
                                    <option value="7d">Últimos 7 Días</option>
                                    <option value="custom">Rango Personalizado</option>
                                </select>
                            </div>
                            {dateRange === 'custom' && (
                                <div className="space-y-2">
                                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                </div>
                            )}
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4">
                             <button onClick={handleExportConsolidated} className="flex-1 py-4 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7.414A2 2 0 0015.414 6L12 2.586A2 2 0 0010.586 2H6zm5 6a1 1 0 10-2 0v3.586l-1.293-1.293a1 1 0 10-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 11.586V8z" clipRule="evenodd" /></svg>
                                 EXPORTAR CONSOLIDADO
                             </button>
                             <button onClick={handleExportDetailed} className="flex-1 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" /></svg>
                                 EXPORTAR DETALLADO
                             </button>
                        </div>
                    </div>
                </AdminSection>
            </div>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

function MetricItem({ label, value }: { label: string; value: string }) {
    return (
        <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
            <p className="text-sm font-bold text-gray-800">{value}</p>
        </div>
    );
}

function EfficiencyDashboard({ onBack }: { onBack: () => void }) {
    const [data, setData] = useState<{sessions: Session[], usages: CraneUsage[], movements: Movement[]}>({sessions:[], usages:[], movements:[]});
    const [filter, setFilter] = useState<'day' | 'week' | 'month'>('day');

    useEffect(() => {
        const fetch = async () => {
            const all = await getAllDataForExport();
            const now = new Date();
            let start = new Date();
            if (filter === 'day') start.setHours(0,0,0,0);
            else if (filter === 'week') {
                const day = now.getDay();
                start = new Date(now.getTime() - day * 24 * 60 * 60 * 1000);
                start.setHours(0,0,0,0);
            } else {
                start = new Date(now.getFullYear(), now.getMonth(), 1);
            }

            const filteredSessions = all.sessions.filter(s => new Date(s.startTime) >= start);
            const sIds = new Set(filteredSessions.map(s => s.id));
            setData({
                sessions: filteredSessions,
                usages: all.craneUsages.filter(cu => sIds.has(cu.sessionId)),
                movements: all.movements.filter(m => sIds.has(m.sessionId))
            });
        };
        fetch();
    }, [filter]);

    const stats = useMemo(() => {
        const opStats: Record<string, {movs: number, hours: number}> = {};
        const craneStats: Record<string, {movs: number, hours: number}> = {};

        data.usages.forEach(u => {
            const session = data.sessions.find(s => s.id === u.sessionId);
            const op = session?.operator || 'Desconocido';
            const hours = u.endHourMeter && u.startHourMeter ? (u.endHourMeter - u.startHourMeter) : 0;
            const movs = data.movements.filter(m => m.craneUsageId === u.id).length;

            if (!opStats[op]) opStats[op] = {movs: 0, hours: 0};
            opStats[op].movs += movs;
            opStats[op].hours += hours;

            if (!craneStats[u.crane]) craneStats[u.crane] = {movs: 0, hours: 0};
            craneStats[u.crane].movs += movs;
            craneStats[u.crane].hours += hours;
        });

        return { operators: opStats, cranes: craneStats };
    }, [data]);

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl animate-in fade-in slide-in-from-right duration-500">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-blue-600">
                <div className="flex items-center gap-4">
                    <div className="bg-blue-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Eficiencia Gerencial</h1>
                        <p className="text-sm font-bold text-blue-600">Indicadores de Desempeño (KPIs)</p>
                    </div>
                </div>
                <div className="flex gap-2 bg-gray-100 p-1.5 rounded-xl">
                    {(['day', 'week', 'month'] as const).map(f => (
                        <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${filter === f ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                            {f === 'day' ? 'Hoy' : f === 'week' ? 'Semana' : 'Mes'}
                        </button>
                    ))}
                    <button onClick={onBack} className="ml-4 px-4 py-2 bg-gray-800 text-white rounded-lg text-xs font-black uppercase hover:bg-black transition-all">SALIR</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <KPICard title="Total Movimientos" value={data.movements.length} color="blue" />
                <KPICard title="Horas Totales" value={Object.values(stats.cranes).reduce((a,b) => a+b.hours, 0).toFixed(1)} color="green" />
                <KPICard title="Promedio MPH" value={data.movements.length > 0 ? (data.movements.length / Object.values(stats.cranes).reduce((a,b) => a+b.hours, 0)).toFixed(1) : 0} color="orange" unit="mov/hr" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Rendimiento por Operador (MPH)" icon="👤">
                    <div className="space-y-4">
                        {Object.entries(stats.operators).length > 0 ? Object.entries(stats.operators).sort((a,b) => (b[1].movs/b[1].hours) - (a[1].movs/a[1].hours)).map(([name, s]) => {
                            const mph = s.hours > 0 ? (s.movs / s.hours) : 0;
                            return (
                                <EfficiencyBar key={name} label={name} value={mph} max={25} />
                            );
                        }) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>

                <AdminSection title="Uso por Grúa (Horas)" icon="🏗️">
                    <div className="space-y-4">
                        {Object.entries(stats.cranes).length > 0 ? Object.entries(stats.cranes).sort((a,b) => b[1].hours - a[1].hours).map(([crane, s]) => (
                            <EfficiencyBar key={crane} label={crane} value={s.hours} max={24} color="bg-green-500" />
                        )) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>
            </div>
        </div>
    );
}

function KPICard({ title, value, color, unit }: { title: string; value: string | number; color: string; unit?: string }) {
    const colors: any = { blue: 'text-blue-600', green: 'text-green-600', orange: 'text-orange-600' };
    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg border-l-8 border-current text-gray-800" style={{borderColor: color === 'blue' ? '#2563eb' : color === 'green' ? '#16a34a' : '#ea580c'}}>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{title}</p>
            <p className={`text-4xl font-black ${colors[color]}`}>{value} <span className="text-sm font-bold text-gray-400">{unit}</span></p>
        </div>
    );
}

function EfficiencyBar({ label, value, max, color = "bg-blue-600" }: { label: string; value: number; max: number; color?: string }) {
    const percentage = Math.min((value / max) * 100, 100);
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-xs font-bold uppercase">
                <span className="text-gray-700">{label}</span>
                <span className="text-gray-900">{value.toFixed(1)}</span>
            </div>
            <div className="w-full bg-gray-100 h-4 rounded-full overflow-hidden border border-gray-200">
                <div className={`${color} h-full transition-all duration-1000`} style={{ width: `${percentage}%` }}></div>
            </div>
        </div>
    );
}

const AdminSection: React.FC<{ title: string; icon?: string; children: React.ReactNode }> = ({ title, icon, children }) => (
    <section className="bg-white p-8 rounded-3xl shadow-xl border border-gray-50">
        <h2 className="text-xl font-black mb-6 text-gray-800 flex items-center gap-3 uppercase tracking-tighter">
            <span className="text-2xl">{icon}</span>
            {title}
        </h2>
        {children}
    </section>
);

const ConfigManager: React.FC<{ config: Record<AppConfigKey, string[]>; onConfigChange: () => void }> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);
    useEffect(() => { setEditableConfig(config); }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            setEditableConfig(prev => ({ ...prev, [key]: [...prev[key], value] }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        setEditableConfig(prev => ({ ...prev, [key]: prev[key].filter(i => i !== value) }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`"${key}" actualizado correctamente.`);
            onConfigChange();
        } catch (e) { alert("Error al guardar."); }
    };

    return (
        <AdminSection title="Mantenimiento de Variables del Sistema" icon="⚙️">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection key={key} configKey={key as AppConfigKey} values={editableConfig[key as AppConfigKey]} onAddItem={handleAddItem} onRemoveItem={handleRemoveItem} onSave={handleSave} />
                ))}
            </div>
        </AdminSection>
    );
};

const ConfigSection: React.FC<{ configKey: AppConfigKey; values: string[]; onAddItem: any; onRemoveItem: any; onSave: any }> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');
