import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session, CraneUsage } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [viewMode, setViewMode] = useState<'main' | 'efficiency'>('main');
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(s => {
                const d = new Date(s.startTime);
                return d >= startDateFilter! && d <= endDateFilter!;
            });
            const sIds = new Set(filteredSessions.map(s => s.id));
            return { 
                sessions: filteredSessions, 
                craneUsages: craneUsages.filter(cu => sIds.has(cu.sessionId)), 
                movements: movements.filter(m => sIds.has(m.sessionId)),
                workshopRecords: workshopRecords.filter(wr => sIds.has(wr.sessionId))
            };
        }
        return { sessions: [], craneUsages: [], movements: [], workshopRecords: [] };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("No hay datos para exportar en este rango.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const clients = config.CLIENTS || [];
        const reasons = config.MOVEMENT_REASONS || [];

        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter) : 0;

            const row: any = {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TURNO': session?.shift || 'N/A',
                'GRÚA': usage.crane,
                'HORÓMETRO INICIAL': usage.startHourMeter,
                'HORÓMETRO FINAL': usage.endHourMeter || 'PENDIENTE',
                'HORAS DE USO': hrsCrane.toFixed(2),
            };

            // Columnas por cliente
            let totalMovs = 0;
            clients.forEach(client => {
                const count = usageMovements.filter(m => m.client === client).length;
                row[`CLIENTE: ${client}`] = count;
                totalMovs += count;
            });
            row['TOTAL MOVIMIENTOS X CLIENTE'] = totalMovs;

            // Columnas por tipo/razón
            reasons.forEach(reason => {
                const count = usageMovements.filter(m => m.reason === reason).length;
                row[`MOTIVO: ${reason}`] = count;
            });
            row['TOTAL MOVIMIENTOS GENERAL'] = usageMovements.length;

            return row;
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado_Maestro');
        XLSX.writeFile(workbook, `Reporte_Consolidado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0 && workshopRecords.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });
        });

        workshopRecords.forEach(wr => {
            const s = sessionMap.get(wr.sessionId);
            allEvents.push({
                timestamp: new Date(wr.timestamp),
                data: {
                    'FECHA': new Date(wr.timestamp).toLocaleDateString(),
                    'HORA': new Date(wr.timestamp).toLocaleTimeString(),
                    'TIPO': 'TALLER MECÁNICO',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': wr.crane,
                    'PREDIO': 'TALLER',
                    'CLIENTE': 'SISTEMA',
                    'CONTENEDOR/REF': 'SERVICIO TÉCNICO',
                    'ACCION': 'Reparación / Mantenimiento',
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': wr.details
                }
            });
        });

        craneUsages.forEach(cu => {
            if (cu.endTime && cu.changeReason) {
                const s = sessionMap.get(cu.sessionId);
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'CAMBIO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': 'SISTEMA',
                        'CONTENEDOR/REF': `CAMBIO: ${cu.changeReason}`,
                        'ACCION': 'Finalización de uso',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason,
                        'NOTAS MECÁNICO / TALLER': ''
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detallado');
        XLSX.writeFile(workbook, 'ReporteDetallado_Completo.xlsx');
    };

    if (viewMode === 'efficiency') {
        return <EfficiencyDashboard onBack={() => setViewMode('main')} />;
    }

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-green-600">
                <div className="flex items-center gap-4">
                    <div className="bg-green-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Panel Administrativo</h1>
                        <p className="text-sm font-bold text-green-600">Gestión de Operaciones Portuarias</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setViewMode('efficiency')} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center gap-2">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         DASHBOARD EFICIENCIA
                    </button>
                    <button onClick={() => setView('LOGIN')} className="px-6 py-2.5 bg-gray-100 text-gray-600 rounded-xl hover:bg-gray-200 font-bold transition-all">Regresar</button>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Consulta de Contenedor" icon="🔍">
                    <form onSubmit={handleSearch} className="flex gap-3 mb-6">
                        <input type="text" value={containerNumber} onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} className="flex-grow p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-mono text-xl font-bold tracking-widest focus:border-green-500 outline-none" placeholder="7 DÍGITOS"/>
                        <button type="submit" className="px-8 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all" disabled={isLoading}>BUSCAR</button>
                    </form>
                    {searchResult !== undefined && (
                        <div className="p-6 bg-green-50/50 border-2 border-green-100 rounded-2xl animate-in fade-in zoom-in duration-300">
                            {searchResult === null ? (
                                <p className="text-center text-gray-500 font-bold py-4">No se encontraron registros para este contenedor.</p>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex justify-between items-center border-b border-green-100 pb-2">
                                        <span className="text-xs font-black text-green-800 uppercase">Último Movimiento</span>
                                        <span className="text-sm font-bold bg-green-600 text-white px-2 py-1 rounded">{new Date(searchResult.timestamp).toLocaleDateString()}</span>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <MetricItem label="Operador" value={searchResult.operator} />
                                        <MetricItem label="Hora" value={new Date(searchResult.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} />
                                        <MetricItem label="Grúa" value={searchResult.crane} />
                                        <MetricItem label="Motivo" value={searchResult.reason} />
                                        <div className="col-span-2">
                                            <MetricItem label="Cliente" value={searchResult.client} />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </AdminSection>

                <AdminSection title="Generación de Reportes Excel" icon="📊">
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-gray-500 uppercase mb-2">Período de Análisis</label>
                                <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-bold text-gray-700 focus:border-green-500 outline-none">
                                    <option value="all">Todo el Historial</option>
                                    <option value="24h">Últimas 24 Horas</option>
                                    <option value="7d">Últimos 7 Días</option>
                                    <option value="custom">Rango Personalizado</option>
                                </select>
                            </div>
                            {dateRange === 'custom' && (
                                <div className="space-y-2">
                                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                </div>
                            )}
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4">
                             <button onClick={handleExportConsolidated} className="flex-1 py-4 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7.414A2 2 0 0015.414 6L12 2.586A2 2 0 0010.586 2H6zm5 6a1 1 0 10-2 0v3.586l-1.293-1.293a1 1 0 10-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 11.586V8z" clipRule="evenodd" /></svg>
                                 EXPORTAR CONSOLIDADO
                             </button>
                             <button onClick={handleExportDetailed} className="flex-1 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" /></svg>
                                 EXPORTAR DETALLADO
                             </button>
                        </div>
                    </div>
                </AdminSection>
            </div>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

function MetricItem({ label, value }: { label: string; value: string }) {
    return (
        <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
            <p className="text-sm font-bold text-gray-800">{value}</p>
        </div>
    );
}

// Fixed EfficiencyStat interface to define statistical shape.
interface EfficiencyStat {
    movs: number;
    hours: number;
}

function EfficiencyDashboard({ onBack }: { onBack: () => void }) {
    const [data, setData] = useState<{sessions: Session[], usages: CraneUsage[], movements: Movement[]}>({sessions:[], usages:[], movements:[]});
    const [filter, setFilter] = useState<'day' | 'week' | 'month'>('day');

    useEffect(() => {
        const fetch = async () => {
            const all = await getAllDataForExport();
            const now = new Date();
            let start = new Date();
            if (filter === 'day') start.setHours(0,0,0,0);
            else if (filter === 'week') {
                const day = now.getDay();
                start = new Date(now.getTime() - day * 24 * 60 * 60 * 1000);
                start.setHours(0,0,0,0);
            } else {
                start = new Date(now.getFullYear(), now.getMonth(), 1);
            }

            const filteredSessions = all.sessions.filter(s => new Date(s.startTime) >= start);
            const sIds = new Set(filteredSessions.map(s => s.id));
            setData({
                sessions: filteredSessions,
                usages: all.craneUsages.filter(cu => sIds.has(cu.sessionId)),
                movements: all.movements.filter(m => sIds.has(m.sessionId))
            });
        };
        fetch();
    }, [filter]);

    const stats = useMemo(() => {
        const opStats: Record<string, EfficiencyStat> = {};
        const craneStats: Record<string, EfficiencyStat> = {};

        data.usages.forEach(u => {
            const session = data.sessions.find(s => s.id === u.sessionId);
            const op = session?.operator || 'Desconocido';
            const hours = u.endHourMeter && u.startHourMeter ? (u.endHourMeter - u.startHourMeter) : 0;
            const movs = data.movements.filter(m => m.craneUsageId === u.id).length;

            if (!opStats[op]) opStats[op] = {movs: 0, hours: 0};
            opStats[op].movs += movs;
            opStats[op].hours += hours;

            if (!craneStats[u.crane]) craneStats[u.crane] = {movs: 0, hours: 0};
            craneStats[u.crane].movs += movs;
            craneStats[u.crane].hours += hours;
        });

        return { operators: opStats, cranes: craneStats };
    }, [data]);

    // Computed total hours helper to avoid repetition and unknown types.
    const totalHours = useMemo(() => 
        Object.values(stats.cranes).reduce((acc: number, curr: EfficiencyStat) => acc + curr.hours, 0)
    , [stats.cranes]);

    return (
