                                <tr key={m.id} className="hover:bg-green-50/30 transition-colors">
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-600">{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-green-700 font-mono tracking-wider">{m.containerNumber}</td>
