  oldCraneUsageId: number, endHourMeter: number, changeReason: string, newCrane: string,
  newYard: string, newStartHourMeter: number, sessionId: number, changeReasonDetails?: string
): Promise<CraneUsage> => {
  const now = new Date();
  return await db.transaction('rw', db.craneUsages, async () => {
    const oldUsage = await db.craneUsages.get(oldCraneUsageId);
    await db.craneUsages.update(oldCraneUsageId, { endHourMeter, changeReason, changeReasonDetails, endTime: now });

    const newCraneUsage: CraneUsage = { sessionId, crane: newCrane, yard: newYard, startHourMeter: newStartHourMeter, startTime: now };
    const newCraneUsageId = await db.craneUsages.add(newCraneUsage);
    newCraneUsage.id = newCraneUsageId;

    if (oldUsage) {
        enqueueSync('CRANE_CHANGE', {
            fecha: now.toLocaleDateString(),
            hora: now.toLocaleTimeString(),
            cliente: "",
            contenedor: "",
            grua_saliente: oldUsage.crane,
            horimetro_final_saliente: endHourMeter,
            motivo: changeReason,
            detalles: changeReasonDetails,
            grua_entrante: newCrane,
            horimetro_inicial_entrante: newStartHourMeter
        });
    }

    return newCraneUsage;
  });
};

