    </div>
);

const Select: React.FC<{ label: string; value: string; onChange: (v: string) => void; options: string[] }> = ({ label, value, onChange, options }) => (
    <div>
        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{label}</label>
        <select
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full px-3 py-2 text-gray-900 bg-gray-50 border border-gray-200 rounded-lg shadow-sm focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none transition-all"
        >
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default function OperatorDashboard({ setView }: OperatorDashboardProps) {
    const { activeSession, setActiveSession, logout } = useContext(SessionContext);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
        MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });
    const [client, setClient] = useState('');
    const [containerNumber, setContainerNumber] = useState(() => localStorage.getItem('staktrak_draft_container') || '');
    const [recentMovements, setRecentMovements] = useState<Movement[]>([]);
    const [totalMovements, setTotalMovements] = useState(0);
    const [pendingSync, setPendingSync] = useState(0);
    const [isCraneModalOpen, setCraneModalOpen] = useState(false);
    const [isYardModalOpen, setYardModalOpen] = useState(false);
    const [isWorkshopModalOpen, setWorkshopModalOpen] = useState(false);
    const [isEndSessionModalOpen, setEndSessionModalOpen] = useState(false);
    const [isRackMultiplierModalOpen, setRackMultiplierModalOpen] = useState(false);
    const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });
    const [showOnlyCurrentCrane, setShowOnlyCurrentCrane] = useState(false);

    useEffect(() => {
        const fetchConfig = async () => {
            const appConfig = await getAppConfig();
            setConfig(appConfig);
        };
        fetchConfig();
    }, []);

    useEffect(() => {
        localStorage.setItem('staktrak_draft_container', containerNumber);
    }, [containerNumber]);

    const updateSyncStatus = useCallback(async () => {
        const count = await getPendingSyncCount();
        setPendingSync(count);
    }, []);

    useEffect(() => {
        const interval = setInterval(updateSyncStatus, 5000);
        updateSyncStatus();
        return () => clearInterval(interval);
    }, [updateSyncStatus]);

    const fetchMovements = useCallback(async () => {
        if (activeSession?.session.id) {
            const craneFilter = showOnlyCurrentCrane ? activeSession.craneUsage.id : undefined;
            const movements = await getRecentMovements(activeSession.session.id, 5, craneFilter);
            setRecentMovements(movements);
            const count = await countSessionMovements(activeSession.session.id);
            setTotalMovements(count);
        }
    }, [activeSession, showOnlyCurrentCrane]);

    useEffect(() => {
        if (activeSession) {
            if (config.CLIENTS.length > 0) {
              setClient(activeSession.session.client || config.CLIENTS[0]);
            }
            fetchMovements();
        } else {
            setView('LOGIN');
        }
    }, [activeSession, fetchMovements, setView, config.CLIENTS]);

    const showStatusMessage = (type: 'success' | 'error', text: string) => {
        setStatusMessage({ type, text });
        setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
    };

    const handleLogMovement = async (reason: string) => {
        if (!activeSession) return;
        if (!/^\d{7}$/.test(containerNumber)) {
            showStatusMessage('error', 'El número de contenedor debe tener 7 dígitos.');
            return;
        }
        if (reason === "Revisión en Racks") {
            setRackMultiplierModalOpen(true);
            return;
        }
        await processMovementExecution(reason, 1);
    };

    const processMovementExecution = async (reason: string, count: number) => {
        if (!activeSession) return;
        try {
            const getBaseMovement = () => ({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                client,
                containerNumber,
                reason,
                yard: activeSession.craneUsage.yard,
                crane: activeSession.craneUsage.crane,
                operator: activeSession.session.operator,
            });

            for (let i = 0; i < count; i++) {
                await addMovement(getBaseMovement());
            }

            showStatusMessage('success', `Registrado: ${reason} (${count} mov).`);
            setContainerNumber('');
            localStorage.removeItem('staktrak_draft_container');
            fetchMovements();
            updateSyncStatus();
        } catch (error) {
            showStatusMessage('error', 'Error al registrar el movimiento.');
            console.error(error);
        }
    };

    if (!activeSession) return null;

    const { session, craneUsage } = activeSession;

    return (
        <div className="container mx-auto p-4 space-y-6 text-gray-900">
             <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 flex items-center justify-center bg-green-50 rounded-lg">
                        <svg className="w-8 h-8 text-green-700" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M3 21h18M5 21V7l8-4v18M13 21V3l8 4v14" />
                        </svg>
                    </div>
                    <div className="text-left">
                        <h1 className="text-2xl font-black text-green-700 leading-none uppercase tracking-tighter">
                          PANEL DE CONTROL GRUAS
                        </h1>
                        <div className="flex items-center gap-2 mt-1">
                            <p className="text-xs italic text-gray-400 font-medium">By R. Fonseca</p>
                            {pendingSync > 0 ? (
                                <span className="flex items-center gap-1 px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded text-[10px] font-bold animate-pulse">
                                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-11a1 1 0 10-2 0v2H7a1 1 0 100 2h2v2a1 1 0 102 0v-2h2a1 1 0 100-2h-2V7z"/></svg>
                                    NUBE: {pendingSync} PEND.
                                </span>
                            ) : (
                                <span className="flex items-center gap-1 px-1.5 py-0.5 bg-green-100 text-green-700 rounded text-[10px] font-bold">
                                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>
                                    NUBE: OK
                                </span>
                            )}
                        </div>
                    </div>
                </div>
                <div>
                    <button onClick={() => setEndSessionModalOpen(true)} className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-bold shadow-sm transition-colors">Finalizar Sesión</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-1 bg-white p-6 rounded-lg shadow-md border">
                    <h3 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <span className="text-green-600">ℹ️</span> Información
                    </h3>
                    <div className="space-y-2 text-sm mb-4">
                        <p><span className="text-gray-500 font-medium">Operador:</span> <span className="font-bold">{session.operator}</span></p>
                        <p><span className="text-gray-500 font-medium">Turno:</span> <span className="font-bold">{session.shift}</span></p>
                        <p><span className="text-gray-500 font-medium">Grúa:</span> <span className="font-bold text-green-700">{craneUsage.crane}</span></p>
                        <p><span className="text-gray-500 font-medium">Predio:</span> <span className="font-bold">{craneUsage.yard}</span></p>
                    </div>
                    <button 
                        onClick={() => setShowOnlyCurrentCrane(!showOnlyCurrentCrane)} 
                        className={`w-full py-2 px-4 rounded-lg font-bold text-xs uppercase transition-all shadow-sm flex items-center justify-center gap-2 border ${showOnlyCurrentCrane ? 'bg-green-700 text-white border-green-800' : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-gray-100'}`}
                    >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                        {showOnlyCurrentCrane ? 'Viendo esta grúa' : 'Ver por Grúa'}
                    </button>
                    <div className="mt-6 bg-blue-50 p-4 rounded-xl text-center border border-blue-100">
                        <p className="text-xs font-bold text-blue-800 uppercase tracking-widest">Movimientos de hoy</p>
                        <p className="text-5xl font-black text-blue-600 mt-1">{totalMovements}</p>
                    </div>
                    <div className="mt-6 flex flex-col gap-2">
                        <button onClick={() => setCraneModalOpen(true)} className="w-full px-3 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 shadow-sm transition-all">Cambiar Grúa</button>
                        <button onClick={() => setYardModalOpen(true)} className="w-full px-3 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 shadow-sm transition-all">Cambiar Predio</button>
                        <button onClick={() => setWorkshopModalOpen(true)} className="w-full px-3 py-2 bg-orange-500 text-white rounded-lg text-sm font-black hover:bg-orange-600 flex items-center justify-center shadow-sm transition-all">
                            <span className="mr-2">🔧</span> TALLER MEC
                        </button>
                    </div>
                </div>

                <div className="md:col-span-2 bg-white p-6 rounded-lg shadow-md border">
                    <h3 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <span className="text-green-600">🏗️</span> Registrar Movimiento
                    </h3>
                    <div className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Cliente</label>
                                <select value={client} onChange={(e) => setClient(e.target.value)} disabled={session.workType === 'Operación de Barco'} className="w-full p-2.5 border rounded-lg bg-gray-50 border-gray-200 disabled:opacity-50 font-medium">
                                    {(config.CLIENTS || []).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1"># Contenedor (7 dígitos)</label>
                                <input type="text" value={containerNumber} onChange={(e) => {
                                        const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 7);
                                        setContainerNumber(value);
                                    }} pattern="\d{7}" placeholder="0000000" className="w-full p-2.5 border rounded-lg bg-gray-50 border-gray-200 font-mono text-lg font-bold text-center tracking-widest focus:ring-2 focus:ring-green-500 outline-none transition-all"/>
                            </div>
                        </div>
                        <div className="pt-2">
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-3">Seleccione el motivo</label>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                                {(config.MOVEMENT_REASONS || []).map((reason) => {
                                    const { emoji, color } = getReasonStyle(reason);
                                    return (
                                        <button
                                            key={reason}
                                            type="button"
                                            onClick={() => handleLogMovement(reason)}
                                            className={`p-3 rounded-xl text-white flex flex-col items-center justify-center transition-all transform active:scale-90 hover:brightness-110 shadow-sm ${color}`}
                                        >
                                            <span className="text-2xl mb-1">{emoji}</span>
                                            <span className="text-xs font-black uppercase text-center">{reason}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                    {statusMessage.text && (
                        <div className={`mt-6 p-3 rounded-lg text-center font-bold text-sm animate-bounce ${statusMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                            {statusMessage.text}
                        </div>
                    )}
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-md border">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-semibold flex items-center gap-2">
                        <span className="text-green-600">📜</span> 
                        {showOnlyCurrentCrane ? `Últimos 5 de ${craneUsage.crane}` : 'Últimos 5 Movimientos (General)'}
                    </h3>
                    {showOnlyCurrentCrane && (
                        <span className="px-3 py-1 bg-green-100 text-green-800 text-[10px] font-black uppercase rounded-full border border-green-200 animate-pulse">
                            Filtro Activo
                        </span>
                    )}
                </div>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-100">
                        <thead>
                            <tr className="bg-gray-50">
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Hora</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Contenedor</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Cliente</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Razón</th>
                                {!showOnlyCurrentCrane && <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Grúa</th>}
