    );
}

function WorkshopModal({ onClose, showStatus }: { onClose: () => void, showStatus: (type: 'success' | 'error', text: string) => void }) {
    const { activeSession } = useContext(SessionContext);
    const [details, setDetails] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession || !details) return;

        try {
            await addWorkshopRecord({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                crane: activeSession.craneUsage.crane,
                details
            });
            showStatus('success', 'Reporte técnico guardado.');
            onClose();
        } catch (err) {
            setError('Error al guardar reporte técnico.');
        }
    };

    return (
        <Modal title="🔧 TALLER MECÁNICO" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <p className="text-sm text-gray-600">Registre arreglos o mantenimiento para la grúa: <strong className="text-orange-600">{activeSession?.craneUsage.crane}</strong>.</p>
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Comentarios técnicos</label>
                    <textarea 
                        value={details} 
                        onChange={e => setDetails(e.target.value)} 
                        required 
                        className="w-full p-2.5 border rounded-lg bg-gray-50 border-gray-200 outline-none focus:ring-2 focus:ring-orange-500" 
                        rows={5} 
                        placeholder="Describa el trabajo realizado..."
                    />
                </div>
                {error && <p className="text-red-500 text-sm font-bold">{error}</p>}
                <div className="flex justify-end gap-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-orange-600 text-white rounded-lg font-black shadow-md hover:bg-orange-700 transition-all">Guardar Reporte</button>
                </div>
            </form>
        </Modal>
    );
}

function EndSessionModal({ onClose }: { onClose: () => void }) {
    const { activeSession, logout } = useContext(SessionContext);
    const [finalHourMeter, setFinalHourMeter] = useState('');
    const [error, setError] = useState('');

    const handleEndSession = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeSession) return;

        const normalizedValue = finalHourMeter.replace(',', '.');
        const finalValue = parseFloat(normalizedValue);
        const initialValue = activeSession.craneUsage.startHourMeter;

        if (!finalHourMeter || isNaN(finalValue)) {
            setError(`Ingrese un valor numérico.`);
            return;
        }

        const finalDigits = normalizedValue.split('.')[0].length;
        let warnings = [];

        if (finalValue < initialValue) {
            warnings.push(`• El valor final (${finalHourMeter}) es MENOR al inicial (${initialValue.toString().replace('.', ',')}).`);
        }
        if (finalDigits > 8) {
            warnings.push(`• El valor tiene más de 8 dígitos enteros.`);
        }

        if (warnings.length > 0) {
            const confirmMsg = `ADVERTENCIA DE SEGURIDAD:\n\n${warnings.join('\n')}\n\n¿Está seguro que el horómetro final es correcto?`;
            if (!window.confirm(confirmMsg)) return;
        }

        try {
            await endCurrentSession(
                activeSession.session.id!,
                activeSession.craneUsage.id!,
                finalValue
            );
            localStorage.removeItem('staktrak_draft_container');
            logout();
        } catch (err) {
            setError('Error al finalizar sesión.');
            console.error(err);
        }
    };

    if (!activeSession) return null;

    return (
        <Modal title="🛑 Finalizar Jornada" onClose={onClose}>
            <form onSubmit={handleEndSession} className="space-y-4">
                <div className="bg-gray-50 p-3 rounded-lg border border-gray-100 text-sm space-y-1">
                    <div className="flex justify-between items-center">
                        <span className="text-gray-500 font-bold">GRÚA:</span>
                        <span className="font-black text-green-700">{activeSession.craneUsage.crane}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-gray-500 font-bold">LECTURA INICIAL:</span>
                        <span className="font-black text-blue-600">{activeSession.craneUsage.startHourMeter.toString().replace('.', ',')}</span>
                    </div>
                </div>
                <Input label="Lectura de Horómetro Final" type="text" value={finalHourMeter} onChange={(val) => setFinalHourMeter(val.replace(/[^0-9,]/g, ''))} required placeholder="0000,00" />
                {error && <p className="text-sm text-red-600 font-bold">{error}</p>}
                <div className="flex justify-end gap-2 pt-4">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-red-600 text-white rounded-lg font-black shadow-md hover:bg-red-700 transition-all">Cerrar Sesión</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeCraneModal({ onClose, fetchMovements, config }: { onClose: () => void, fetchMovements: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [endHourMeter, setEndHourMeter] = useState('');
    const [reason, setReason] = useState(config.CRANE_CHANGE_REASONS?.[0] || '');
    const [reasonDetails, setReasonDetails] = useState('');
    const [newCrane, setNewCrane] = useState(() => {
        if (!activeSession) return '';
        const availableCranes = config.CRANES.filter(c => c !== activeSession.craneUsage.crane);
        return availableCranes[0] || '';
    });
    const [newStartHourMeter, setNewStartHourMeter] = useState('');
    const [lastMeterForNew, setLastMeterForNew] = useState<number | undefined>(undefined);
    const [isContinuing, setIsContinuing] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (newCrane && activeSession) {
            getLatestUsageInSession(activeSession.session.id!, newCrane).then(usage => {
                if (usage && usage.endHourMeter !== undefined) {
                    setNewStartHourMeter(usage.endHourMeter.toString().replace('.', ','));
                    setLastMeterForNew(usage.endHourMeter);
                    setIsContinuing(true);
                } else {
                    setIsContinuing(false);
                    getLastHourMeterForCrane(newCrane).then(setLastMeterForNew);
                }
            });
        }
    }, [newCrane, activeSession]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const isYardChange = reason === 'Cambio de predio';
        if (!activeSession || (!isYardChange && !endHourMeter) || !reason || !newCrane || !newStartHourMeter) {
            setError('Todos los campos son obligatorios.');
            return;
        }

        const normalizedEnd = endHourMeter.replace(',', '.');
        const normalizedNewStart = newStartHourMeter.replace(',', '.');
        const currentEndMeter = endHourMeter ? parseFloat(normalizedEnd) : activeSession.craneUsage.startHourMeter;
        const newStartVal = parseFloat(normalizedNewStart);

        if (isNaN(newStartVal)) {
            setError('Horómetro inicial inválido.');
            return;
        }

        const initialMeterOld = activeSession.craneUsage.startHourMeter;

        if (endHourMeter) {
            const currentEndDigits = normalizedEnd.split('.')[0].length;
            let warningsOld = [];
            if (currentEndMeter < initialMeterOld) warningsOld.push(`• Valor final (${endHourMeter}) es MENOR al inicial (${initialMeterOld.toString().replace('.', ',')}).`);
            if (currentEndDigits > 8) warningsOld.push(`• Valor final tiene más de 8 dígitos enteros.`);
            if (warningsOld.length > 0) {
                if (!window.confirm(`ADVERTENCIA (Equipo Saliente):\n\n${warningsOld.join('\n')}\n\n¿Desea continuar?`)) return;
            }
        }

        if (!isContinuing && lastMeterForNew !== undefined) {
            const newStartDigits = normalizedNewStart.split('.')[0].length;
            let warningsNew = [];
            if (newStartVal < lastMeterForNew) warningsNew.push(`• Valor inicial (${newStartHourMeter}) es MENOR al último registro (${lastMeterForNew.toString().replace('.', ',')}).`);
            if (newStartDigits > 8) warningsNew.push(`• Valor inicial tiene más de 8 dígitos enteros.`);
            if (warningsNew.length > 0) {
                if (!window.confirm(`ADVERTENCIA (Equipo Entrante):\n\n${warningsNew.join('\n')}\n\n¿Desea continuar?`)) return;
            }
        }

        try {
            const newCraneUsage = await changeCrane(
                activeSession.craneUsage.id!,
                currentEndMeter,
                reason,
                newCrane,
                activeSession.craneUsage.yard,
                newStartVal,
                activeSession.session.id!,
                reason === 'Falla mecánica' ? reasonDetails : undefined
            );
            setActiveSession({ ...activeSession, craneUsage: newCraneUsage });
            fetchMovements();
            onClose();
        } catch (err) {
            setError('Error al cambiar de grúa.');
            console.error(err);
        }
    };

    const isYardChange = reason === 'Cambio de predio';

    return (
        <Modal title="🔄 Cambio de Equipo" onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="bg-red-50 p-3 rounded-lg border border-red-100 text-xs">
                    <p className="font-bold text-red-800 mb-1 uppercase tracking-tight">Equipo Saliente</p>
                    <div className="flex justify-between">
                        <span>GRÚA: <strong className="text-red-700">{activeSession?.craneUsage.crane}</strong></span>
                        <span>INICIAL: <strong className="text-red-700">{activeSession?.craneUsage.startHourMeter.toString().replace('.', ',')}</strong></span>
                    </div>
                </div>
                <Input label="Lectura Final (máquina actual)" type="text" value={endHourMeter} onChange={(val) => setEndHourMeter(val.replace(/[^0-9,]/g, ''))} required={!isYardChange} placeholder={isYardChange ? "Opcional" : "0000,00"} />
                <Select label="Razón del Cambio" value={reason} onChange={setReason} options={config.CRANE_CHANGE_REASONS || []} />
                {reason === 'Falla mecánica' && (
                     <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Detalle de la Falla</label>
                        <textarea value={reasonDetails} onChange={e => setReasonDetails(e.target.value)} required className="w-full p-2 border rounded-lg bg-gray-50 border-gray-200 text-sm outline-none focus:ring-2 focus:ring-red-500" rows={2} placeholder="Describa la falla..."/>
                    </div>
                )}
                <div className="w-full h-px bg-gray-100 my-2"></div>
                <div className="bg-green-50 p-3 rounded-lg border border-green-100 text-xs">
                    <p className="font-bold text-green-800 mb-1 uppercase tracking-tight">Equipo Entrante</p>
                    <Select label="Nueva Grúa" value={newCrane} onChange={setNewCrane} options={(config.CRANES || []).filter(c => c !== activeSession?.craneUsage.crane)} />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Horómetro Inicial (nueva)</label>
                    <input type="text" value={newStartHourMeter} onChange={e => setNewStartHourMeter(e.target.value.replace(/[^0-9,]/g, ''))} required readOnly={isContinuing} className={`w-full p-2.5 border rounded-lg shadow-sm font-bold ${isContinuing ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 border-gray-200 focus:ring-2 focus:ring-green-500'}`} placeholder="0000,00" />
                    {!isContinuing && lastMeterForNew !== undefined && (
                        <p className="text-[10px] text-blue-700 font-bold mt-1 bg-blue-50 p-1 rounded flex justify-between">
                            <span>ÚLTIMO REGISTRO:</span>
                            <span>{lastMeterForNew.toString().replace('.', ',')}</span>
                        </p>
                    )}
                </div>
                {error && <p className="text-red-600 text-xs font-bold">{error}</p>}
                <div className="flex justify-end gap-2 pt-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-lg font-black shadow-md hover:bg-green-700 transition-all">Confirmar Cambio</button>
                </div>
            </form>
        </Modal>
    );
}

function ChangeYardModal({ onClose, config }: { onClose: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newYard, setNewYard] = useState(activeSession?.craneUsage.yard || '');
    const handleYardChange = async () => {
        if (!activeSession) return;
        try {
            await changeYard(activeSession.craneUsage.id!, newYard);
            setActiveSession({ ...activeSession, craneUsage: { ...activeSession.craneUsage, yard: newYard } });
            onClose();
        } catch (error) { console.error(error); }
    };
    return (
        <Modal title="📍 Cambiar Predio" onClose={onClose}>
            <div className="space-y-4">
                <Select label="Nuevo Predio" value={newYard} onChange={setNewYard} options={config.YARDS || []} />
                <div className="flex justify-end gap-2 pt-4">
                    <button onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancelar</button>
                    <button onClick={handleYardChange} className="px-4 py-2 bg-green-600 text-white rounded-lg font-black shadow-md hover:bg-green-700 transition-all">Actualizar Predio</button>
                </div>
            </div>
        </Modal>
    );
}

import React, { useState, useContext, useEffect, useCallback } from 'react';
import { SessionContext } from '../contexts/SessionContext';
import { Movement, AppConfigKey, WorkshopRecord } from '../types';
import { addMovement, getRecentMovements, changeCrane, changeYard, endCurrentSession, countSessionMovements, getAppConfig, getLastHourMeterForCrane, addWorkshopRecord, getLatestUsageInSession, getPendingSyncCount } from '../services/db';

interface OperatorDashboardProps {
    setView: (view: 'LOGIN' | 'ADMIN') => void;
}

const getReasonStyle = (reason: string): { emoji: string; color: string } => {
    switch (reason) {
        case "Recepción": return { emoji: "📥", color: "bg-green-500 hover:bg-green-600" };
        case "Despacho": return { emoji: "📤", color: "bg-blue-500 hover:bg-blue-600" };
        case "Re-estibas": return { emoji: "🔄", color: "bg-yellow-500 hover:bg-yellow-600" };
        case "Cambios de chasis": return { emoji: "🚚", color: "bg-purple-500 hover:bg-purple-600" };
        case "Revisión en Racks": return { emoji: "✅", color: "bg-teal-500 hover:bg-teal-600" };
        case "Otro": return { emoji: "❓", color: "bg-gray-500 hover:bg-gray-600" };
        default: return { emoji: "🔘", color: "bg-gray-500 hover:bg-gray-600" };
    }
};

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
        <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="text-lg font-black text-gray-800 uppercase tracking-tight">{title}</h3>
                <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-100 transition-colors">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                </button>
            </div>
            <div className="p-6">
                {children}
            </div>
        </div>
    </div>
);

const Input: React.FC<{ label: string; type: string; value: string; onChange: (v: string) => void; required?: boolean; step?: string; placeholder?: string; readOnly?: boolean; className?: string }> = ({ label, type, value, onChange, required, step, placeholder, readOnly, className }) => (
    <div>
        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{label}</label>
        <input
            type={type}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            required={required}
            placeholder={placeholder}
            readOnly={readOnly}
            className={className || "w-full px-3 py-2 text-gray-900 bg-gray-50 border border-gray-200 rounded-lg shadow-sm focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none transition-all"}
        />
    </div>
);

const Select: React.FC<{ label: string; value: string; onChange: (v: string) => void; options: string[] }> = ({ label, value, onChange, options }) => (
    <div>
        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{label}</label>
        <select
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full px-3 py-2 text-gray-900 bg-gray-50 border border-gray-200 rounded-lg shadow-sm focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none transition-all"
        >
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default function OperatorDashboard({ setView }: OperatorDashboardProps) {
    const { activeSession, setActiveSession, logout } = useContext(SessionContext);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
        MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });
    const [client, setClient] = useState('');
    const [containerNumber, setContainerNumber] = useState(() => localStorage.getItem('staktrak_draft_container') || '');
    const [recentMovements, setRecentMovements] = useState<Movement[]>([]);
    const [totalMovements, setTotalMovements] = useState(0);
    const [pendingSync, setPendingSync] = useState(0);
    const [isCraneModalOpen, setCraneModalOpen] = useState(false);
    const [isYardModalOpen, setYardModalOpen] = useState(false);
    const [isWorkshopModalOpen, setWorkshopModalOpen] = useState(false);
    const [isEndSessionModalOpen, setEndSessionModalOpen] = useState(false);
    const [isRackMultiplierModalOpen, setRackMultiplierModalOpen] = useState(false);
    const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });
    const [showOnlyCurrentCrane, setShowOnlyCurrentCrane] = useState(false);

    useEffect(() => {
        const fetchConfig = async () => {
            const appConfig = await getAppConfig();
            setConfig(appConfig);
        };
        fetchConfig();
    }, []);

    useEffect(() => {
        localStorage.setItem('staktrak_draft_container', containerNumber);
    }, [containerNumber]);

    const updateSyncStatus = useCallback(async () => {
        const count = await getPendingSyncCount();
        setPendingSync(count);
    }, []);

    useEffect(() => {
        const interval = setInterval(updateSyncStatus, 5000);
        updateSyncStatus();
        return () => clearInterval(interval);
    }, [updateSyncStatus]);

    const fetchMovements = useCallback(async () => {
        if (activeSession?.session.id) {
            const craneFilter = showOnlyCurrentCrane ? activeSession.craneUsage.id : undefined;
            const movements = await getRecentMovements(activeSession.session.id, 5, craneFilter);
            setRecentMovements(movements);
            const count = await countSessionMovements(activeSession.session.id);
            setTotalMovements(count);
        }
    }, [activeSession, showOnlyCurrentCrane]);

    useEffect(() => {
        if (activeSession) {
            if (config.CLIENTS.length > 0) {
              setClient(activeSession.session.client || config.CLIENTS[0]);
            }
            fetchMovements();
        } else {
            setView('LOGIN');
        }
    }, [activeSession, fetchMovements, setView, config.CLIENTS]);

    const showStatusMessage = (type: 'success' | 'error', text: string) => {
        setStatusMessage({ type, text });
        setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
    };

    const handleLogMovement = async (reason: string) => {
        if (!activeSession) return;
        if (!/^\d{7}$/.test(containerNumber)) {
            showStatusMessage('error', 'El número de contenedor debe tener 7 dígitos.');
            return;
        }
        if (reason === "Revisión en Racks") {
            setRackMultiplierModalOpen(true);
            return;
        }
        await processMovementExecution(reason, 1);
    };

    const processMovementExecution = async (reason: string, count: number) => {
        if (!activeSession) return;
        try {
            const getBaseMovement = () => ({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                client,
                containerNumber,
                reason,
                yard: activeSession.craneUsage.yard,
                crane: activeSession.craneUsage.crane,
                operator: activeSession.session.operator,
            });

            for (let i = 0; i < count; i++) {
                await addMovement(getBaseMovement());
            }

            showStatusMessage('success', `Registrado: ${reason} (${count} mov).`);
            setContainerNumber('');
            localStorage.removeItem('staktrak_draft_container');
            fetchMovements();
            updateSyncStatus();
        } catch (error) {
            showStatusMessage('error', 'Error al registrar el movimiento.');
            console.error(error);
        }
    };

    if (!activeSession) return null;

    const { session, craneUsage } = activeSession;

    return (
        <div className="container mx-auto p-4 space-y-6 text-gray-900">
             <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 flex items-center justify-center bg-green-50 rounded-lg">
                        <svg className="w-8 h-8 text-green-700" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M3 21h18M5 21V7l8-4v18M13 21V3l8 4v14" />
                        </svg>
                    </div>
                    <div className="text-left">
                        <h1 className="text-2xl font-black text-green-700 leading-none uppercase tracking-tighter">
                          PANEL DE CONTROL GRUAS
                        </h1>
                        <div className="flex items-center gap-2 mt-1">
                            <p className="text-xs italic text-gray-400 font-medium">By R. Fonseca</p>
                            {pendingSync > 0 ? (
                                <span className="flex items-center gap-1 px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded text-[10px] font-bold animate-pulse">
                                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-11a1 1 0 10-2 0v2H7a1 1 0 100 2h2v2a1 1 0 102 0v-2h2a1 1 0 100-2h-2V7z"/></svg>
                                    NUBE: {pendingSync} PEND.
                                </span>
                            ) : (
                                <span className="flex items-center gap-1 px-1.5 py-0.5 bg-green-100 text-green-700 rounded text-[10px] font-bold">
                                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>
                                    NUBE: OK
                                </span>
                            )}
                        </div>
                    </div>
                </div>
                <div>
                    <button onClick={() => setEndSessionModalOpen(true)} className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-bold shadow-sm transition-colors">Finalizar Sesión</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* 1. REGISTRO DE MOVIMIENTO (Ahora primero) */}
                <div className="md:col-span-2 bg-white p-6 rounded-lg shadow-md border order-first md:order-none">
                    <h3 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <span className="text-green-600">🏗️</span> Registrar Movimiento
                    </h3>
                    <div className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Cliente</label>
                                <select value={client} onChange={(e) => setClient(e.target.value)} disabled={session.workType === 'Operación de Barco'} className="w-full p-2.5 border rounded-lg bg-gray-50 border-gray-200 disabled:opacity-50 font-medium">
                                    {(config.CLIENTS || []).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1"># Contenedor (7 dígitos)</label>
                                <input type="text" value={containerNumber} onChange={(e) => {
                                        const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 7);
                                        setContainerNumber(value);
                                    }} pattern="\d{7}" placeholder="0000000" className="w-full p-2.5 border rounded-lg bg-gray-50 border-gray-200 font-mono text-lg font-bold text-center tracking-widest focus:ring-2 focus:ring-green-500 outline-none transition-all"/>
                            </div>
                        </div>
                        <div className="pt-2">
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-3">Seleccione el motivo</label>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                                {(config.MOVEMENT_REASONS || []).map((reason) => {
                                    const { emoji, color } = getReasonStyle(reason);
                                    return (
                                        <button
                                            key={reason}
                                            type="button"
                                            onClick={() => handleLogMovement(reason)}
                                            className={`p-3 rounded-xl text-white flex flex-col items-center justify-center transition-all transform active:scale-90 hover:brightness-110 shadow-sm ${color}`}
                                        >
                                            <span className="text-2xl mb-1">{emoji}</span>
                                            <span className="text-xs font-black uppercase text-center">{reason}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                    {statusMessage.text && (
                        <div className={`mt-6 p-3 rounded-lg text-center font-bold text-sm animate-bounce ${statusMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                            {statusMessage.text}
                        </div>
                    )}
                </div>

                {/* 2. INFORMACIÓN GENERAL (Ahora después del registro en móvil) */}
                <div className="md:col-span-1 bg-white p-6 rounded-lg shadow-md border order-last md:order-none">
                    <h3 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <span className="text-green-600">ℹ️</span> Información
                    </h3>
                    <div className="space-y-2 text-sm mb-4">
                        <p><span className="text-gray-500 font-medium">Operador:</span> <span className="font-bold">{session.operator}</span></p>
                        <p><span className="text-gray-500 font-medium">Turno:</span> <span className="font-bold">{session.shift}</span></p>
                        <p><span className="text-gray-500 font-medium">Grúa:</span> <span className="font-bold text-green-700">{craneUsage.crane}</span></p>
                        <p><span className="text-gray-500 font-medium">Predio:</span> <span className="font-bold">{craneUsage.yard}</span></p>
                    </div>
                    <button 
                        onClick={() => setShowOnlyCurrentCrane(!showOnlyCurrentCrane)} 
                        className={`w-full py-2 px-4 rounded-lg font-bold text-xs uppercase transition-all shadow-sm flex items-center justify-center gap-2 border ${showOnlyCurrentCrane ? 'bg-green-700 text-white border-green-800' : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-gray-100'}`}
                    >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                        {showOnlyCurrentCrane ? 'Viendo esta grúa' : 'Ver por Grúa'}
                    </button>
                    <div className="mt-6 bg-blue-50 p-4 rounded-xl text-center border border-blue-100">
                        <p className="text-xs font-bold text-blue-800 uppercase tracking-widest">Movimientos de hoy</p>
                        <p className="text-5xl font-black text-blue-600 mt-1">{totalMovements}</p>
                    </div>
                    <div className="mt-6 flex flex-col gap-2">
                        <button onClick={() => setCraneModalOpen(true)} className="w-full px-3 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 shadow-sm transition-all">Cambiar Grúa</button>
                        <button onClick={() => setYardModalOpen(true)} className="w-full px-3 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 shadow-sm transition-all">Cambiar Predio</button>
                        <button onClick={() => setWorkshopModalOpen(true)} className="w-full px-3 py-2 bg-orange-500 text-white rounded-lg text-sm font-black hover:bg-orange-600 flex items-center justify-center shadow-sm transition-all">
                            <span className="mr-2">🔧</span> TALLER MEC
                        </button>
                    </div>
                </div>
            </div>

            {/* 3. HISTORIAL (Permanece al final) */}
            <div className="bg-white p-6 rounded-lg shadow-md border">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-semibold flex items-center gap-2">
                        <span className="text-green-600">📜</span> 
                        {showOnlyCurrentCrane ? `Últimos 5 de ${craneUsage.crane}` : 'Últimos 5 Movimientos (General)'}
                    </h3>
                    {showOnlyCurrentCrane && (
                        <span className="px-3 py-1 bg-green-100 text-green-800 text-[10px] font-black uppercase rounded-full border border-green-200 animate-pulse">
                            Filtro Activo
                        </span>
                    )}
                </div>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-100">
                        <thead>
                            <tr className="bg-gray-50">
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Hora</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Contenedor</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Cliente</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Razón</th>
                                {!showOnlyCurrentCrane && <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Grúa</th>}
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-100">
                            {recentMovements.length > 0 ? recentMovements.map(m => (
