    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(s => {
                const d = new Date(s.startTime);
                return d >= startDateFilter! && d <= endDateFilter!;
            });
            const sIds = new Set(filteredSessions.map(s => s.id));
            return { 
                sessions: filteredSessions, 
                craneUsages: craneUsages.filter(cu => sIds.has(cu.sessionId)), 
                movements: movements.filter(m => sIds.has(m.sessionId)),
                workshopRecords: workshopRecords.filter(wr => sIds.has(wr.sessionId))
            };
        }
        return { sessions: [], craneUsages: [], movements: [], workshopRecords: [] };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("No hay datos para exportar en este rango.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const clients = config.CLIENTS || [];
        const reasons = config.MOVEMENT_REASONS || [];

        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter) : 0;

            const row: any = {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TURNO': session?.shift || 'N/A',
                'GRÚA': usage.crane,
                'HORÓMETRO INICIAL': usage.startHourMeter,
                'HORÓMETRO FINAL': usage.endHourMeter || 'PENDIENTE',
                'HORAS DE USO': hrsCrane.toFixed(2),
            };

            let totalMovs = 0;
            clients.forEach(client => {
                const count = usageMovements.filter(m => m.client === client).length;
                row[`CLIENTE: ${client}`] = count;
                totalMovs += count;
            });
            row['TOTAL MOVIMIENTOS X CLIENTE'] = totalMovs;

            reasons.forEach(reason => {
                const count = usageMovements.filter(m => m.reason === reason).length;
                row[`MOTIVO: ${reason}`] = count;
            });
            row['TOTAL MOVIMIENTOS GENERAL'] = usageMovements.length;

            return row;
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado_Maestro');
        XLSX.writeFile(workbook, `Reporte_Consolidado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0 && workshopRecords.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });
        });

        workshopRecords.forEach(wr => {
            const s = sessionMap.get(wr.sessionId);
            allEvents.push({
                timestamp: new Date(wr.timestamp),
                data: {
                    'FECHA': new Date(wr.timestamp).toLocaleDateString(),
                    'HORA': new Date(wr.timestamp).toLocaleTimeString(),
                    'TIPO': 'TALLER MECÁNICO',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': wr.crane,
                    'PREDIO': 'TALLER',
                    'CLIENTE': '', 
                    'CONTENEDOR/REF': '',
                    'ACCION': 'Reparación / Mantenimiento',
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': wr.details
                }
            });
        });

        craneUsages.forEach(cu => {
            const s = sessionMap.get(cu.sessionId);

            // Inicio de uso
            allEvents.push({
                timestamp: new Date(cu.startTime),
                data: {
                    'FECHA': new Date(cu.startTime).toLocaleDateString(),
                    'HORA': new Date(cu.startTime).toLocaleTimeString(),
                    'TIPO': 'INICIO USO GRÚA',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': cu.crane,
                    'PREDIO': cu.yard,
                    'CLIENTE': '', 
                    'CONTENEDOR/REF': '',
                    'ACCION': `Inicio horómetro: ${cu.startHourMeter}`,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });

            // Fin de uso
            if (cu.endTime) {
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'FIN USO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': '',
                        'CONTENEDOR/REF': '',
                        'ACCION': cu.endHourMeter ? `Fin horómetro: ${cu.endHourMeter}` : 'Cierre sin horómetro final',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason || '',
                        'NOTAS MECÁNICO / TALLER': ''
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detallado');
        XLSX.writeFile(workbook, `ReporteDetallado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    if (viewMode === 'efficiency') {
        return <EfficiencyDashboard onBack={() => setViewMode('main')} />;
    }

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-green-600">
                <div className="flex items-center gap-4">
                    <div className="bg-green-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Panel Administrativo</h1>
                        <p className="text-sm font-bold text-green-600">Gestión de Operaciones Portuarias</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setViewMode('efficiency')} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center gap-2">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         DASHBOARD EFICIENCIA
                    </button>
                    <button onClick={() => setView('LOGIN')} className="px-6 py-2.5 bg-gray-100 text-gray-600 rounded-xl hover:bg-gray-200 font-bold transition-all">Regresar</button>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Consulta de Contenedor" icon="🔍">
                    <form onSubmit={handleSearch} className="flex gap-3 mb-6">
                        <input type="text" value={containerNumber} onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} className="flex-grow p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-mono text-xl font-bold tracking-widest focus:border-green-500 outline-none" placeholder="7 DÍGITOS"/>
                        <button type="submit" className="px-8 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all" disabled={isLoading}>BUSCAR</button>
                    </form>
                    {searchResult !== undefined && (
                        <div className="p-6 bg-green-50/50 border-2 border-green-100 rounded-2xl animate-in fade-in zoom-in duration-300">
                            {searchResult === null ? (
                                <p className="text-center text-gray-500 font-bold py-4">No se encontraron registros para este contenedor.</p>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex justify-between items-center border-b border-green-100 pb-2">
                                        <span className="text-xs font-black text-green-800 uppercase">Último Movimiento</span>
                                        <span className="text-sm font-bold bg-green-600 text-white px-2 py-1 rounded">{new Date(searchResult.timestamp).toLocaleDateString()}</span>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <MetricItem label="Operador" value={searchResult.operator} />
                                        <MetricItem label="Hora" value={new Date(searchResult.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} />
                                        <MetricItem label="Grúa" value={searchResult.crane} />
                                        <MetricItem label="Motivo" value={searchResult.reason} />
                                        <div className="col-span-2">
                                            <MetricItem label="Cliente" value={searchResult.client} />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </AdminSection>

                <AdminSection title="Generación de Reportes Excel" icon="📊">
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-gray-500 uppercase mb-2">Período de Análisis</label>
                                <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-bold text-gray-700 focus:border-green-500 outline-none">
                                    <option value="all">Todo el Historial</option>
                                    <option value="24h">Últimas 24 Horas</option>
                                    <option value="7d">Últimos 7 Días</option>
                                    <option value="custom">Rango Personalizado</option>
                                </select>
                            </div>
                            {dateRange === 'custom' && (
                                <div className="space-y-2">
                                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                </div>
                            )}
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4">
                             <button onClick={handleExportConsolidated} className="flex-1 py-4 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7.414A2 2 0 0015.414 6L12 2.586A2 2 0 0010.586 2H6zm5 6a1 1 0 10-2 0v3.586l-1.293-1.293a1 1 0 10-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 11.586V8z" clipRule="evenodd" /></svg>
                                 EXPORTAR CONSOLIDADO
                             </button>
                             <button onClick={handleExportDetailed} className="flex-1 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" /></svg>
                                 EXPORTAR DETALLADO
                             </button>
                        </div>
                    </div>
                </AdminSection>
            </div>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

function MetricItem({ label, value }: { label: string; value: string }) {
    return (
        <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
            <p className="text-sm font-bold text-gray-800">{value}</p>
        </div>
    );
}

interface EfficiencyStat {
    movs: number;
    hours: number;
}

function EfficiencyDashboard({ onBack }: { onBack: () => void }) {
    const [data, setData] = useState<{sessions: Session[], usages: CraneUsage[], movements: Movement[]}>({sessions:[], usages:[], movements:[]});
    const [filter, setFilter] = useState<'day' | 'week' | 'month'>('day');

    useEffect(() => {
        const fetch = async () => {
            const all = await getAllDataForExport();
            const now = new Date();
            let start = new Date();
            if (filter === 'day') start.setHours(0,0,0,0);
            else if (filter === 'week') {
                const day = now.getDay();
                start = new Date(now.getTime() - day * 24 * 60 * 60 * 1000);
                start.setHours(0,0,0,0);
            } else {
                start = new Date(now.getFullYear(), now.getMonth(), 1);
            }

            const filteredSessions = all.sessions.filter(s => new Date(s.startTime) >= start);
            const sIds = new Set(filteredSessions.map(s => s.id));
            setData({
                sessions: filteredSessions,
                usages: all.craneUsages.filter(cu => sIds.has(cu.sessionId)),
                movements: all.movements.filter(m => sIds.has(m.sessionId))
            });
        };
        fetch();
    }, [filter]);

    const stats = useMemo(() => {
        const opStats: Record<string, EfficiencyStat> = {};
        const craneStats: Record<string, EfficiencyStat> = {};

        data.usages.forEach(u => {
            const session = data.sessions.find(s => s.id === u.sessionId);
            const op = session?.operator || 'Desconocido';
            const hours = u.endHourMeter && u.startHourMeter ? (u.endHourMeter - u.startHourMeter) : 0;
            const movs = data.movements.filter(m => m.craneUsageId === u.id).length;

            if (!opStats[op]) opStats[op] = {movs: 0, hours: 0};
            opStats[op].movs += movs;
            opStats[op].hours += hours;

            if (!craneStats[u.crane]) craneStats[u.crane] = {movs: 0, hours: 0};
            craneStats[u.crane].movs += movs;
            craneStats[u.crane].hours += hours;
        });

        return { operators: opStats, cranes: craneStats };
    }, [data]);

    const totalHours = useMemo(() => 
        Object.values(stats.cranes).reduce((acc: number, curr: EfficiencyStat) => acc + curr.hours, 0)
    , [stats.cranes]);

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl animate-in fade-in slide-in-from-right duration-500">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-blue-600">
                <div className="flex items-center gap-4">
                    <div className="bg-blue-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Eficiencia Gerencial</h1>
                        <p className="text-sm font-bold text-blue-600">Indicadores de Desempeño (KPIs)</p>
                    </div>
                </div>
                <div className="flex gap-2 bg-gray-100 p-1.5 rounded-xl">
                    {(['day', 'week', 'month'] as const).map(f => (
                        <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${filter === f ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                            {f === 'day' ? 'Hoy' : f === 'week' ? 'Semana' : 'Mes'}
                        </button>
                    ))}
                    <button onClick={onBack} className="ml-4 px-4 py-2 bg-gray-800 text-white rounded-lg text-xs font-black uppercase hover:bg-black transition-all">SALIR</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <KPICard title="Total Movimientos" value={data.movements.length} color="blue" />
                <KPICard title="Horas Totales" value={totalHours.toFixed(1)} color="green" />
                <KPICard title="Promedio MPH" value={totalHours > 0 ? (data.movements.length / totalHours).toFixed(1) : 0} color="orange" unit="mov/hr" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Rendimiento por Operador (MPH)" icon="👤">
                    <div className="space-y-4">
                        {(Object.entries(stats.operators) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.operators) as [string, EfficiencyStat][]).sort((a,b) => (b[1].movs/b[1].hours) - (a[1].movs/a[1].hours)).map(([name, s]) => {
                            const mph = s.hours > 0 ? (s.movs / s.hours) : 0;
                            return (
                                <EfficiencyBar key={name} label={name} value={mph} max={25} />
                            );
                        }) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>

                <AdminSection title="Uso por Grúa (Horas)" icon="🏗️">
                    <div className="space-y-4">
                        {(Object.entries(stats.cranes) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.cranes) as [string, EfficiencyStat][]).sort((a,b) => b[1].hours - a[1].hours).map(([crane, s]) => (
                            <EfficiencyBar key={crane} label={crane} value={s.hours} max={24} color="bg-green-500" />
                        )) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>
            </div>
        </div>
    );
}

function KPICard({ title, value, color, unit }: { title: string; value: string | number; color: string; unit?: string }) {
    const colors: any = { blue: 'text-blue-600', green: 'text-green-600', orange: 'text-orange-600' };
    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg border-l-8 border-current text-gray-800" style={{borderColor: color === 'blue' ? '#2563eb' : color === 'green' ? '#16a34a' : '#ea580c'}}>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{title}</p>
            <p className={`text-4xl font-black ${colors[color]}`}>{value} <span className="text-sm font-bold text-gray-400">{unit}</span></p>
        </div>
    );
}

interface EfficiencyBarProps {
    label: string;
    value: number;
    max: number;
    color?: string;
}

const EfficiencyBar: React.FC<EfficiencyBarProps> = ({ label, value, max, color = "bg-blue-600" }) => {
    const percentage = Math.min((value / max) * 100, 100);
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-xs font-bold uppercase">
                <span className="text-gray-700">{label}</span>
                <span className="text-gray-900">{value.toFixed(1)}</span>
            </div>
            <div className="w-full bg-gray-100 h-4 rounded-full overflow-hidden border border-gray-200">
                <div className={`${color} h-full transition-all duration-1000`} style={{ width: `${percentage}%` }}></div>
            </div>
        </div>
    );
};

const AdminSection: React.FC<{ title: string; icon?: string; children: React.ReactNode }> = ({ title, icon, children }) => (
    <section className="bg-white p-8 rounded-3xl shadow-xl border border-gray-50">
        <h2 className="text-xl font-black mb-6 text-gray-800 flex items-center gap-3 uppercase tracking-tighter">
            <span className="text-2xl">{icon}</span>
            {title}
        </h2>
        {children}
    </section>
);

const ConfigManager: React.FC<{ config: Record<AppConfigKey, string[]>; onConfigChange: () => void }> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);
    useEffect(() => { setEditableConfig(config); }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            setEditableConfig(prev => ({ ...prev, [key]: [...prev[key], value] }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        setEditableConfig(prev => ({ ...prev, [key]: prev[key].filter(i => i !== value) }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`"${key}" actualizado correctamente.`);
            onConfigChange();
        } catch (e) { alert("Error al guardar."); }
    };

    return (
        <AdminSection title="Mantenimiento de Variables del Sistema" icon="⚙️">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection key={key} configKey={key as AppConfigKey} values={editableConfig[key as AppConfigKey]} onAddItem={handleAddItem} onRemoveItem={handleRemoveItem} onSave={handleSave} />
                ))}
            </div>
        </AdminSection>
    );
};

const ConfigSection: React.FC<{ configKey: AppConfigKey; values: string[]; onAddItem: any; onRemoveItem: any; onSave: any }> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');
    const titleMap: any = { OPERATORS: 'Operadores', SHIFTS: 'Turnos', WORK_TYPES: 'Jornadas', CRANES: 'Grúas', YARDS: 'Predios', CLIENTS: 'Clientes', MOVEMENT_REASONS: 'Razones Movimiento', CRANE_CHANGE_REASONS: 'Razones Cambio Grúa' };

    return (
        <div className="p-5 border-2 border-gray-100 rounded-2xl bg-gray-50/50 flex flex-col hover:border-green-200 transition-colors">
            <h3 className="font-black mb-4 text-gray-700 uppercase text-xs tracking-widest">{titleMap[configKey]}</h3>
            <ul className="flex-grow h-40 overflow-y-auto mb-4 space-y-2 pr-2 scrollbar-thin">
                {values.map(item => (
                    <li key={item} className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-100 shadow-sm text-sm font-bold text-gray-600">
                        <span>{item}</span>
                        <button onClick={() => onRemoveItem(configKey, item)} className="text-red-400 hover:text-red-600 transition-colors">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-2 mb-3">
                <input type="text" value={newItem} onChange={e => setNewItem(e.target.value)} className="flex-grow p-3 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none focus:border-green-500" placeholder="NUEVO VALOR..."/>
                <button onClick={() => { onAddItem(configKey, newItem); setNewItem(''); }} className="px-4 bg-green-600 text-white rounded-xl font-black shadow-lg hover:scale-105 transition-all">+</button>
            </div>
            <button onClick={() => onSave(configKey)} className="w-full py-3 bg-gray-800 text-white rounded-xl font-black text-xs shadow-lg hover:bg-black transition-all uppercase tracking-widest">Guardar Cambios</button>
        </div>
    );
};

import React, { useState, useContext, useEffect, useCallback } from 'react';
import { SessionContext } from '../contexts/SessionContext';
import { Movement, AppConfigKey, WorkshopRecord, CraneUsage } from '../types';
import { addMovement, getRecentMovements, changeCrane, changeYard, endCurrentSessionWithMeters, countSessionMovements, getAppConfig, getLastHourMeterForCrane, addWorkshopRecord, getLatestUsageInSession, getPendingSyncCount, getPendingHourMetersForSession } from '../services/db';

interface OperatorDashboardProps {
    setView: (view: 'LOGIN' | 'ADMIN') => void;
}

const getReasonStyle = (reason: string): { emoji: string; color: string } => {
    switch (reason) {
        case "Recepción": return { emoji: "📥", color: "bg-green-500 hover:bg-green-600" };
        case "Despacho": return { emoji: "📤", color: "bg-blue-500 hover:bg-blue-600" };
        case "Re-estibas": return { emoji: "🔄", color: "bg-yellow-500 hover:bg-yellow-600" };
        case "Cambios de chasis": return { emoji: "🚚", color: "bg-purple-500 hover:bg-purple-600" };
        case "Revisión en Racks": return { emoji: "✅", color: "bg-teal-500 hover:bg-teal-600" };
        case "Otro": return { emoji: "❓", color: "bg-gray-500 hover:bg-gray-600" };
        default: return { emoji: "🔘", color: "bg-gray-500 hover:bg-gray-600" };
    }
};

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
        <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in duration-200">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="text-lg font-black text-gray-800 uppercase tracking-tight">{title}</h3>
                <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-100">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>
            <div className="p-6 max-h-[80vh] overflow-y-auto">
                {children}
            </div>
        </div>
    </div>
);

export default function OperatorDashboard({ setView }: OperatorDashboardProps) {
    const { activeSession, setActiveSession, logout } = useContext(SessionContext);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
        MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });
    const [client, setClient] = useState('');
    const [containerNumber, setContainerNumber] = useState(() => localStorage.getItem('staktrak_draft_container') || '');
    const [recentMovements, setRecentMovements] = useState<Movement[]>([]);
    const [totalMovements, setTotalMovements] = useState(0);
    const [pendingSync, setPendingSync] = useState(0);
    const [isCraneModalOpen, setCraneModalOpen] = useState(false);
    const [isYardModalOpen, setYardModalOpen] = useState(false);
    const [isWorkshopModalOpen, setWorkshopModalOpen] = useState(false);
    const [isEndSessionModalOpen, setEndSessionModalOpen] = useState(false);
    const [isRackMultiplierModalOpen, setRackMultiplierModalOpen] = useState(false);
    const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });
    const [showOnlyCurrentCrane, setShowOnlyCurrentCrane] = useState(false);

    useEffect(() => {
        const fetchConfig = async () => setConfig(await getAppConfig());
        fetchConfig();
    }, []);

    useEffect(() => { localStorage.setItem('staktrak_draft_container', containerNumber); }, [containerNumber]);

    const updateSyncStatus = useCallback(async () => setPendingSync(await getPendingSyncCount()), []);

    useEffect(() => {
        const interval = setInterval(updateSyncStatus, 5000);
        updateSyncStatus();
        return () => clearInterval(interval);
    }, [updateSyncStatus]);

    const fetchMovements = useCallback(async () => {
        if (activeSession?.session.id) {
            const craneFilter = showOnlyCurrentCrane ? activeSession.craneUsage.id : undefined;
            const movements = await getRecentMovements(activeSession.session.id, 5, craneFilter);
            setRecentMovements(movements);
            setTotalMovements(await countSessionMovements(activeSession.session.id));
        }
    }, [activeSession, showOnlyCurrentCrane]);

    useEffect(() => {
        if (activeSession) {
            if (config.CLIENTS.length > 0) setClient(activeSession.session.client || config.CLIENTS[0]);
            fetchMovements();
        } else { setView('LOGIN'); }
    }, [activeSession, fetchMovements, setView, config.CLIENTS]);

    const handleLogMovement = async (reason: string) => {
        if (!activeSession) return;
        if (!/^\d{7}$/.test(containerNumber)) {
            setStatusMessage({ type: 'error', text: 'El número debe tener 7 dígitos.' });
            setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
            return;
        }
        if (reason === "Revisión en Racks") { setRackMultiplierModalOpen(true); return; }
        await processMovementExecution(reason, 1);
    };

    const processMovementExecution = async (reason: string, count: number) => {
        if (!activeSession) return;
        try {
            const getBase = () => ({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                client,
                containerNumber,
                reason,
                yard: activeSession.craneUsage.yard,
                crane: activeSession.craneUsage.crane,
                operator: activeSession.session.operator,
            });
            for (let i = 0; i < count; i++) await addMovement(getBase());
            setStatusMessage({ type: 'success', text: `Registrado: ${reason}` });
            setContainerNumber('');
            localStorage.removeItem('staktrak_draft_container');
            fetchMovements();
            updateSyncStatus();
            setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
        } catch (error) { console.error(error); }
    };

    if (!activeSession) return null;

    return (
        <div className="container mx-auto p-4 space-y-4 text-gray-900 pb-20">
             <header className="flex justify-between items-center bg-white p-3 rounded-xl shadow-sm border">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 flex items-center justify-center bg-green-50 rounded-lg">
                        <svg className="w-6 h-6 text-green-700" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 21h18M5 21V7l8-4v18M13 21V3l8 4v14" /></svg>
                    </div>
                    <div>
                        <h1 className="text-lg font-black text-green-700 leading-none uppercase tracking-tighter">SISTEMA GRÚAS</h1>
                        <p className="text-[10px] text-gray-400 font-bold uppercase">{pendingSync > 0 ? `Sincronizando ${pendingSync}...` : 'Nube OK'}</p>
                    </div>
                </div>
                <button onClick={() => setEndSessionModalOpen(true)} className="px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-black uppercase shadow-sm active:scale-95 transition-all">Finalizar</button>
            </header>

            {/* 1. REGISTRO DE MOVIMIENTO */}
            <div className="bg-white p-5 rounded-xl shadow-md border-t-4 border-green-600">
                <div className="grid grid-cols-2 gap-3 mb-4">
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Cliente</label>
                        <select value={client} onChange={(e) => setClient(e.target.value)} disabled={activeSession.session.workType === 'Operación de Barco'} className="w-full p-2.5 border rounded-lg bg-gray-50 text-sm font-bold">
                            {config.CLIENTS.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Contenedor</label>
                        <input 
                            type="text" 
                            inputMode="numeric" 
                            pattern="[0-9]*"
                            value={containerNumber} 
                            onChange={(e) => setContainerNumber(e.target.value.replace(/\D/g, '').slice(0, 7))} 
                            placeholder="0000000" 
                            className="w-full p-2.5 border rounded-lg bg-gray-50 font-mono text-lg font-black text-center focus:ring-2 focus:ring-green-500 outline-none transition-all"
                        />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-2">
                    {config.MOVEMENT_REASONS.map((reason) => {
                        const { emoji, color } = getReasonStyle(reason);
                        return (
                            <button key={reason} onClick={() => handleLogMovement(reason)} className={`p-3 rounded-xl text-white flex flex-col items-center justify-center transition-all transform active:scale-90 shadow-sm ${color}`}>
                                <span className="text-xl mb-0.5">{emoji}</span>
                                <span className="text-[9px] font-black uppercase tracking-tight">{reason}</span>
                            </button>
                        );
                    })}
                </div>
                {statusMessage.text && <div className={`mt-3 p-2 rounded text-center font-bold text-xs ${statusMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{statusMessage.text}</div>}
            </div>

            {/* 2. GESTIÓN DE EQUIPO */}
            <div className="grid grid-cols-3 gap-2">
                <button onClick={() => setCraneModalOpen(true)} className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-sm hover:bg-gray-50 active:scale-95 transition-all">
                    <span className="text-xl mb-1">🔄</span>
                    <span className="text-[8px] font-black text-gray-500 uppercase">Cambiar Grúa</span>
                </button>
                <button onClick={() => setYardModalOpen(true)} className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-sm hover:bg-gray-50 active:scale-95 transition-all">
                    <span className="text-xl mb-1">📍</span>
                    <span className="text-[8px] font-black text-gray-500 uppercase">Cambiar Predio</span>
                </button>
                <button onClick={() => setWorkshopModalOpen(true)} className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-sm hover:bg-gray-50 active:scale-95 transition-all">
                    <span className="text-xl mb-1">🔧</span>
                    <span className="text-[8px] font-black text-gray-500 uppercase">Taller</span>
                </button>
            </div>

            {/* 3. HISTORIAL SIMPLIFICADO */}
            <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                <div className="p-3 border-b bg-gray-50 flex justify-between items-center">
                    <h3 className="text-xs font-black text-gray-600 uppercase">Últimos 5</h3>
                    <button onClick={() => setShowOnlyCurrentCrane(!showOnlyCurrentCrane)} className={`text-[8px] px-2 py-1 rounded font-black uppercase ${showOnlyCurrentCrane ? 'bg-green-600 text-white' : 'bg-gray-200 text-gray-500'}`}>
                        {showOnlyCurrentCrane ? activeSession.craneUsage.crane : 'Ver por Grúa'}
                    </button>
                </div>
                <table className="w-full text-left text-sm">
                    <tbody className="divide-y">
                        {recentMovements.length > 0 ? recentMovements.map(m => (
                            <tr key={m.id} className="hover:bg-gray-50">
                                <td className="px-4 py-3 font-mono font-black text-green-700 tracking-widest">{m.containerNumber}</td>
                                <td className="px-4 py-3 text-right text-[10px] text-gray-400 font-bold">{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</td>
                            </tr>
                        )) : <tr><td colSpan={2} className="px-4 py-6 text-center text-gray-300 text-xs italic">Sin movimientos aún.</td></tr>}
                    </tbody>
                </table>
            </div>

            {/* 4. INFORMACIÓN DEL PIE */}
            <div className="bg-gray-50 p-4 rounded-xl border-t-2 border-gray-200">
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Operador / Grúa</p>
                        <p className="text-xs font-black text-gray-700 uppercase">{activeSession.session.operator} • {activeSession.craneUsage.crane}</p>
                    </div>
                    <div className="text-right">
                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Total Movimientos</p>
                        <p className="text-xl font-black text-blue-600 leading-none mt-1">{totalMovements}</p>
                    </div>
                </div>
            </div>

            {/* Modales */}
            {isCraneModalOpen && <ChangeCraneModal onClose={() => setCraneModalOpen(false)} fetchMovements={fetchMovements} config={config} />}
            {isYardModalOpen && <ChangeYardModal onClose={() => setYardModalOpen(false)} config={config} />}
            {isWorkshopModalOpen && <WorkshopModal onClose={() => setWorkshopModalOpen(false)} />}
            {isEndSessionModalOpen && <FinalizeSessionModal onClose={() => setEndSessionModalOpen(false)} />}
            {isRackMultiplierModalOpen && (
                <Modal title="Revisión en Racks" onClose={() => setRackMultiplierModalOpen(false)}>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => { processMovementExecution("Revisión en Racks", 1); setRackMultiplierModalOpen(false); }} className="p-6 bg-teal-500 text-white rounded-2xl shadow-lg active:scale-95 transition-all">
                            <span className="text-4xl font-black">1</span><br/><span className="text-[10px] uppercase font-bold">Movimiento</span>
                        </button>
                        <button onClick={() => { processMovementExecution("Revisión en Racks", 2); setRackMultiplierModalOpen(false); }} className="p-6 bg-teal-600 text-white rounded-2xl shadow-lg active:scale-95 transition-all">
                            <span className="text-4xl font-black">2</span><br/><span className="text-[10px] uppercase font-bold">Movimientos</span>
                        </button>
                    </div>
                </Modal>
            )}
        </div>
    );
}

function ChangeCraneModal({ onClose, fetchMovements, config }: { onClose: () => void, fetchMovements: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newCrane, setNewCrane] = useState(config.CRANES.filter(c => c !== activeSession?.craneUsage.crane)[0] || '');
    const [newStartHourMeter, setNewStartHourMeter] = useState('');
    const [lastMeter, setLastMeter] = useState<number | undefined>(undefined);
    const [isContinuing, setIsContinuing] = useState(false);

    useEffect(() => {
        if (newCrane && activeSession) {
            getLatestUsageInSession(activeSession.session.id!, newCrane).then(usage => {
                if (usage && usage.endHourMeter !== undefined) {
                    setNewStartHourMeter(usage.endHourMeter.toString().replace('.', ','));
                    setIsContinuing(true);
                } else {
                    setIsContinuing(false);
                    getLastHourMeterForCrane(newCrane).then(setLastMeter);
                }
            });
        }
    }, [newCrane, activeSession]);

    const handleConfirm = async () => {
        if (!activeSession || !newCrane || !newStartHourMeter) return;
        const startVal = parseFloat(newStartHourMeter.replace(',', '.'));
        if (isNaN(startVal)) return;

        try {
            const usage = await changeCrane(activeSession.craneUsage.id!, 'Cambio de equipo', newCrane, activeSession.craneUsage.yard, startVal, activeSession.session.id!);
            setActiveSession({ ...activeSession, craneUsage: usage });
            fetchMovements();
            onClose();
        } catch (e) { console.error(e); }
    };

    return (
        <Modal title="🔄 Cambio de Grúa" onClose={onClose}>
            <div className="space-y-4">
                <div className="p-3 bg-red-50 rounded-lg border border-red-100 text-[10px] font-bold text-red-800 uppercase">
                    Saliente: {activeSession?.craneUsage.crane}
                </div>
                <div>
                    <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Nueva Grúa</label>
                    <select value={newCrane} onChange={e => setNewCrane(e.target.value)} className="w-full p-2 border rounded-lg bg-gray-50 font-bold text-sm">
                        {config.CRANES.filter(c => c !== activeSession?.craneUsage.crane).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Horómetro Inicial</label>
                    <input 
                        type="text" 
                        inputMode="decimal"
                        value={newStartHourMeter} 
                        onChange={e => setNewStartHourMeter(e.target.value.replace(/[^0-9,]/g, ''))} 
                        readOnly={isContinuing} 
                        className="w-full p-3 border rounded-lg font-black text-lg text-center" 
                    />
                    {lastMeter !== undefined && !isContinuing && <p className="text-[9px] text-blue-600 font-bold mt-1 uppercase">Último: {lastMeter.toString().replace('.', ',')}</p>}
                </div>
                <button onClick={handleConfirm} className="w-full py-3 bg-green-600 text-white rounded-lg font-black uppercase shadow-md">Confirmar Cambio</button>
            </div>
        </Modal>
    );
}

function FinalizeSessionModal({ onClose }: { onClose: () => void }) {
    const { activeSession, logout } = useContext(SessionContext);
    const [pendingUsages, setPendingUsages] = useState<CraneUsage[]>([]);
    const [meters, setMeters] = useState<Record<number, string>>({});
    const [error, setError] = useState('');

    useEffect(() => {
        if (activeSession?.session.id) {
            getPendingHourMetersForSession(activeSession.session.id).then(setPendingUsages);
        }
    }, [activeSession]);

    const handleFinalize = async () => {
        if (!activeSession) return;
        const finalMeters: Record<number, number> = {};
        for (const usage of pendingUsages) {
            const val = parseFloat((meters[usage.id!] || '').replace(',', '.'));
            if (isNaN(val)) { setError('Complete todos los horómetros.'); return; }
            if (val < usage.startHourMeter) {
                if (!window.confirm(`El horómetro de ${usage.crane} (${val}) es menor al inicial (${usage.startHourMeter}). ¿Continuar?`)) return;
            }
            finalMeters[usage.id!] = val;
        }

        try {
            await endCurrentSessionWithMeters(activeSession.session.id!, finalMeters);
            logout();
        } catch (e) { console.error(e); }
    };

    return (
        <Modal title="🏁 Finalizar Jornada" onClose={onClose}>
            <div className="space-y-6">
                <p className="text-xs text-gray-500 font-bold uppercase text-center border-b pb-4">Ingrese horómetros finales para cerrar sesión</p>
                {pendingUsages.map(usage => (
                    <div key={usage.id} className="p-4 bg-gray-50 rounded-xl border border-gray-100 space-y-3">
                        <div className="flex justify-between items-center border-b pb-2">
                            <span className="text-lg font-black text-green-700">{usage.crane}</span>
                            <span className="text-[10px] font-black text-gray-400">INICIAL: {usage.startHourMeter.toString().replace('.', ',')}</span>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Horómetro Final</label>
                            <input 
                                type="text" 
                                inputMode="decimal"
                                value={meters[usage.id!] || ''} 
                                onChange={e => setMeters({...meters, [usage.id!]: e.target.value.replace(/[^0-9,]/g, '')})} 
                                placeholder="0000,00" 
                                className="w-full p-3 border rounded-lg font-black text-center text-lg bg-white" 
                            />
                        </div>
                    </div>
                ))}
                {error && <p className="text-red-600 text-[10px] font-black uppercase text-center">{error}</p>}
                <div className="grid grid-cols-2 gap-3 pt-4">
                    <button onClick={onClose} className="py-3 bg-gray-200 text-gray-700 rounded-lg font-black uppercase">Cancelar</button>
                    <button onClick={handleFinalize} className="py-3 bg-red-600 text-white rounded-lg font-black uppercase shadow-lg">Cerrar Sesión</button>
                </div>
            </div>
        </Modal>
    );
}

function ChangeYardModal({ onClose, config }: { onClose: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newYard, setNewYard] = useState(activeSession?.craneUsage.yard || '');
    const handleConfirm = async () => {
        if (!activeSession) return;
        await changeYard(activeSession.craneUsage.id!, newYard);
        setActiveSession({ ...activeSession, craneUsage: { ...activeSession.craneUsage, yard: newYard } });
        onClose();
    };
    return (
        <Modal title="📍 Cambiar Predio" onClose={onClose}>
            <div className="space-y-4">
                <select value={newYard} onChange={e => setNewYard(e.target.value)} className="w-full p-3 border rounded-lg bg-gray-50 font-bold text-sm">
                    {config.YARDS.map(y => <option key={y} value={y}>{y}</option>)}
                </select>
                <button onClick={handleConfirm} className="w-full py-3 bg-green-600 text-white rounded-lg font-black uppercase">Confirmar</button>
            </div>
        </Modal>
    );
}

function WorkshopModal({ onClose }: { onClose: () => void }) {
    const { activeSession } = useContext(SessionContext);
    const [details, setDetails] = useState('');
    const handleSubmit = async () => {
        if (!activeSession || !details) return;
        await addWorkshopRecord({ sessionId: activeSession.session.id!, craneUsageId: activeSession.craneUsage.id!, timestamp: new Date(), crane: activeSession.craneUsage.crane, details });
        onClose();
    };
    return (
        <Modal title="🔧 Taller Mecánico" onClose={onClose}>
            <div className="space-y-4">
                <p className="text-[10px] font-black text-gray-400 uppercase">Grúa: {activeSession?.craneUsage.crane}</p>
                <textarea value={details} onChange={e => setDetails(e.target.value)} placeholder="Describa el problema o trabajo..." className="w-full p-3 border rounded-lg bg-gray-50 text-sm min-h-[150px]" />
                <button onClick={handleSubmit} className="w-full py-3 bg-orange-600 text-white rounded-lg font-black uppercase">Guardar Reporte</button>
            </div>
        </Modal>
    );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session, CraneUsage } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [viewMode, setViewMode] = useState<'main' | 'efficiency'>('main');
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date | null = null;
        let endDateFilter: Date | null = null;

        switch (dateRange) {
            case '24h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                endDateFilter = now;
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                endDateFilter = now;
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
        }

        if (startDateFilter && endDateFilter) {
            const filteredSessions = sessions.filter(s => {
                const d = new Date(s.startTime);
                return d >= startDateFilter! && d <= endDateFilter!;
            });
            const sIds = new Set(filteredSessions.map(s => s.id));
            return { 
                sessions: filteredSessions, 
                craneUsages: craneUsages.filter(cu => sIds.has(cu.sessionId)), 
                movements: movements.filter(m => sIds.has(m.sessionId)),
                workshopRecords: workshopRecords.filter(wr => sIds.has(wr.sessionId))
            };
        }
        return { sessions: [], craneUsages: [], movements: [], workshopRecords: [] };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("No hay datos para exportar en este rango.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const clients = config.CLIENTS || [];
        const reasons = config.MOVEMENT_REASONS || [];

        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter) : 0;

            const row: any = {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TURNO': session?.shift || 'N/A',
                'GRÚA': usage.crane,
                'HORÓMETRO INICIAL': usage.startHourMeter,
                'HORÓMETRO FINAL': usage.endHourMeter || 'PENDIENTE',
                'HORAS DE USO': hrsCrane.toFixed(2),
            };

            let totalMovs = 0;
            clients.forEach(client => {
                const count = usageMovements.filter(m => m.client === client).length;
                row[`CLIENTE: ${client}`] = count;
                totalMovs += count;
            });
            row['TOTAL MOVIMIENTOS X CLIENTE'] = totalMovs;

            reasons.forEach(reason => {
                const count = usageMovements.filter(m => m.reason === reason).length;
                row[`MOTIVO: ${reason}`] = count;
            });
            row['TOTAL MOVIMIENTOS GENERAL'] = usageMovements.length;

            return row;
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado_Maestro');
        XLSX.writeFile(workbook, `Reporte_Consolidado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0 && workshopRecords.length === 0) {
            alert("Sin datos.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });
        });

        workshopRecords.forEach(wr => {
            const s = sessionMap.get(wr.sessionId);
            allEvents.push({
                timestamp: new Date(wr.timestamp),
                data: {
                    'FECHA': new Date(wr.timestamp).toLocaleDateString(),
                    'HORA': new Date(wr.timestamp).toLocaleTimeString(),
                    'TIPO': 'TALLER MECÁNICO',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': wr.crane,
                    'PREDIO': 'TALLER',
                    'CLIENTE': '', 
                    'CONTENEDOR/REF': '',
                    'ACCION': 'Reparación / Mantenimiento',
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': wr.details
                }
            });
        });

        craneUsages.forEach(cu => {
            const s = sessionMap.get(cu.sessionId);

            // Inicio de uso
            allEvents.push({
                timestamp: new Date(cu.startTime),
                data: {
                    'FECHA': new Date(cu.startTime).toLocaleDateString(),
                    'HORA': new Date(cu.startTime).toLocaleTimeString(),
                    'TIPO': 'INICIO USO GRÚA',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': cu.crane,
                    'PREDIO': cu.yard,
                    'CLIENTE': '', 
                    'CONTENEDOR/REF': '',
                    'ACCION': `Inicio horómetro: ${cu.startHourMeter}`,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });

            // Fin de uso
            if (cu.endTime) {
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'FIN USO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': '',
                        'CONTENEDOR/REF': '',
                        'ACCION': cu.endHourMeter ? `Fin horómetro: ${cu.endHourMeter}` : 'Cierre sin horómetro final',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason || '',
                        'NOTAS MECÁNICO / TALLER': ''
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detallado');
        XLSX.writeFile(workbook, `ReporteDetallado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    if (viewMode === 'efficiency') {
        return <EfficiencyDashboard onBack={() => setViewMode('main')} />;
    }

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-green-600">
                <div className="flex items-center gap-4">
                    <div className="bg-green-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Panel Administrativo</h1>
                        <p className="text-sm font-bold text-green-600">Gestión de Operaciones Portuarias</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setViewMode('efficiency')} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center gap-2">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         DASHBOARD EFICIENCIA
                    </button>
                    <button onClick={() => setView('LOGIN')} className="px-6 py-2.5 bg-gray-100 text-gray-600 rounded-xl hover:bg-gray-200 font-bold transition-all">Regresar</button>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Consulta de Contenedor" icon="🔍">
                    <form onSubmit={handleSearch} className="flex gap-3 mb-6">
                        <input 
                            type="text" 
                            inputMode="numeric"
                            pattern="[0-9]*"
                            value={containerNumber} 
                            onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} 
                            className="flex-grow p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-mono text-xl font-bold tracking-widest focus:border-green-500 outline-none" 
                            placeholder="7 DÍGITOS"
                        />
                        <button type="submit" className="px-8 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all" disabled={isLoading}>BUSCAR</button>
                    </form>
                    {searchResult !== undefined && (
                        <div className="p-6 bg-green-50/50 border-2 border-green-100 rounded-2xl animate-in fade-in zoom-in duration-300">
                            {searchResult === null ? (
                                <p className="text-center text-gray-500 font-bold py-4">No se encontraron registros para este contenedor.</p>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex justify-between items-center border-b border-green-100 pb-2">
                                        <span className="text-xs font-black text-green-800 uppercase">Último Movimiento</span>
                                        <span className="text-sm font-bold bg-green-600 text-white px-2 py-1 rounded">{new Date(searchResult.timestamp).toLocaleDateString()}</span>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <MetricItem label="Operador" value={searchResult.operator} />
                                        <MetricItem label="Hora" value={new Date(searchResult.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} />
                                        <MetricItem label="Grúa" value={searchResult.crane} />
                                        <MetricItem label="Motivo" value={searchResult.reason} />
                                        <div className="col-span-2">
                                            <MetricItem label="Cliente" value={searchResult.client} />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </AdminSection>

                <AdminSection title="Generación de Reportes Excel" icon="📊">
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-gray-500 uppercase mb-2">Período de Análisis</label>
                                <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-bold text-gray-700 focus:border-green-500 outline-none">
                                    <option value="all">Todo el Historial</option>
                                    <option value="24h">Últimas 24 Horas</option>
                                    <option value="7d">Últimos 7 Días</option>
                                    <option value="custom">Rango Personalizado</option>
                                </select>
                            </div>
                            {dateRange === 'custom' && (
                                <div className="space-y-2">
                                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                </div>
                            )}
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4">
                             <button onClick={handleExportConsolidated} className="flex-1 py-4 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7.414A2 2 0 0015.414 6L12 2.586A2 2 0 0010.586 2H6zm5 6a1 1 0 10-2 0v3.586l-1.293-1.293a1 1 0 10-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 11.586V8z" clipRule="evenodd" /></svg>
                                 EXPORTAR CONSOLIDADO
                             </button>
                             <button onClick={handleExportDetailed} className="flex-1 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" /></svg>
                                 EXPORTAR DETALLADO
                             </button>
                        </div>
                    </div>
                </AdminSection>
            </div>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

function MetricItem({ label, value }: { label: string; value: string }) {
    return (
        <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
            <p className="text-sm font-bold text-gray-800">{value}</p>
        </div>
    );
}

interface EfficiencyStat {
    movs: number;
    hours: number;
}

function EfficiencyDashboard({ onBack }: { onBack: () => void }) {
    const [data, setData] = useState<{sessions: Session[], usages: CraneUsage[], movements: Movement[]}>({sessions:[], usages:[], movements:[]});
    const [filter, setFilter] = useState<'day' | 'week' | 'month'>('day');

    useEffect(() => {
        const fetch = async () => {
            const all = await getAllDataForExport();
            const now = new Date();
            let start = new Date();
            if (filter === 'day') start.setHours(0,0,0,0);
            else if (filter === 'week') {
                const day = now.getDay();
                start = new Date(now.getTime() - day * 24 * 60 * 60 * 1000);
                start.setHours(0,0,0,0);
            } else {
                start = new Date(now.getFullYear(), now.getMonth(), 1);
            }

            const filteredSessions = all.sessions.filter(s => new Date(s.startTime) >= start);
            const sIds = new Set(filteredSessions.map(s => s.id));
            setData({
                sessions: filteredSessions,
                usages: all.craneUsages.filter(cu => sIds.has(cu.sessionId)),
                movements: all.movements.filter(m => sIds.has(m.sessionId))
            });
        };
        fetch();
    }, [filter]);

    const stats = useMemo(() => {
        const opStats: Record<string, EfficiencyStat> = {};
        const craneStats: Record<string, EfficiencyStat> = {};

        data.usages.forEach(u => {
            const session = data.sessions.find(s => s.id === u.sessionId);
            const op = session?.operator || 'Desconocido';
            const hours = u.endHourMeter && u.startHourMeter ? (u.endHourMeter - u.startHourMeter) : 0;
            const movs = data.movements.filter(m => m.craneUsageId === u.id).length;

            if (!opStats[op]) opStats[op] = {movs: 0, hours: 0};
            opStats[op].movs += movs;
            opStats[op].hours += hours;

            if (!craneStats[u.crane]) craneStats[u.crane] = {movs: 0, hours: 0};
            craneStats[u.crane].movs += movs;
            craneStats[u.crane].hours += hours;
        });

        return { operators: opStats, cranes: craneStats };
    }, [data]);

    const totalHours = useMemo(() => 
        Object.values(stats.cranes).reduce((acc: number, curr: EfficiencyStat) => acc + curr.hours, 0)
    , [stats.cranes]);

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl animate-in fade-in slide-in-from-right duration-500">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-blue-600">
                <div className="flex items-center gap-4">
                    <div className="bg-blue-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Eficiencia Gerencial</h1>
                        <p className="text-sm font-bold text-blue-600">Indicadores de Desempeño (KPIs)</p>
                    </div>
                </div>
                <div className="flex gap-2 bg-gray-100 p-1.5 rounded-xl">
                    {(['day', 'week', 'month'] as const).map(f => (
                        <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${filter === f ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                            {f === 'day' ? 'Hoy' : f === 'week' ? 'Semana' : 'Mes'}
                        </button>
                    ))}
                    <button onClick={onBack} className="ml-4 px-4 py-2 bg-gray-800 text-white rounded-lg text-xs font-black uppercase hover:bg-black transition-all">SALIR</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <KPICard title="Total Movimientos" value={data.movements.length} color="blue" />
                <KPICard title="Horas Totales" value={totalHours.toFixed(1)} color="green" />
                <KPICard title="Promedio MPH" value={totalHours > 0 ? (data.movements.length / totalHours).toFixed(1) : 0} color="orange" unit="mov/hr" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Rendimiento por Operador (MPH)" icon="👤">
                    <div className="space-y-4">
                        {(Object.entries(stats.operators) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.operators) as [string, EfficiencyStat][]).sort((a,b) => (b[1].movs/b[1].hours) - (a[1].movs/a[1].hours)).map(([name, s]) => {
                            const mph = s.hours > 0 ? (s.movs / s.hours) : 0;
                            return (
                                <EfficiencyBar key={name} label={name} value={mph} max={25} />
                            );
                        }) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>

                <AdminSection title="Uso por Grúa (Horas)" icon="🏗️">
                    <div className="space-y-4">
                        {(Object.entries(stats.cranes) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.cranes) as [string, EfficiencyStat][]).sort((a,b) => b[1].hours - a[1].hours).map(([crane, s]) => (
                            <EfficiencyBar key={crane} label={crane} value={s.hours} max={24} color="bg-green-500" />
                        )) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>
            </div>
        </div>
    );
}

function KPICard({ title, value, color, unit }: { title: string; value: string | number; color: string; unit?: string }) {
    const colors: any = { blue: 'text-blue-600', green: 'text-green-600', orange: 'text-orange-600' };
    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg border-l-8 border-current text-gray-800" style={{borderColor: color === 'blue' ? '#2563eb' : color === 'green' ? '#16a34a' : '#ea580c'}}>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{title}</p>
            <p className={`text-4xl font-black ${colors[color]}`}>{value} <span className="text-sm font-bold text-gray-400">{unit}</span></p>
        </div>
    );
}

interface EfficiencyBarProps {
    label: string;
    value: number;
    max: number;
    color?: string;
}

const EfficiencyBar: React.FC<EfficiencyBarProps> = ({ label, value, max, color = "bg-blue-600" }) => {
    const percentage = Math.min((value / max) * 100, 100);
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-xs font-bold uppercase">
                <span className="text-gray-700">{label}</span>
                <span className="text-gray-900">{value.toFixed(1)}</span>
            </div>
            <div className="w-full bg-gray-100 h-4 rounded-full overflow-hidden border border-gray-200">
                <div className={`${color} h-full transition-all duration-1000`} style={{ width: `${percentage}%` }}></div>
            </div>
        </div>
    );
};

const AdminSection: React.FC<{ title: string; icon?: string; children: React.ReactNode }> = ({ title, icon, children }) => (
    <section className="bg-white p-8 rounded-3xl shadow-xl border border-gray-50">
        <h2 className="text-xl font-black mb-6 text-gray-800 flex items-center gap-3 uppercase tracking-tighter">
            <span className="text-2xl">{icon}</span>
            {title}
        </h2>
        {children}
    </section>
);

const ConfigManager: React.FC<{ config: Record<AppConfigKey, string[]>; onConfigChange: () => void }> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);
    useEffect(() => { setEditableConfig(config); }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            setEditableConfig(prev => ({ ...prev, [key]: [...prev[key], value] }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        setEditableConfig(prev => ({ ...prev, [key]: prev[key].filter(i => i !== value) }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`"${key}" actualizado correctamente.`);
            onConfigChange();
        } catch (e) { alert("Error al guardar."); }
    };

    return (
        <AdminSection title="Mantenimiento de Variables del Sistema" icon="⚙️">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection key={key} configKey={key as AppConfigKey} values={editableConfig[key as AppConfigKey]} onAddItem={handleAddItem} onRemoveItem={handleRemoveItem} onSave={handleSave} />
                ))}
            </div>
        </AdminSection>
    );
};

const ConfigSection: React.FC<{ configKey: AppConfigKey; values: string[]; onAddItem: any; onRemoveItem: any; onSave: any }> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');
    const titleMap: any = { OPERATORS: 'Operadores', SHIFTS: 'Turnos', WORK_TYPES: 'Jornadas', CRANES: 'Grúas', YARDS: 'Predios', CLIENTS: 'Clientes', MOVEMENT_REASONS: 'Razones Movimiento', CRANE_CHANGE_REASONS: 'Razones Cambio Grúa' };

    return (
        <div className="p-5 border-2 border-gray-100 rounded-2xl bg-gray-50/50 flex flex-col hover:border-green-200 transition-colors">
            <h3 className="font-black mb-4 text-gray-700 uppercase text-xs tracking-widest">{titleMap[configKey]}</h3>
            <ul className="flex-grow h-40 overflow-y-auto mb-4 space-y-2 pr-2 scrollbar-thin">
                {values.map(item => (
                    <li key={item} className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-100 shadow-sm text-sm font-bold text-gray-600">
                        <span>{item}</span>
                        <button onClick={() => onRemoveItem(configKey, item)} className="text-red-400 hover:text-red-600 transition-colors">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-2 mb-3">
                <input type="text" value={newItem} onChange={e => setNewItem(e.target.value)} className="flex-grow p-3 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none focus:border-green-500" placeholder="NUEVO VALOR..."/>
                <button onClick={() => { onAddItem(configKey, newItem); setNewItem(''); }} className="px-4 bg-green-600 text-white rounded-xl font-black shadow-lg hover:scale-105 transition-all">+</button>
            </div>
            <button onClick={() => onSave(configKey)} className="w-full py-3 bg-gray-800 text-white rounded-xl font-black text-xs shadow-lg hover:bg-black transition-all uppercase tracking-widest">Guardar Cambios</button>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session, CraneUsage } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [viewMode, setViewMode] = useState<'main' | 'efficiency'>('main');
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('48h'); // Por defecto Ayer y Hoy
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        let { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date;
        let endDateFilter: Date = now;

        switch (dateRange) {
            case 'today':
                startDateFilter = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
                break;
            case '48h':
                // Desde ayer a las 00:00:00 hasta ahora
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                } else {
                    startDateFilter = new Date(0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
            default:
                startDateFilter = new Date(0);
        }

        const startTs = startDateFilter.getTime();
        const endTs = endDateFilter.getTime();

        // 1. Filtrar movimientos por su propio timestamp
        const filteredMovements = movements.filter(m => {
            const ts = new Date(m.timestamp).getTime();
            return ts >= startTs && ts <= endTs;
        });

        // 2. Filtrar registros de taller
        const filteredWorkshop = workshopRecords.filter(wr => {
            const ts = new Date(wr.timestamp).getTime();
            return ts >= startTs && ts <= endTs;
        });

        // 3. Filtrar usos de grúa que intersecten con el periodo
        const filteredUsages = craneUsages.filter(cu => {
            const cuStart = new Date(cu.startTime).getTime();
            const cuEnd = cu.endTime ? new Date(cu.endTime).getTime() : now.getTime();
            // Hay intersección si (InicioUso <= FinFiltro) Y (FinUso >= InicioFiltro)
            return cuStart <= endTs && cuEnd >= startTs;
        });

        // 4. Obtener sesiones involucradas
        const relevantSessionIds = new Set([
            ...filteredMovements.map(m => m.sessionId),
            ...filteredWorkshop.map(wr => wr.sessionId),
            ...filteredUsages.map(cu => cu.sessionId)
        ]);

        const filteredSessions = sessions.filter(s => relevantSessionIds.has(s.id!));

        return { 
            sessions: filteredSessions, 
            craneUsages: filteredUsages, 
            movements: filteredMovements,
            workshopRecords: filteredWorkshop
        };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("No hay datos para exportar en este rango.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const clients = config.CLIENTS || [];
        const reasons = config.MOVEMENT_REASONS || [];

        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            // En el consolidado por grúa, mostramos los movimientos que pertenecen a ese uso específico
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter) : 0;

            const row: any = {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'OPERADOR': session?.operator || 'N/A',
                'TURNO': session?.shift || 'N/A',
                'GRÚA': usage.crane,
                'HORÓMETRO INICIAL': usage.startHourMeter,
                'HORÓMETRO FINAL': usage.endHourMeter || 'ACTIVO',
                'HORAS DE USO': hrsCrane.toFixed(2),
            };

            let totalMovs = 0;
            clients.forEach(client => {
                const count = usageMovements.filter(m => m.client === client).length;
                row[`CLIENTE: ${client}`] = count;
                totalMovs += count;
            });
            row['TOTAL MOVIMIENTOS X CLIENTE'] = totalMovs;

            reasons.forEach(reason => {
                const count = usageMovements.filter(m => m.reason === reason).length;
                row[`MOTIVO: ${reason}`] = count;
            });
            row['TOTAL MOVIMIENTOS GENERAL'] = usageMovements.length;

            return row;
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Consolidado_Maestro');
        XLSX.writeFile(workbook, `Consolidado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    const handleExportDetailed = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getFilteredData();
        if (movements.length === 0 && craneUsages.length === 0 && workshopRecords.length === 0) {
            alert("Sin datos en el rango seleccionado.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const allEvents: any[] = [];

        movements.forEach(m => {
            allEvents.push({
                timestamp: new Date(m.timestamp),
                data: {
                    'FECHA': new Date(m.timestamp).toLocaleDateString(),
                    'HORA': new Date(m.timestamp).toLocaleTimeString(),
                    'TIPO': 'MOVIMIENTO',
                    'OPERADOR': m.operator,
                    'GRUA': m.crane,
                    'PREDIO': m.yard,
                    'CLIENTE': m.client,
                    'CONTENEDOR/REF': m.containerNumber,
                    'ACCION': m.reason,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });
        });

        workshopRecords.forEach(wr => {
            const s = sessionMap.get(wr.sessionId);
            allEvents.push({
                timestamp: new Date(wr.timestamp),
                data: {
                    'FECHA': new Date(wr.timestamp).toLocaleDateString(),
                    'HORA': new Date(wr.timestamp).toLocaleTimeString(),
                    'TIPO': 'TALLER MECÁNICO',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': wr.crane,
                    'PREDIO': 'TALLER',
                    'CLIENTE': '', 
                    'CONTENEDOR/REF': '',
                    'ACCION': 'Reparación / Mantenimiento',
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': wr.details
                }
            });
        });

        craneUsages.forEach(cu => {
            const s = sessionMap.get(cu.sessionId);

            // Evento de inicio de uso
            allEvents.push({
                timestamp: new Date(cu.startTime),
                data: {
                    'FECHA': new Date(cu.startTime).toLocaleDateString(),
                    'HORA': new Date(cu.startTime).toLocaleTimeString(),
                    'TIPO': 'INICIO USO GRÚA',
                    'OPERADOR': s?.operator || 'N/A',
                    'GRUA': cu.crane,
                    'PREDIO': cu.yard,
                    'CLIENTE': '', 
                    'CONTENEDOR/REF': '',
                    'ACCION': `Inicio horómetro: ${cu.startHourMeter}`,
                    'NOTAS / DAÑOS REPORTADOS': '',
                    'NOTAS MECÁNICO / TALLER': ''
                }
            });

            // Evento de fin de uso
            if (cu.endTime) {
                allEvents.push({
                    timestamp: new Date(cu.endTime),
                    data: {
                        'FECHA': new Date(cu.endTime).toLocaleDateString(),
                        'HORA': new Date(cu.endTime).toLocaleTimeString(),
                        'TIPO': 'FIN USO GRÚA',
                        'OPERADOR': s?.operator || 'N/A',
                        'GRUA': cu.crane,
                        'PREDIO': cu.yard,
                        'CLIENTE': '',
                        'CONTENEDOR/REF': '',
                        'ACCION': cu.endHourMeter ? `Fin horómetro: ${cu.endHourMeter}` : 'Cierre sin horómetro final',
                        'NOTAS / DAÑOS REPORTADOS': cu.changeReasonDetails || cu.changeReason || '',
                        'NOTAS MECÁNICO / TALLER': ''
                    }
                });
            }
        });

        allEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
        const dataForExport = allEvents.map(e => e.data);

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Detalle_Log');
        XLSX.writeFile(workbook, `Detallado_${new Date().toISOString().split('T')[0]}.xlsx`);
    };

    if (viewMode === 'efficiency') {
        return <EfficiencyDashboard onBack={() => setViewMode('main')} />;
    }

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-green-600">
                <div className="flex items-center gap-4">
                    <div className="bg-green-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Panel Administrativo</h1>
                        <p className="text-sm font-bold text-green-600">Gestión de Operaciones Portuarias</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setViewMode('efficiency')} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center gap-2">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         DASHBOARD EFICIENCIA
                    </button>
                    <button onClick={() => setView('LOGIN')} className="px-6 py-2.5 bg-gray-100 text-gray-600 rounded-xl hover:bg-gray-200 font-bold transition-all">Regresar</button>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Consulta de Contenedor" icon="🔍">
                    <form onSubmit={handleSearch} className="flex gap-3 mb-6">
                        <input 
                            type="text" 
                            inputMode="numeric"
                            pattern="[0-9]*"
                            value={containerNumber} 
                            onChange={e => setContainerNumber(e.target.value.replace(/\D/g,'').slice(0,7))} 
                            className="flex-grow p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-mono text-xl font-bold tracking-widest focus:border-green-500 outline-none" 
                            placeholder="7 DÍGITOS"
                        />
                        <button type="submit" className="px-8 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all" disabled={isLoading}>BUSCAR</button>
                    </form>
                    {searchResult !== undefined && (
                        <div className="p-6 bg-green-50/50 border-2 border-green-100 rounded-2xl animate-in fade-in zoom-in duration-300">
                            {searchResult === null ? (
                                <p className="text-center text-gray-500 font-bold py-4">No se encontraron registros para este contenedor.</p>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex justify-between items-center border-b border-green-100 pb-2">
                                        <span className="text-xs font-black text-green-800 uppercase">Último Movimiento</span>
                                        <span className="text-sm font-bold bg-green-600 text-white px-2 py-1 rounded">{new Date(searchResult.timestamp).toLocaleDateString()}</span>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <MetricItem label="Operador" value={searchResult.operator} />
                                        <MetricItem label="Hora" value={new Date(searchResult.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} />
                                        <MetricItem label="Grúa" value={searchResult.crane} />
                                        <MetricItem label="Motivo" value={searchResult.reason} />
                                        <div className="col-span-2">
                                            <MetricItem label="Cliente" value={searchResult.client} />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </AdminSection>

                <AdminSection title="Generación de Reportes Excel" icon="📊">
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-gray-500 uppercase mb-2">Período de Análisis</label>
                                <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-xl font-bold text-gray-700 focus:border-green-500 outline-none">
                                    <option value="today">Hoy (Desde 00:00)</option>
                                    <option value="48h">Ayer y Hoy (Recomendado)</option>
                                    <option value="7d">Últimos 7 Días</option>
                                    <option value="all">Todo el Historial</option>
                                    <option value="custom">Rango Personalizado</option>
                                </select>
                            </div>
                            {dateRange === 'custom' && (
                                <div className="space-y-2">
                                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                </div>
                            )}
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4">
                             <button onClick={handleExportConsolidated} className="flex-1 py-4 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7.414A2 2 0 0015.414 6L12 2.586A2 2 0 0010.586 2H6zm5 6a1 1 0 10-2 0v3.586l-1.293-1.293a1 1 0 10-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 11.586V8z" clipRule="evenodd" /></svg>
                                 EXPORTAR CONSOLIDADO
                             </button>
                             <button onClick={handleExportDetailed} className="flex-1 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" /></svg>
                                 EXPORTAR DETALLADO
                             </button>
                        </div>
                    </div>
                </AdminSection>
            </div>

            <ConfigManager config={config} onConfigChange={fetchConfig} />
        </div>
    );
}

function MetricItem({ label, value }: { label: string; value: string }) {
    return (
        <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
            <p className="text-sm font-bold text-gray-800">{value}</p>
        </div>
    );
}

interface EfficiencyStat {
    movs: number;
    hours: number;
}

function EfficiencyDashboard({ onBack }: { onBack: () => void }) {
    const [data, setData] = useState<{sessions: Session[], usages: CraneUsage[], movements: Movement[]}>({sessions:[], usages:[], movements:[]});
    const [filter, setFilter] = useState<'day' | 'week' | 'month'>('day');

    useEffect(() => {
        const fetch = async () => {
            const all = await getAllDataForExport();
            const now = new Date();
            let start = new Date();
            if (filter === 'day') start.setHours(0,0,0,0);
            else if (filter === 'week') {
                const day = now.getDay();
                start = new Date(now.getTime() - day * 24 * 60 * 60 * 1000);
                start.setHours(0,0,0,0);
            } else {
                start = new Date(now.getFullYear(), now.getMonth(), 1);
            }

            const filteredSessions = all.sessions.filter(s => new Date(s.startTime) >= start);
            const sIds = new Set(filteredSessions.map(s => s.id));
            setData({
                sessions: filteredSessions,
                usages: all.craneUsages.filter(cu => sIds.has(cu.sessionId)),
                movements: all.movements.filter(m => sIds.has(m.sessionId))
            });
        };
        fetch();
    }, [filter]);

    const stats = useMemo(() => {
        const opStats: Record<string, EfficiencyStat> = {};
        const craneStats: Record<string, EfficiencyStat> = {};

        data.usages.forEach(u => {
            const session = data.sessions.find(s => s.id === u.sessionId);
            const op = session?.operator || 'Desconocido';
            const hours = u.endHourMeter && u.startHourMeter ? (u.endHourMeter - u.startHourMeter) : 0;
            const movs = data.movements.filter(m => m.craneUsageId === u.id).length;

            if (!opStats[op]) opStats[op] = {movs: 0, hours: 0};
            opStats[op].movs += movs;
            opStats[op].hours += hours;

            if (!craneStats[u.crane]) craneStats[u.crane] = {movs: 0, hours: 0};
            craneStats[u.crane].movs += movs;
            craneStats[u.crane].hours += hours;
        });

        return { operators: opStats, cranes: craneStats };
    }, [data]);

    const totalHours = useMemo(() => 
        Object.values(stats.cranes).reduce((acc: number, curr: EfficiencyStat) => acc + curr.hours, 0)
    , [stats.cranes]);

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl animate-in fade-in slide-in-from-right duration-500">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-blue-600">
                <div className="flex items-center gap-4">
                    <div className="bg-blue-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Eficiencia Gerencial</h1>
                        <p className="text-sm font-bold text-blue-600">Indicadores de Desempeño (KPIs)</p>
                    </div>
                </div>
                <div className="flex gap-2 bg-gray-100 p-1.5 rounded-xl">
                    {(['day', 'week', 'month'] as const).map(f => (
                        <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${filter === f ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                            {f === 'day' ? 'Hoy' : f === 'week' ? 'Semana' : 'Mes'}
                        </button>
                    ))}
                    <button onClick={onBack} className="ml-4 px-4 py-2 bg-gray-800 text-white rounded-lg text-xs font-black uppercase hover:bg-black transition-all">SALIR</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <KPICard title="Total Movimientos" value={data.movements.length} color="blue" />
                <KPICard title="Horas Totales" value={totalHours.toFixed(1)} color="green" />
                <KPICard title="Promedio MPH" value={totalHours > 0 ? (data.movements.length / totalHours).toFixed(1) : 0} color="orange" unit="mov/hr" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Rendimiento por Operador (MPH)" icon="👤">
                    <div className="space-y-4">
                        {(Object.entries(stats.operators) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.operators) as [string, EfficiencyStat][]).sort((a,b) => (b[1].movs/b[1].hours) - (a[1].movs/a[1].hours)).map(([name, s]) => {
                            const mph = s.hours > 0 ? (s.movs / s.hours) : 0;
                            return (
                                <EfficiencyBar key={name} label={name} value={mph} max={25} />
                            );
                        }) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>

                <AdminSection title="Uso por Grúa (Horas)" icon="🏗️">
                    <div className="space-y-4">
                        {(Object.entries(stats.cranes) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.cranes) as [string, EfficiencyStat][]).sort((a,b) => b[1].hours - a[1].hours).map(([crane, s]) => (
                            <EfficiencyBar key={crane} label={crane} value={s.hours} max={24} color="bg-green-500" />
                        )) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>
            </div>
        </div>
    );
}

function KPICard({ title, value, color, unit }: { title: string; value: string | number; color: string; unit?: string }) {
    const colors: any = { blue: 'text-blue-600', green: 'text-green-600', orange: 'text-orange-600' };
    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg border-l-8 border-current text-gray-800" style={{borderColor: color === 'blue' ? '#2563eb' : color === 'green' ? '#16a34a' : '#ea580c'}}>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{title}</p>
            <p className={`text-4xl font-black ${colors[color]}`}>{value} <span className="text-sm font-bold text-gray-400">{unit}</span></p>
        </div>
    );
}

interface EfficiencyBarProps {
    label: string;
    value: number;
    max: number;
    color?: string;
}

const EfficiencyBar: React.FC<EfficiencyBarProps> = ({ label, value, max, color = "bg-blue-600" }) => {
    const percentage = Math.min((value / max) * 100, 100);
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-xs font-bold uppercase">
                <span className="text-gray-700">{label}</span>
                <span className="text-gray-900">{value.toFixed(1)}</span>
            </div>
            <div className="w-full bg-gray-100 h-4 rounded-full overflow-hidden border border-gray-200">
                <div className={`${color} h-full transition-all duration-1000`} style={{ width: `${percentage}%` }}></div>
            </div>
        </div>
    );
};

const AdminSection: React.FC<{ title: string; icon?: string; children: React.ReactNode }> = ({ title, icon, children }) => (
    <section className="bg-white p-8 rounded-3xl shadow-xl border border-gray-50">
        <h2 className="text-xl font-black mb-6 text-gray-800 flex items-center gap-3 uppercase tracking-tighter">
            <span className="text-2xl">{icon}</span>
            {title}
        </h2>
        {children}
    </section>
);

const ConfigManager: React.FC<{ config: Record<AppConfigKey, string[]>; onConfigChange: () => void }> = ({ config, onConfigChange }) => {
    const [editableConfig, setEditableConfig] = useState(config);
    useEffect(() => { setEditableConfig(config); }, [config]);

    const handleAddItem = (key: AppConfigKey, value: string) => {
        if (value && !editableConfig[key].includes(value)) {
            setEditableConfig(prev => ({ ...prev, [key]: [...prev[key], value] }));
        }
    };

    const handleRemoveItem = (key: AppConfigKey, value: string) => {
        setEditableConfig(prev => ({ ...prev, [key]: prev[key].filter(i => i !== value) }));
    };

    const handleSave = async (key: AppConfigKey) => {
        try {
            await updateAppConfig(key, editableConfig[key]);
            alert(`"${key}" actualizado correctamente.`);
            onConfigChange();
        } catch (e) { alert("Error al guardar."); }
    };

    return (
        <AdminSection title="Mantenimiento de Variables del Sistema" icon="⚙️">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Object.keys(editableConfig).map((key) => (
                    <ConfigSection key={key} configKey={key as AppConfigKey} values={editableConfig[key as AppConfigKey]} onAddItem={handleAddItem} onRemoveItem={handleRemoveItem} onSave={handleSave} />
                ))}
            </div>
        </AdminSection>
    );
};

const ConfigSection: React.FC<{ configKey: AppConfigKey; values: string[]; onAddItem: any; onRemoveItem: any; onSave: any }> = ({ configKey, values, onAddItem, onRemoveItem, onSave }) => {
    const [newItem, setNewItem] = useState('');
    const titleMap: any = { OPERATORS: 'Operadores', SHIFTS: 'Turnos', WORK_TYPES: 'Jornadas', CRANES: 'Grúas', YARDS: 'Predios', CLIENTS: 'Clientes', MOVEMENT_REASONS: 'Razones Movimiento', CRANE_CHANGE_REASONS: 'Razones Cambio Grúa' };

    return (
        <div className="p-5 border-2 border-gray-100 rounded-2xl bg-gray-50/50 flex flex-col hover:border-green-200 transition-colors">
            <h3 className="font-black mb-4 text-gray-700 uppercase text-xs tracking-widest">{titleMap[configKey]}</h3>
            <ul className="flex-grow h-40 overflow-y-auto mb-4 space-y-2 pr-2 scrollbar-thin">
                {values.map(item => (
                    <li key={item} className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-100 shadow-sm text-sm font-bold text-gray-600">
                        <span>{item}</span>
                        <button onClick={() => onRemoveItem(configKey, item)} className="text-red-400 hover:text-red-600 transition-colors">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-2 mb-3">
                <input type="text" value={newItem} onChange={e => setNewItem(e.target.value)} className="flex-grow p-3 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none focus:border-green-500" placeholder="NUEVO VALOR..."/>
                <button onClick={() => { onAddItem(configKey, newItem); setNewItem(''); }} className="px-4 bg-green-600 text-white rounded-xl font-black shadow-lg hover:scale-105 transition-all">+</button>
            </div>
            <button onClick={() => onSave(configKey)} className="w-full py-3 bg-gray-800 text-white rounded-xl font-black text-xs shadow-lg hover:bg-black transition-all uppercase tracking-widest">Guardar Cambios</button>
        </div>
