        />
    </div>
);

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { findLastMovementByContainer, getAllDataForExport, getAppConfig, updateAppConfig } from '../services/db';
import { Movement, AppConfigKey, Session, CraneUsage } from '../types';

interface AdminDashboardProps {
    setView: (view: 'LOGIN' | 'OPERATOR') => void;
}

declare const XLSX: any;

export default function AdminDashboard({ setView }: AdminDashboardProps) {
    const [viewMode, setViewMode] = useState<'main' | 'efficiency'>('main');
    const [containerNumber, setContainerNumber] = useState('');
    const [searchResult, setSearchResult] = useState<Movement | null | undefined>(undefined);
    const [isLoading, setIsLoading] = useState(false);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CRANES: [], YARDS: [],
        CLIENTS: [], MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });

    const [dateRange, setDateRange] = useState('48h'); 
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const fetchConfig = useCallback(async () => {
        const appConfig = await getAppConfig();
        setConfig(appConfig);
    }, []);

    useEffect(() => {
        fetchConfig();
    }, [fetchConfig]);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!/^\d{7}$/.test(containerNumber)) {
            alert("Ingrese 7 dígitos.");
            return;
        }
        setIsLoading(true);
        const result = await findLastMovementByContainer(containerNumber);
        setSearchResult(result);
        setIsLoading(false);
    };

    const getFilteredData = async () => {
        const { sessions, craneUsages, movements, workshopRecords } = await getAllDataForExport();
        if (dateRange === 'all') return { sessions, craneUsages, movements, workshopRecords };

        const now = new Date();
        let startDateFilter: Date;
        let endDateFilter: Date = now;

        switch (dateRange) {
            case 'today':
                startDateFilter = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
                break;
            case '48h':
                startDateFilter = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                break;
            case '7d':
                startDateFilter = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                startDateFilter.setHours(0, 0, 0, 0);
                break;
            case 'custom':
                 if (startDate) {
                    const [y, m, d] = startDate.split('-').map(Number);
                    startDateFilter = new Date(y, m - 1, d, 0, 0, 0, 0);
                } else {
                    startDateFilter = new Date(0);
                }
                if (endDate) {
                    const [y, m, d] = endDate.split('-').map(Number);
                    endDateFilter = new Date(y, m - 1, d, 23, 59, 59, 999);
                }
                break;
            default:
                startDateFilter = new Date(0);
        }

        const startTs = startDateFilter.getTime();
        const endTs = endDateFilter.getTime();

        const filteredMovements = movements.filter(m => {
            const ts = new Date(m.timestamp).getTime();
            return ts >= startTs && ts <= endTs;
        });

        const filteredUsages = craneUsages.filter(cu => {
            const cuStart = new Date(cu.startTime).getTime();
            const cuEnd = cu.endTime ? new Date(cu.endTime).getTime() : now.getTime();
            return cuStart <= endTs && cuEnd >= startTs;
        });

        const relevantSessionIds = new Set([
            ...filteredMovements.map(m => m.sessionId),
            ...filteredUsages.map(cu => cu.sessionId)
        ]);

        const filteredSessions = sessions.filter(s => relevantSessionIds.has(s.id!));

        return { 
            sessions: filteredSessions, 
            craneUsages: filteredUsages, 
            movements: filteredMovements,
            workshopRecords: workshopRecords // Opcional
        };
    };

    const handleExportConsolidated = async () => {
        const { sessions, craneUsages, movements } = await getFilteredData();
        if (craneUsages.length === 0) {
            alert("No se encontraron registros en el rango seleccionado.");
            return;
        }

        const sessionMap = new Map<number, Session>(sessions.map(s => [s.id!, s]));
        const clients = config.CLIENTS || [];
        const reasons = config.MOVEMENT_REASONS || [];

        const dataForExport = craneUsages.map(usage => {
            const session = sessionMap.get(usage.sessionId);
            // IMPORTANTE: Se cuentan los movimientos que pertenecen a este uso específico de grúa
            const usageMovements = movements.filter(m => m.craneUsageId === usage.id);
            const hrsCrane = usage.endHourMeter && usage.startHourMeter ? (usage.endHourMeter - usage.startHourMeter) : 0;
            const isClosed = usage.endTime !== undefined;

            const row: any = {
                'FECHA': session ? new Date(session.startTime).toLocaleDateString() : 'N/A',
                'ESTADO': isClosed ? 'FINALIZADO' : 'TRABAJANDO',
                'OPERADOR': session?.operator || 'N/A',
                'TURNO': session?.shift || 'N/A',
                'GRÚA': usage.crane,
                'PREDIO': usage.yard,
                'HORÓMETRO INICIAL': usage.startHourMeter,
                'HORÓMETRO FINAL': usage.endHourMeter || 'ACTIVO',
                'HORAS DE USO': isClosed ? hrsCrane.toFixed(2) : 'EN CURSO',
            };

            let totalMovs = 0;
            clients.forEach(client => {
                const count = usageMovements.filter(m => m.client === client).length;
                row[`CLIENTE: ${client}`] = count;
                totalMovs += count;
            });
            row['TOTAL POR CLIENTES'] = totalMovs;

            reasons.forEach(reason => {
                const count = usageMovements.filter(m => m.reason === reason).length;
                row[`MOTIVO: ${reason}`] = count;
            });
            row['TOTAL GENERAL MOVIMIENTOS'] = usageMovements.length;

            return row;
        });

        const worksheet = XLSX.utils.json_to_sheet(dataForExport);
        const workbook = XLSX.utils.book_new();
