                                </select>
                            </div>
                            {dateRange === 'custom' && (
                                <div className="space-y-2">
                                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2.5 bg-gray-50 border rounded-lg text-sm font-bold"/>
                                </div>
                            )}
                        </div>
                        <div className="flex flex-col gap-4">
                             <button onClick={handleExportConsolidated} className="w-full py-4 bg-green-600 text-white rounded-xl hover:bg-green-700 font-black shadow-lg transition-all flex items-center justify-center gap-2">
                                 <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2h8a2 2 0 002-2V7.414A2 2 0 0015.414 6L12 2.586A2 2 0 0010.586 2H6zm5 6a1 1 0 10-2 0v3.586l-1.293-1.293a1 1 0 10-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 11.586V8z" clipRule="evenodd" /></svg>
