import React, { useState, useEffect, useMemo } from 'react';
import { getAllDataForExport } from '../services/db';
import { Session, CraneUsage, Movement } from '../types';

interface EfficiencyStat {
    movs: number;
    hours: number;
}

interface EfficiencyDashboardProps {
    onBack: () => void;
}

export default function EfficiencyDashboard({ onBack }: EfficiencyDashboardProps) {
    const [data, setData] = useState<{sessions: Session[], usages: CraneUsage[], movements: Movement[]}>({sessions:[], usages:[], movements:[]});
    const [filter, setFilter] = useState<'day' | 'week' | 'month'>('day');

    useEffect(() => {
        const fetch = async () => {
            const all = await getAllDataForExport();
            const now = new Date();
            let start = new Date();
            if (filter === 'day') start.setHours(0,0,0,0);
            else if (filter === 'week') {
                const day = now.getDay();
                start = new Date(now.getTime() - day * 24 * 60 * 60 * 1000);
                start.setHours(0,0,0,0);
            } else {
                start = new Date(now.getFullYear(), now.getMonth(), 1);
            }

            const filteredSessions = all.sessions.filter(s => new Date(s.startTime) >= start);
            const sIds = new Set(filteredSessions.map(s => s.id));
            setData({
                sessions: filteredSessions,
                usages: all.craneUsages.filter(cu => sIds.has(cu.sessionId)),
                movements: all.movements.filter(m => sIds.has(m.sessionId))
            });
        };
        fetch();
    }, [filter]);

    const stats = useMemo(() => {
        const opStats: Record<string, EfficiencyStat> = {};
        const craneStats: Record<string, EfficiencyStat> = {};

        data.usages.forEach(u => {
            const session = data.sessions.find(s => s.id === u.sessionId);
            const op = session?.operator || 'Desconocido';
            const hours = u.endHourMeter && u.startHourMeter ? (u.endHourMeter - u.startHourMeter) : 0;
            const movs = data.movements.filter(m => m.craneUsageId === u.id).length;

            if (!opStats[op]) opStats[op] = {movs: 0, hours: 0};
            opStats[op].movs += movs;
            opStats[op].hours += hours;

            if (!craneStats[u.crane]) craneStats[u.crane] = {movs: 0, hours: 0};
            craneStats[u.crane].movs += movs;
            craneStats[u.crane].hours += hours;
        });

        return { operators: opStats, cranes: craneStats };
    }, [data]);

    const totalHours = useMemo(() => 
        Object.values(stats.cranes).reduce((acc: number, curr: EfficiencyStat) => acc + curr.hours, 0)
    , [stats.cranes]);

    return (
        <div className="container mx-auto p-4 space-y-8 max-w-7xl animate-in fade-in slide-in-from-right duration-500">
            <header className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-2xl shadow-xl border-b-4 border-blue-600">
                <div className="flex items-center gap-4">
                    <div className="bg-blue-600 p-3 rounded-xl shadow-lg">
                        <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Eficiencia Gerencial</h1>
                        <p className="text-sm font-bold text-blue-600">Indicadores de Desempeño (KPIs)</p>
                    </div>
                </div>
                <div className="flex gap-2 bg-gray-100 p-1.5 rounded-xl">
                    {(['day', 'week', 'month'] as const).map(f => (
                        <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${filter === f ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                            {f === 'day' ? 'Hoy' : f === 'week' ? 'Semana' : 'Mes'}
                        </button>
                    ))}
                    <button onClick={onBack} className="ml-4 px-4 py-2 bg-gray-800 text-white rounded-lg text-xs font-black uppercase hover:bg-black transition-all">SALIR</button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <KPICard title="Total Movimientos" value={data.movements.length} color="blue" />
                <KPICard title="Horas Totales" value={totalHours.toFixed(1)} color="green" />
                <KPICard title="Promedio MPH" value={totalHours > 0 ? (data.movements.length / totalHours).toFixed(1) : 0} color="orange" unit="mov/hr" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <AdminSection title="Rendimiento por Operador (MPH)" icon="👤">
                    <div className="space-y-4">
                        {(Object.entries(stats.operators) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.operators) as [string, EfficiencyStat][]).sort((a,b) => (b[1].movs/b[1].hours) - (a[1].movs/a[1].hours)).map(([name, s]) => {
                            const mph = s.hours > 0 ? (s.movs / s.hours) : 0;
                            return (
                                <EfficiencyBar key={name} label={name} value={mph} max={25} />
                            );
                        }) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>

                <AdminSection title="Uso por Grúa (Horas)" icon="🏗️">
                    <div className="space-y-4">
                        {(Object.entries(stats.cranes) as [string, EfficiencyStat][]).length > 0 ? (Object.entries(stats.cranes) as [string, EfficiencyStat][]).sort((a,b) => b[1].hours - a[1].hours).map(([crane, s]) => (
                            <EfficiencyBar key={crane} label={crane} value={s.hours} max={24} color="bg-green-500" />
                        )) : <p className="text-center text-gray-400 py-10 italic">No hay registros para este período.</p>}
                    </div>
                </AdminSection>
            </div>
        </div>
    );
}

function KPICard({ title, value, color, unit }: { title: string; value: string | number; color: string; unit?: string }) {
    const colors: any = { blue: 'text-blue-600', green: 'text-green-600', orange: 'text-orange-600' };
    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg border-l-8 border-current text-gray-800" style={{borderColor: color === 'blue' ? '#2563eb' : color === 'green' ? '#16a34a' : '#ea580c'}}>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{title}</p>
            <p className={`text-4xl font-black ${colors[color]}`}>{value} <span className="text-sm font-bold text-gray-400">{unit}</span></p>
        </div>
    );
}

function AdminSection({ title, icon, children }: { title: string; icon?: string; children: React.ReactNode }) {
    return (
        <section className="bg-white p-8 rounded-3xl shadow-xl border border-gray-50">
            <h2 className="text-xl font-black mb-6 text-gray-800 flex items-center gap-3 uppercase tracking-tighter">
                <span className="text-2xl">{icon}</span>
                {title}
            </h2>
            {children}
        </section>
    );
}

function EfficiencyBar({ label, value, max, color = "bg-blue-600" }: { label: string; value: number; max: number; color?: string }) {
    const percentage = Math.min((value / max) * 100, 100);
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-xs font-bold uppercase">
                <span className="text-gray-700">{label}</span>
                <span className="text-gray-900">{value.toFixed(1)}</span>
            </div>
            <div className="w-full bg-gray-100 h-4 rounded-full overflow-hidden border border-gray-200">
                <div className={`${color} h-full transition-all duration-1000`} style={{ width: `${percentage}%` }}></div>
            </div>
        </div>
    );
}

