                        </button>
                    </li>
                ))}
            </ul>
            <div className="flex gap-2 mb-3">
                <input type="text" value={newItem} onChange={e => setNewItem(e.target.value)} className="flex-grow p-3 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none focus:border-green-500" placeholder="NUEVO VALOR..."/>
                <button onClick={() => { onAddItem(configKey, newItem); setNewItem(''); }} className="px-4 bg-green-600 text-white rounded-xl font-black shadow-lg hover:scale-105 transition-all">+</button>
