        />
    </div>
);

import React, { useState, useContext, useEffect, useCallback } from 'react';
import { SessionContext } from '../contexts/SessionContext';
import { Movement, AppConfigKey, WorkshopRecord, CraneUsage } from '../types';
import { addMovement, getRecentMovements, changeCrane, changeYard, endCurrentSessionWithMeters, countSessionMovements, getAppConfig, getLastHourMeterForCrane, addWorkshopRecord, getLatestUsageInSession, getPendingSyncCount, getPendingHourMetersForSession, checkCraneAvailability, getAllActiveCranes } from '../services/db';

interface OperatorDashboardProps {
    setView: (view: 'LOGIN' | 'ADMIN') => void;
}

const getReasonStyle = (reason: string): { emoji: string; color: string } => {
    switch (reason) {
        case "Recepción": return { emoji: "📥", color: "bg-green-500 hover:bg-green-600" };
        case "Despacho": return { emoji: "📤", color: "bg-blue-500 hover:bg-blue-600" };
        case "Re-estibas": return { emoji: "🔄", color: "bg-yellow-500 hover:bg-yellow-600" };
        case "Cambios de chasis": return { emoji: "🚚", color: "bg-purple-500 hover:bg-purple-600" };
        case "Revisión en Racks": return { emoji: "✅", color: "bg-teal-500 hover:bg-teal-600" };
        case "Otro": return { emoji: "❓", color: "bg-gray-500 hover:bg-gray-600" };
        default: return { emoji: "🔘", color: "bg-gray-500 hover:bg-gray-600" };
    }
};

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
        <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in duration-200">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="text-lg font-black text-gray-800 uppercase tracking-tight">{title}</h3>
                <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-100">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>
            <div className="p-6 max-h-[80vh] overflow-y-auto">
                {children}
            </div>
        </div>
    </div>
);

export default function OperatorDashboard({ setView }: OperatorDashboardProps) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [config, setConfig] = useState<Record<AppConfigKey, string[]>>({
        OPERATORS: [], SHIFTS: [], WORK_TYPES: [], CLIENTS: [], CRANES: [], YARDS: [],
        MOVEMENT_REASONS: [], CRANE_CHANGE_REASONS: []
    });
    const [client, setClient] = useState('');
    const [containerNumber, setContainerNumber] = useState(() => localStorage.getItem('staktrak_draft_container') || '');
    const [recentMovements, setRecentMovements] = useState<Movement[]>([]);
    const [totalMovements, setTotalMovements] = useState(0);
    const [pendingSync, setPendingSync] = useState(0);
    const [isCraneModalOpen, setCraneModalOpen] = useState(false);
    const [isYardModalOpen, setYardModalOpen] = useState(false);
    const [isWorkshopModalOpen, setWorkshopModalOpen] = useState(false);
    const [isEndSessionModalOpen, setEndSessionModalOpen] = useState(false);
    const [isRackMultiplierModalOpen, setRackMultiplierModalOpen] = useState(false);
    const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });
    const [showOnlyCurrentCrane, setShowOnlyCurrentCrane] = useState(false);

    useEffect(() => {
        const fetchConfig = async () => setConfig(await getAppConfig());
        fetchConfig();
    }, []);

    useEffect(() => { localStorage.setItem('staktrak_draft_container', containerNumber); }, [containerNumber]);

    const updateSyncStatus = useCallback(async () => setPendingSync(await getPendingSyncCount()), []);

    useEffect(() => {
        const interval = setInterval(updateSyncStatus, 5000);
        updateSyncStatus();
        return () => clearInterval(interval);
    }, [updateSyncStatus]);

    const fetchMovements = useCallback(async () => {
        if (activeSession?.session.id) {
            const craneFilter = showOnlyCurrentCrane ? activeSession.craneUsage.id : undefined;
            const movements = await getRecentMovements(activeSession.session.id, 5, craneFilter);
            setRecentMovements(movements);
            setTotalMovements(await countSessionMovements(activeSession.session.id));
        }
    }, [activeSession, showOnlyCurrentCrane]);

    useEffect(() => {
        if (activeSession) {
            if (config.CLIENTS.length > 0) setClient(activeSession.session.client || config.CLIENTS[0]);
            fetchMovements();
        } else { setView('LOGIN'); }
    }, [activeSession, fetchMovements, setView, config.CLIENTS]);

    const handleLogMovement = async (reason: string) => {
        if (!activeSession) return;
        if (!/^\d{7}$/.test(containerNumber)) {
            setStatusMessage({ type: 'error', text: 'El número debe tener 7 dígitos.' });
            setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
            return;
        }
        if (reason === "Revisión en Racks") { setRackMultiplierModalOpen(true); return; }
        await processMovementExecution(reason, 1);
    };

    const processMovementExecution = async (reason: string, count: number) => {
        if (!activeSession) return;
        try {
            const getBase = () => ({
                sessionId: activeSession.session.id!,
                craneUsageId: activeSession.craneUsage.id!,
                timestamp: new Date(),
                client,
                containerNumber,
                reason,
                yard: activeSession.craneUsage.yard,
                crane: activeSession.craneUsage.crane,
                operator: activeSession.session.operator,
            });
            for (let i = 0; i < count; i++) await addMovement(getBase());
            setStatusMessage({ type: 'success', text: `Registrado: ${reason}` });
            setContainerNumber('');
            localStorage.removeItem('staktrak_draft_container');
            fetchMovements();
            updateSyncStatus();
            setTimeout(() => setStatusMessage({ type: '', text: '' }), 3000);
        } catch (error) { console.error(error); }
    };

    if (!activeSession) return null;

    return (
        <div className="container mx-auto p-4 space-y-4 text-gray-900 pb-20">
             <header className="flex justify-between items-center bg-white p-3 rounded-xl shadow-sm border">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 flex items-center justify-center bg-green-50 rounded-lg">
                        <svg className="w-6 h-6 text-green-700" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 21h18M5 21V7l8-4v18M13 21V3l8 4v14" /></svg>
                    </div>
                    <div>
                        <h1 className="text-lg font-black text-green-700 leading-none uppercase tracking-tighter">SISTEMA GRÚAS</h1>
                        <p className="text-[10px] text-gray-400 font-bold uppercase">{pendingSync > 0 ? `Sincronizando ${pendingSync}...` : 'Nube OK'}</p>
                    </div>
                </div>
                <button onClick={() => setEndSessionModalOpen(true)} className="px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-black uppercase shadow-sm active:scale-95 transition-all">Finalizar</button>
            </header>

            <div className="grid grid-cols-4 gap-2 bg-gray-50 p-3 rounded-xl border border-gray-100 shadow-inner">
                <div className="text-center border-r border-gray-200">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">Operador</p>
                    <p className="text-[10px] font-black text-gray-800 uppercase truncate px-1">{activeSession.session.operator.split(' ')[0]}</p>
                </div>
                <div className="text-center border-r border-gray-200">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">Grúa</p>
                    <p className="text-[10px] font-black text-gray-800 uppercase truncate px-1">{activeSession.craneUsage.crane}</p>
                </div>
                <div className="text-center border-r border-gray-200">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">Predio</p>
                    <p className="text-[10px] font-black text-gray-800 uppercase truncate px-1">{activeSession.craneUsage.yard}</p>
                </div>
                <div className="text-center">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">Movs</p>
                    <p className="text-sm font-black text-blue-600 leading-none">{totalMovements}</p>
                </div>
            </div>

            <div className="bg-white p-5 rounded-xl shadow-md border-t-4 border-green-600">
                <div className="grid grid-cols-2 gap-3 mb-4">
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Cliente</label>
                        <select value={client} onChange={(e) => setClient(e.target.value)} disabled={activeSession.session.workType === 'Operación de Barco'} className="w-full p-2.5 border rounded-lg bg-gray-50 text-sm font-bold">
                            {config.CLIENTS.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Contenedor</label>
                        <input 
                            type="text" 
                            inputMode="numeric" 
                            pattern="[0-9]*"
                            value={containerNumber} 
                            onChange={(e) => setContainerNumber(e.target.value.replace(/\D/g, '').slice(0, 7))} 
                            placeholder="0000000" 
                            className="w-full p-2.5 border rounded-lg bg-gray-50 font-mono text-lg font-black text-center focus:ring-2 focus:ring-green-500 outline-none transition-all"
                        />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-2">
                    {config.MOVEMENT_REASONS.map((reason) => {
                        const { emoji, color } = getReasonStyle(reason);
                        return (
                            <button key={reason} onClick={() => handleLogMovement(reason)} className={`p-3 rounded-xl text-white flex flex-col items-center justify-center transition-all transform active:scale-90 shadow-sm ${color}`}>
                                <span className="text-xl mb-0.5">{emoji}</span>
                                <span className="text-[9px] font-black uppercase tracking-tight">{reason}</span>
                            </button>
                        );
                    })}
                </div>
                {statusMessage.text && <div className={`mt-3 p-2 rounded text-center font-bold text-xs ${statusMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{statusMessage.text}</div>}
            </div>

            <div className="grid grid-cols-3 gap-2">
                <button onClick={() => setCraneModalOpen(true)} className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-sm hover:bg-gray-50 active:scale-95 transition-all">
                    <span className="text-xl mb-1">🔄</span>
                    <span className="text-[8px] font-black text-gray-500 uppercase">Cambiar Grúa</span>
                </button>
                <button onClick={() => setYardModalOpen(true)} className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-sm hover:bg-gray-50 active:scale-95 transition-all">
                    <span className="text-xl mb-1">📍</span>
                    <span className="text-[8px] font-black text-gray-500 uppercase">Cambiar Predio</span>
                </button>
                <button onClick={() => setWorkshopModalOpen(true)} className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-sm hover:bg-gray-50 active:scale-95 transition-all border-orange-100 bg-orange-50/20">
                    <span className="text-xl mb-1">⚠️</span>
                    <span className="text-[8px] font-black text-gray-500 uppercase text-center">Reportar Falla</span>
                </button>
            </div>

            <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                <div className="p-3 border-b bg-gray-50 flex justify-between items-center">
                    <h3 className="text-xs font-black text-gray-600 uppercase">Mis Últimos 5</h3>
                    <button onClick={() => setShowOnlyCurrentCrane(!showOnlyCurrentCrane)} className={`text-[8px] px-2 py-1 rounded font-black uppercase ${showOnlyCurrentCrane ? 'bg-green-600 text-white' : 'bg-gray-200 text-gray-500'}`}>
                        {showOnlyCurrentCrane ? activeSession.craneUsage.crane : 'Ver por Grúa'}
                    </button>
                </div>
                <table className="w-full text-left text-sm">
                    <tbody className="divide-y">
                        {recentMovements.length > 0 ? recentMovements.map(m => (
                            <tr key={m.id} className="hover:bg-gray-50">
                                <td className="px-4 py-3 font-mono font-black text-green-700 tracking-widest">{m.containerNumber}</td>
                                <td className="px-4 py-3 text-right text-[10px] text-gray-400 font-bold">{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', hour12:false})}</td>
                            </tr>
                        )) : <tr><td colSpan={2} className="px-4 py-6 text-center text-gray-300 text-xs italic">Sin movimientos aún.</td></tr>}
                    </tbody>
                </table>
            </div>

            {isCraneModalOpen && <ChangeCraneModal onClose={() => setCraneModalOpen(false)} fetchMovements={fetchMovements} config={config} />}
            {isYardModalOpen && <ChangeYardModal onClose={() => setYardModalOpen(false)} config={config} />}
            {isWorkshopModalOpen && <WorkshopModal onClose={() => setWorkshopModalOpen(false)} />}
            {isEndSessionModalOpen && <FinalizeSessionModal onClose={() => setEndSessionModalOpen(false)} />}
            {isRackMultiplierModalOpen && (
                <Modal title="Revisión en Racks" onClose={() => setRackMultiplierModalOpen(false)}>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => { processMovementExecution("Revisión en Racks", 1); setRackMultiplierModalOpen(false); }} className="p-6 bg-teal-500 text-white rounded-2xl shadow-lg active:scale-95 transition-all">
                            <span className="text-4xl font-black">1</span><br/><span className="text-[10px] uppercase font-bold">Movimiento</span>
                        </button>
                        <button onClick={() => { processMovementExecution("Revisión en Racks", 2); setRackMultiplierModalOpen(false); }} className="p-6 bg-teal-600 text-white rounded-2xl shadow-lg active:scale-95 transition-all">
                            <span className="text-4xl font-black">2</span><br/><span className="text-[10px] uppercase font-bold">Movimientos</span>
                        </button>
                    </div>
                </Modal>
            )}
        </div>
    );
}

function ChangeCraneModal({ onClose, fetchMovements, config }: { onClose: () => void, fetchMovements: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [changeReason, setChangeReason] = useState(config.CRANE_CHANGE_REASONS[0] || 'Falla mecánica');
    const [changeDetails, setChangeDetails] = useState('');
    const [oldEndHourMeter, setOldEndHourMeter] = useState('');

    const [newCrane, setNewCrane] = useState('');
    const [newStartHourMeter, setNewStartHourMeter] = useState('');

    const [lastMeter, setLastMeter] = useState<number | undefined>(undefined);
    const [isContinuing, setIsContinuing] = useState(false);
    const [error, setError] = useState('');
    const [activeCranes, setActiveCranes] = useState<Record<string, { operator: string, yard: string }>>({});

    useEffect(() => {
        const loadActives = async () => setActiveCranes(await getAllActiveCranes());
        loadActives();
    }, []);

    useEffect(() => {
        if (newCrane && activeSession) {
            setError('');
            getLatestUsageInSession(activeSession.session.id!, newCrane).then(usage => {
                if (usage && usage.endHourMeter !== undefined) {
                    setNewStartHourMeter(usage.endHourMeter.toString().replace('.', ','));
                    setIsContinuing(true);
                } else {
                    setIsContinuing(false);
                    getLastHourMeterForCrane(newCrane).then(setLastMeter);
                }
            });

            if (activeCranes[newCrane]) {
                setError(`⚠️ ALARMA: La grúa ${newCrane} está SIENDO USADA por ${activeCranes[newCrane].operator}.`);
            }
        }
    }, [newCrane, activeSession, activeCranes]);

    const handleConfirm = async () => {
        if (!activeSession || !newCrane || !newStartHourMeter || !oldEndHourMeter || !changeReason) {
            setError('Complete todos los campos obligatorios.');
            return;
        }

        if (changeReason === 'Falla mecánica' && !changeDetails.trim()) {
            setError('Debe indicar los detalles de la falla mecánica.');
            return;
        }

        const busyInfo = await checkCraneAvailability(newCrane);
        if (busyInfo) {
            setError(`🚨 BLOQUEADO: La ${newCrane} está en uso por ${busyInfo.operator}.`);
            return;
        }

        const startVal = parseFloat(newStartHourMeter.replace(',', '.'));
        const oldEndVal = parseFloat(oldEndHourMeter.replace(',', '.'));
        if (isNaN(startVal) || isNaN(oldEndVal)) {
            setError('Formato de horómetro inválido.');
            return;
        }

        try {
            const usage = await changeCrane(
                activeSession.craneUsage.id!, 
                changeReason, 
                newCrane, 
                activeSession.craneUsage.yard, 
                startVal, 
                activeSession.session.id!,
                oldEndVal,
                changeDetails
            );
            setActiveSession({ ...activeSession, craneUsage: usage });
            fetchMovements();
            onClose();
        } catch (e) { console.error(e); }
    };

    return (
        <Modal title="🔄 Cambio de Grúa" onClose={onClose}>
            <div className="space-y-5">
                {error && (
                    <div className="p-3 bg-red-100 text-red-700 text-[10px] font-black rounded-lg border-2 border-red-200 uppercase animate-pulse">
                        {error}
                    </div>
                )}

                <div className="space-y-3">
                    <div>
                        <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Motivo del Cambio</label>
                        <select value={changeReason} onChange={e => setChangeReason(e.target.value)} className="w-full p-3 border rounded-xl bg-gray-50 font-bold text-sm">
                            {config.CRANE_CHANGE_REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                    </div>

                    {changeReason === 'Falla mecánica' && (
                        <div className="animate-in slide-in-from-top-2 duration-300">
                            <label className="block text-[10px] font-black text-red-600 uppercase mb-1">Comentarios de Falla Mecánica</label>
                            <textarea 
                                value={changeDetails} 
                                onChange={e => setChangeDetails(e.target.value)} 
                                placeholder="Describa el fallo técnico..."
                                className="w-full p-3 border-2 border-red-100 rounded-xl text-sm bg-red-50 focus:border-red-500 outline-none min-h-[80px]" 
                            />
                        </div>
                    )}
                </div>

                <hr className="border-gray-100" />

                <div className="p-4 bg-orange-50/50 rounded-xl border border-orange-100">
                    <p className="text-[10px] font-black text-orange-800 uppercase mb-3 flex items-center gap-1">
                        Paso 1: Entregar {activeSession?.craneUsage.crane}
                    </p>
                    <div>
                        <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Horómetro Final</label>
                        <input 
                            type="text" 
                            inputMode="decimal"
                            value={oldEndHourMeter} 
                            onChange={e => setOldEndHourMeter(e.target.value.replace('.', ',').replace(/[^0-9,]/g, ''))} 
                            placeholder="0000,00"
                            className="w-full p-3 border rounded-xl font-black text-xl text-center bg-white" 
                        />
                        <p className="text-[9px] text-gray-400 font-bold mt-1 uppercase text-right">Inicial: {activeSession?.craneUsage.startHourMeter.toString().replace('.', ',')}</p>
                    </div>
                </div>

                <div className="p-4 bg-green-50/50 rounded-xl border border-green-100">
                    <p className="text-[10px] font-black text-green-800 uppercase mb-3 flex items-center gap-1">
                        Paso 2: Recibir Nueva Grúa
                    </p>
                    <div className="space-y-3">
                        <div>
                            <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Nueva Grúa</label>
                            <select 
                                value={newCrane} 
                                onChange={e => setNewCrane(e.target.value)} 
                                className={`w-full p-3 border rounded-xl bg-white font-bold text-sm ${activeCranes[newCrane] ? 'border-red-500 text-red-600' : 'border-gray-200'}`}
                            >
                                <option value="">Seleccione Equipo...</option>
                                {config.CRANES.filter(c => c !== activeSession?.craneUsage.crane).map(c => (
                                    <option key={c} value={c} className={activeCranes[c] ? 'text-red-500 font-black' : ''}>
                                        {c} {activeCranes[c] ? '🔴 (OCUPADA)' : ''}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Horómetro Inicial</label>
                            <input 
                                type="text" 
                                inputMode="decimal"
                                value={newStartHourMeter} 
                                onChange={e => setNewStartHourMeter(e.target.value.replace('.', ',').replace(/[^0-9,]/g, ''))} 
                                readOnly={isContinuing} 
                                placeholder="0000,00"
                                className="w-full p-3 border rounded-xl font-black text-xl text-center bg-white" 
                            />
                            {lastMeter !== undefined && !isContinuing && (
                                <p className="text-[9px] text-blue-600 font-bold mt-1 uppercase text-right">Último reg: {lastMeter.toString().replace('.', ',')}</p>
                            )}
                        </div>
                    </div>
                </div>

                <button 
                    onClick={handleConfirm} 
                    disabled={!!activeCranes[newCrane] || !newCrane}
                    className={`w-full py-4 text-white rounded-xl font-black uppercase shadow-lg active:scale-95 transition-all ${!!activeCranes[newCrane] || !newCrane ? 'bg-gray-300 cursor-not-allowed' : 'bg-gray-900 hover:bg-black'}`}
                >
                    {!!activeCranes[newCrane] ? 'EQUIPO OCUPADO' : 'Finalizar y Cambiar'}
                </button>
            </div>
        </Modal>
    );
}

function FinalizeSessionModal({ onClose }: { onClose: () => void }) {
    const { activeSession, logout } = useContext(SessionContext);
    const [pendingUsages, setPendingUsages] = useState<CraneUsage[]>([]);
    const [meters, setMeters] = useState<Record<number, string>>({});
    const [error, setError] = useState('');

    useEffect(() => {
        if (activeSession?.session.id) {
            getPendingHourMetersForSession(activeSession.session.id).then(setPendingUsages);
        }
    }, [activeSession]);

    const handleFinalize = async () => {
        if (!activeSession) return;
        const finalMeters: Record<number, number> = {};
        for (const usage of pendingUsages) {
            const val = parseFloat((meters[usage.id!] || '').replace(',', '.'));
            if (isNaN(val)) { setError('Complete todos los horómetros.'); return; }
            if (val < usage.startHourMeter) {
                if (!window.confirm(`El horómetro de ${usage.crane} (${val}) es menor al inicial (${usage.startHourMeter}). ¿Continuar?`)) return;
            }
            finalMeters[usage.id!] = val;
        }

        try {
            await endCurrentSessionWithMeters(activeSession.session.id!, finalMeters);
            logout();
        } catch (e) { console.error(e); }
    };

    return (
        <Modal title="🏁 Finalizar Jornada" onClose={onClose}>
            <div className="space-y-6">
                <p className="text-xs text-gray-500 font-bold uppercase text-center border-b pb-4">Ingrese horómetros finales para cerrar sesión</p>
                {pendingUsages.map(usage => (
                    <div key={usage.id} className="p-4 bg-gray-50 rounded-xl border border-gray-100 space-y-3">
                        <div className="flex justify-between items-center border-b pb-2">
                            <span className="text-lg font-black text-green-700">{usage.crane}</span>
                            <span className="text-[10px] font-black text-gray-400">INICIAL: {usage.startHourMeter.toString().replace('.', ',')}</span>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Horómetro Final</label>
                            <input 
                                type="text" 
                                inputMode="decimal"
                                value={meters[usage.id!] || ''} 
                                onChange={e => setMeters({...meters, [usage.id!]: e.target.value.replace('.', ',').replace(/[^0-9,]/g, '')})} 
                                placeholder="0000,00" 
                                className="w-full p-3 border rounded-lg font-black text-center text-lg bg-white" 
                            />
                        </div>
                    </div>
                ))}
                {error && <p className="text-red-600 text-[10px] font-black uppercase text-center">{error}</p>}
                <div className="grid grid-cols-2 gap-3 pt-4">
                    <button onClick={onClose} className="py-3 bg-gray-200 text-gray-700 rounded-lg font-black uppercase">Cancelar</button>
                    <button onClick={handleFinalize} className="py-3 bg-red-600 text-white rounded-lg font-black uppercase shadow-lg">Cerrar Sesión</button>
                </div>
            </div>
        </Modal>
    );
}

function ChangeYardModal({ onClose, config }: { onClose: () => void, config: Record<AppConfigKey, string[]> }) {
    const { activeSession, setActiveSession } = useContext(SessionContext);
    const [newYard, setNewYard] = useState(activeSession?.craneUsage.yard || '');
    const handleConfirm = async () => {
        if (!activeSession) return;
        await changeYard(activeSession.craneUsage.id!, newYard);
        setActiveSession({ ...activeSession, craneUsage: { ...activeSession.craneUsage, yard: newYard } });
        onClose();
    };
    return (
        <Modal title="📍 Cambiar Predio" onClose={onClose}>
            <div className="space-y-4">
                <select value={newYard} onChange={e => setNewYard(e.target.value)} className="w-full p-3 border rounded-lg bg-gray-50 font-bold text-sm">
                    {config.YARDS.map(y => <option key={y} value={y}>{y}</option>)}
                </select>
                <button onClick={handleConfirm} className="w-full py-3 bg-green-600 text-white rounded-lg font-black uppercase">Confirmar</button>
            </div>
        </Modal>
    );
}

function WorkshopModal({ onClose }: { onClose: () => void }) {
    const { activeSession } = useContext(SessionContext);
    const [details, setDetails] = useState('');
    const handleSubmit = async () => {
        if (!activeSession || !details) return;
        await addWorkshopRecord({ sessionId: activeSession.session.id!, craneUsageId: activeSession.craneUsage.id!, timestamp: new Date(), crane: activeSession.craneUsage.crane, details });
        onClose();
    };
    return (
        <Modal title="⚠️ Reportar Falla Mecánica" onClose={onClose}>
            <div className="space-y-4">
                <div className="p-3 bg-orange-50 border border-orange-100 rounded-xl">
                    <p className="text-[10px] font-black text-orange-800 uppercase leading-none mb-1">Equipo bajo reporte</p>
                    <p className="text-lg font-black text-gray-800 uppercase">{activeSession?.craneUsage.crane}</p>
                </div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Detalles del Fallo</label>
                <textarea value={details} onChange={(e) => setDetails(e.target.value)} placeholder="Ej: Fuga de hidráulico en manguera principal, ruidos en motor, etc..." className="w-full p-4 border rounded-xl bg-gray-50 text-sm min-h-[120px] focus:ring-2 focus:ring-orange-500 outline-none transition-all" />
                <button onClick={handleSubmit} className="w-full py-4 bg-orange-600 text-white rounded-xl font-black uppercase shadow-lg active:scale-95 transition-all">
                    Enviar Reporte Técnico
                </button>
            </div>
        </Modal>
    );
}

import Dexie, { type Table } from 'dexie';
import { Session, CraneUsage, Movement, AppConfig, AppConfigKey, WorkshopRecord, ActiveSession } from '../types';
import { 
    INITIAL_OPERATORS, INITIAL_SHIFTS, INITIAL_WORK_TYPES, INITIAL_CRANES, 
    INITIAL_YARDS, INITIAL_CLIENTS, INITIAL_MOVEMENT_REASONS, INITIAL_CRANE_CHANGE_REASONS
} from '../constants';
import { syncPayloadToGoogle } from './sync';

const db = new Dexie('CraneDB') as Dexie & {
  sessions: Table<Session, number>;
  craneUsages: Table<CraneUsage, number>;
  movements: Table<Movement, number>;
  workshopRecords: Table<WorkshopRecord, number>;
  appConfig: Table<AppConfig, AppConfigKey>;
  syncQueue: Table<{ id?: number; payload: any; status: 'pending' | 'failed'; timestamp: Date }, number>;
};

db.version(6).stores({
  sessions: '++id, operator, startTime, endTime',
  craneUsages: '++id, sessionId, crane, startTime, endTime',
  movements: '++id, sessionId, craneUsageId, timestamp, containerNumber',
  workshopRecords: '++id, sessionId, craneUsageId, timestamp, crane',
  appConfig: '&key',
  syncQueue: '++id, status'
});

// Función para cargar los datos históricos
const seedHistoricalData = async () => {
    const isSeeded = localStorage.getItem('staktrak_historical_v1_seeded');
    if (isSeeded) return;

    await db.transaction('rw', [db.sessions, db.craneUsages, db.movements], async () => {
        const today = new Date();
        const yesterday = new Date(today);
        yesterday.setDate(today.getDate() - 1);

        const s1Id = await db.sessions.add({
            operator: 'Danny Arroyo', shift: 'Nocturno', workType: 'Jornada Normal',
            startTime: new Date(yesterday.setHours(21, 0, 0)), endTime: new Date(today.setHours(5, 0, 0))
        });
        const u1Id = await db.craneUsages.add({
            sessionId: s1Id, crane: '3 Kalmar', yard: 'PREDIO_3', startHourMeter: 307100,
            endHourMeter: 307107, startTime: new Date(yesterday.setHours(21, 10, 0)), endTime: new Date(today.setHours(5, 0, 0))
        });
        await db.movements.bulkAdd([
            { sessionId: s1Id, craneUsageId: u1Id, timestamp: new Date(yesterday.setHours(21, 17, 20)), client: 'Otro', containerNumber: '0000001', reason: 'Recepción', yard: 'PREDIO_3', crane: '3 Kalmar', operator: 'Danny Arroyo' },
            { sessionId: s1Id, craneUsageId: u1Id, timestamp: new Date(yesterday.setHours(21, 17, 22)), client: 'Otro', containerNumber: '0000002', reason: 'Recepción', yard: 'PREDIO_3', crane: '3 Kalmar', operator: 'Danny Arroyo' }
        ]);
    });

    localStorage.setItem('staktrak_historical_v1_seeded', 'true');
};

export const initializeDb = async () => {
    try {
        await db.open();
    } catch (err) {
        console.error("Error abriendo la base de datos:", err);
    }

    const configCount = await db.appConfig.count();
    if (configCount === 0) {
        await db.appConfig.bulkPut([
            { key: 'OPERATORS', values: INITIAL_OPERATORS },
            { key: 'SHIFTS', values: INITIAL_SHIFTS },
            { key: 'WORK_TYPES', values: INITIAL_WORK_TYPES },
            { key: 'CRANES', values: INITIAL_CRANES },
            { key: 'YARDS', values: INITIAL_YARDS },
            { key: 'CLIENTS', values: INITIAL_CLIENTS },
            { key: 'MOVEMENT_REASONS', values: INITIAL_MOVEMENT_REASONS },
            { key: 'CRANE_CHANGE_REASONS', values: INITIAL_CRANE_CHANGE_REASONS },
        ]);
    }

    await seedHistoricalData();
    // Cambiado de 30s a 60s para evitar ráfagas y duplicados
    setInterval(processSyncQueue, 60000);
};

const formatTime24h = (date: Date) => {
    const h = date.getHours().toString().padStart(2, '0');
    const m = date.getMinutes().toString().padStart(2, '0');
    const s = date.getSeconds().toString().padStart(2, '0');
    return `${h}:${m}:${s}`;
};

const generateRequestId = () => {
    return `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
};

const enqueueSync = async (type: string, data: any) => {
    const payload = { 
        event_type: type,
        request_id: generateRequestId(), // ID único para evitar duplicados en el backend
        server_timestamp: new Date().toISOString(),
        ...data 
    };
    await db.syncQueue.add({ payload, status: 'pending', timestamp: new Date() });
    if (navigator.onLine) processSyncQueue();
};

export const processSyncQueue = async () => {
    if (!navigator.onLine) return;
    try {
        const pending = await db.syncQueue.where('status').equals('pending').toArray();
        for (const item of pending) {
            const success = await syncPayloadToGoogle(item.payload);
            if (success) await db.syncQueue.delete(item.id!);
            else await db.syncQueue.update(item.id!, { status: 'failed' });
        }
    } catch (err) { console.error(err); }
};

export const getPendingSyncCount = async () => await db.syncQueue.count();

export const getActiveSessionFromDb = async (): Promise<ActiveSession | null> => {
    const openSession = await db.sessions.filter(s => s.endTime === undefined).reverse().first();
    if (!openSession || !openSession.id) return null;
    const activeUsage = await db.craneUsages.where('sessionId').equals(openSession.id).filter(cu => cu.endTime === undefined).reverse().first();
    if (!activeUsage) return null;
    return { session: openSession, craneUsage: activeUsage };
};

export const getAppConfig = async (): Promise<Record<AppConfigKey, string[]>> => {
    const configArray = await db.appConfig.toArray();
    const configMap = configArray.reduce((acc, curr) => { acc[curr.key] = curr.values; return acc; }, {} as Partial<Record<AppConfigKey, string[]>>);
    return {
        OPERATORS: configMap.OPERATORS || [], SHIFTS: configMap.SHIFTS || [], WORK_TYPES: configMap.WORK_TYPES || [],
        CRANES: configMap.CRANES || [], YARDS: configMap.YARDS || [], CLIENTS: configMap.CLIENTS || [],
        MOVEMENT_REASONS: configMap.MOVEMENT_REASONS || [], CRANE_CHANGE_REASONS: configMap.CRANE_CHANGE_REASONS || [],
    };
}

export const updateAppConfig = async (key: AppConfigKey, values: string[]): Promise<void> => {
    await db.appConfig.put({ key, values });
}

export const getLastHourMeterForCrane = async (crane: string): Promise<number | undefined> => {
    const usages = await db.craneUsages.where('crane').equals(crane).filter(cu => cu.endHourMeter !== undefined).toArray();
    if (usages.length === 0) return undefined;
    const latest = usages.sort((a, b) => new Date(b.endTime!).getTime() - new Date(a.endTime!).getTime())[0];
    return latest.endHourMeter;
};

export const getLatestUsageInSession = async (sessionId: number, crane: string): Promise<CraneUsage | undefined> => {
    const usages = await db.craneUsages.where('sessionId').equals(sessionId).filter(cu => cu.crane === crane && cu.endHourMeter !== undefined).toArray();
    if (usages.length === 0) return undefined;
    return usages.sort((a, b) => new Date(b.endTime!).getTime() - new Date(a.endTime!).getTime())[0];
};

/**
 * Retorna información de la sesión activa para una grúa específica, si existe.
 */
export const checkCraneAvailability = async (craneName: string): Promise<{ operator: string, yard: string } | null> => {
    const activeUsage = await db.craneUsages
        .where('crane').equals(craneName)
        .filter(cu => cu.endTime === undefined)
        .first();

    if (activeUsage) {
        const session = await db.sessions.get(activeUsage.sessionId);
        if (session) {
            return { operator: session.operator, yard: activeUsage.yard };
        }
    }
    return null;
};

/**
 * Retorna un mapa de todas las grúas actualmente activas en el sistema.
 */
export const getAllActiveCranes = async (): Promise<Record<string, { operator: string, yard: string }>> => {
    const activeUsages = await db.craneUsages.filter(cu => cu.endTime === undefined).toArray();
    const result: Record<string, { operator: string, yard: string }> = {};
    for (const usage of activeUsages) {
        const session = await db.sessions.get(usage.sessionId);
        if (session) {
            result[usage.crane] = { operator: session.operator, yard: usage.yard };
        }
    }
    return result;
};

export const startNewSession = async (
  operator: string, shift: string, workType: string, crane: string, yard: string, startHourMeter: number, client?: string
): Promise<{ session: Session; craneUsage: CraneUsage }> => {
  const now = new Date();
  const session: Session = { operator, shift, workType, client: workType === 'Operación de Barco' ? client : undefined, startTime: now };
  return await db.transaction('rw', [db.sessions, db.craneUsages, db.syncQueue], async () => {
      const sessionId = await db.sessions.add(session);
      session.id = sessionId;
      const craneUsage: CraneUsage = { sessionId, crane, yard, startHourMeter, startTime: now };
      const craneUsageId = await db.craneUsages.add(craneUsage);
      craneUsage.id = craneUsageId;
      await enqueueSync('SESSION_START', { 
          fecha: now.toLocaleDateString(), 
          hora: formatTime24h(now), 
          operador: operator, 
          turno: shift, 
          grua: crane, 
          predio: yard, 
          horimetro_inicial: startHourMeter, 
          jornada: workType,
          cliente: client || 'N/A'
      });
      return { session, craneUsage };
  });
};

export const getPendingHourMetersForSession = async (sessionId: number): Promise<CraneUsage[]> => {
    return await db.craneUsages.where('sessionId').equals(sessionId).filter(cu => cu.endHourMeter === undefined).toArray();
};

export const endCurrentSessionWithMeters = async (
  sessionId: number, finalMeters: Record<number, number>
): Promise<void> => {
  const now = new Date();
  await db.transaction('rw', [db.sessions, db.craneUsages, db.syncQueue], async () => {
    const session = await db.sessions.get(sessionId);
    await db.sessions.update(sessionId, { endTime: now });
    for (const [idStr, meter] of Object.entries(finalMeters)) {
        const id = parseInt(idStr);
        const usage = await db.craneUsages.get(id);
        if (usage) {
            await db.craneUsages.update(id, { endHourMeter: meter, endTime: usage.endTime || now });
            await enqueueSync('SESSION_END_CRANE', {
                sessionId,
                fecha: now.toLocaleDateString(),
                hora: formatTime24h(now),
                operador: session?.operator || 'Desconocido',
                grua: usage.crane,
                horimetro_inicial: usage.startHourMeter,
                horimetro_final: meter, // Nombre de etiqueta ajustado según requerimiento
                total_horas: (meter - usage.startHourMeter).toFixed(2)
            });
        }
    }
  });
};

export const addMovement = async (movement: Omit<Movement, 'id'>): Promise<number> => {
  const id = await db.movements.add(movement as Movement);
  const now = new Date(movement.timestamp);
  const session = await db.sessions.get(movement.sessionId);

  await enqueueSync('MOVEMENT', {
      target_sheet: 'Movimientos_Live',
      fecha: now.toLocaleDateString(),
      hora: formatTime24h(now),
      operador: movement.operator,
      grua: movement.crane,
      cliente: movement.client,
      contenedor: movement.containerNumber,
      razon: movement.reason,
      predio: movement.yard,
      jornada: session?.workType || 'N/A'
  });

  try {
      const config = await getAppConfig();
      const consolidatedPayload: any = {
          event_type: 'CONSOLIDATED_LIVE',
          target_sheet: 'Consolidado_Live',
          request_id: generateRequestId(),
          fecha: now.toLocaleDateString(),
          hora: formatTime24h(now),
          operador: movement.operator,
          turno: session?.shift || 'N/A',
          jornada: session?.workType || 'N/A',
          grua: movement.crane,
          predio: movement.yard,
          contenedor: movement.containerNumber
      };

      config.CLIENTS.forEach(c => {
          consolidatedPayload[`CLIENTE: ${c}`] = (movement.client === c) ? 1 : 0;
      });

      config.MOVEMENT_REASONS.forEach(r => {
          consolidatedPayload[`MOTIVO: ${r}`] = (movement.reason === r) ? 1 : 0;
      });

      await enqueueSync('CONSOLIDATED_LIVE', consolidatedPayload);
  } catch (err) {
      console.error("Error preparando sync consolidado:", err);
  }

  return id;
};

export const addWorkshopRecord = async (record: Omit<WorkshopRecord, 'id'>): Promise<number> => {
  const id = await db.workshopRecords.add(record as WorkshopRecord);
  const now = new Date(record.timestamp);
  await enqueueSync('WORKSHOP', { 
      target_sheet: 'Fallas_Mecanicas',
      fecha: now.toLocaleDateString(), 
      hora: formatTime24h(now), 
      grua: record.crane, 
      detalles_fallo: record.details // Nombre de etiqueta unificado
  });
  return id;
};

export const getRecentMovements = async (sessionId: number, limit = 5, craneUsageId?: number): Promise<Movement[]> => {
  if (craneUsageId) {
    return db.movements.where('craneUsageId').equals(craneUsageId).reverse().limit(limit).toArray();
  }
  return db.movements.where('sessionId').equals(sessionId).reverse().limit(limit).toArray();
};

export const countSessionMovements = async (sessionId: number): Promise<number> => {
    return await db.movements.where({ sessionId }).count();
}

export const changeCrane = async (
  oldCraneUsageId: number, changeReason: string, newCrane: string,
  newYard: string, newStartHourMeter: number, sessionId: number, oldEndHourMeter: number, changeReasonDetails?: string
): Promise<CraneUsage> => {
  const now = new Date();
  return await db.transaction('rw', [db.sessions, db.craneUsages, db.syncQueue], async () => {
    const oldUsage = await db.craneUsages.get(oldCraneUsageId);
    const session = await db.sessions.get(sessionId);

    await db.craneUsages.update(oldCraneUsageId, { 
        changeReason, 
        changeReasonDetails, 
        endHourMeter: oldEndHourMeter, 
        endTime: now 
    });

    const newCraneUsage: CraneUsage = { sessionId, crane: newCrane, yard: newYard, startHourMeter: newStartHourMeter, startTime: now };
    const newCraneUsageId = await db.craneUsages.add(newCraneUsage);
    newCraneUsage.id = newCraneUsageId;

    if (oldUsage) {
        await enqueueSync('CRANE_CHANGE', {
            target_sheet: 'Cambios_Equipo',
            fecha: now.toLocaleDateString(),
            hora: formatTime24h(now),
            operador: session?.operator || 'N/A',
            grua_saliente: oldUsage.crane,
            horimetro_final_saliente: oldEndHourMeter,
            razon: changeReason, // Ajustado a "razon" por mapeo de nombres
            detalles_fallo: changeReasonDetails || 'N/A', // Etiqueta unificada
            grua_entrante: newCrane,
            horimetro_inicial_entrante: newStartHourMeter
        });
    }
    return newCraneUsage;
  });
};

export const changeYard = async (craneUsageId: number, newYard: string): Promise<void> => {
    const usage = await db.craneUsages.get(craneUsageId);
    await db.craneUsages.update(craneUsageId, { yard: newYard });
    const now = new Date();
    await enqueueSync('YARD_CHANGE', { 
        fecha: now.toLocaleDateString(), 
        hora: formatTime24h(now), 
        grua: usage?.crane || 'N/A', 
        predio: newYard // Ajustado a "predio" para consistencia
    });
};

export const findLastMovementByContainer = async (containerNumber: string): Promise<Movement | undefined> => {
    const movements = await db.movements.where('containerNumber').equals(containerNumber).toArray();
    if (movements.length === 0) return undefined;
    return movements.reduce((latest, current) => new Date(latest.timestamp) > new Date(current.timestamp) ? latest : current);
};

export const getAllDataForExport = async () => {
    const sessions = await db.sessions.toArray();
    const craneUsages = await db.craneUsages.toArray();
    const movements = await db.movements.toArray();
    const workshopRecords = await db.workshopRecords.toArray();
    return { sessions, craneUsages, movements, workshopRecords };
}

