Para solucionar los problemas de duplicidad y asegurar que los datos se registren correctamente en las columnas A-M de tu Google Sheet, he preparado tanto el código de **Google Apps Script** como los ajustes necesarios en tu archivo **db.ts**.

### 1. Google Apps Script (Código para el Servidor)

Este script filtra los eventos redundantes y mapea los nombres de campos variables (`yard`/`predio`, etc.) a la estructura exacta de tu hoja.

```javascript
/**
 * Google Apps Script: doPost
 * Escucha los eventos del sistema de grúas y los registra en la hoja 'GRUAS'
 */
function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);

    // 1. Filtro de Duplicados / Redundancia
    // Ignoramos eventos de consolidado para que no se dupliquen con los movimientos reales
    if (data.event_type === 'CONSOLIDATED_LIVE' || data.target_sheet === 'Consolidado_Live') {
      return ContentService.createTextOutput("Ignored: Consolidated record").setMimeType(ContentService.MimeType.TEXT);
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('GRUAS'); // Asegúrate de que el nombre coincida
    if (!sheet) {
      return ContentService.createTextOutput("Error: Sheet 'GRUAS' not found").setMimeType(ContentService.MimeType.TEXT);
    }

    // 2. Mapeo de Acción (Columna D)
    var accion = 'MOVIMIENTO';
    var type = data.event_type;
    if (type === 'SESSION_START') accion = 'INICIO SESION';
    else if (type === 'SESSION_END_CRANE') accion = 'FINAL SESION';
    else if (type === 'YARD_CHANGE') accion = 'CAMBIO PREDIO';
    else if (type === 'WORKSHOP') accion = 'FALLA MECANICA';
    else if (type === 'CRANE_CHANGE') accion = 'CAMBIO EQUIPO';

    // 3. Mapeo de Predio (Columna G) - Soporta ambos nombres
    var predio = data.predio || data.yard || '';

    // 4. Mapeo de Horómetro (Columna L) - Soporta finales, iniciales y camelCase
    var horometro = data.horimetro_final || data.horimetro_inicial || data.startHourMeter || '';

    // 5. Construcción de la Fila (A a M)
    // A:FECHA, B:HORA, C:JORNADA, D:ACCION, E:OPERADOR, F:GRUA, G:PREDIO, 
    // H:CLIENTE, I:CONTENEDOR, J:MOTIVO, K:comentarios_falla, L:HOROMETRO, M:requestId
    var row = [
      data.fecha || '',                      // A
      data.hora || '',                       // B
      data.jornada || '',                    // C
      accion,                                // D
      data.operador || '',                   // E
      data.grua || data.crane || '',         // F
      predio,                                // G
      data.cliente || '',                    // H
      data.contenedor || '',                 // I
      data.razon || data.reason || '',       // J
      data.detalles_fallo || '',             // K
      horometro,                             // L
      data.request_id || ''                  // M
    ];

    sheet.appendRow(row);

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);

  } catch (error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}
```

### 2. Ajustes en el Frontend (`services/db.ts`)

He actualizado la función `changeYard` para incluir al operador (obteniéndolo de la sesión) y me he asegurado de que `addMovement` y `changeCrane` utilicen los nombres de campo en español y las etiquetas unificadas que solicitaste.

