Aquí tienes la solución integral. He diseñado el código de **Google Apps Script** para que sea el "cerebro" que organiza las columnas y filtra los duplicados, y he ajustado el archivo **db.ts** en el frontend para que envíe los datos con los nombres exactos en español que tu hoja espera.

### 1. Código de Google Apps Script (Servidor)

Copia este código en tu editor de Apps Script. Este script se encarga de:
- Ignorar los eventos de consolidado para evitar duplicados en la hoja principal.
- Mapear la columna **ACCIÓN** (D) según el tipo de evento.
- Normalizar campos como **PREDIO** y **HORÓMETRO**.
- Mantener el orden estricto de las columnas **A hasta la M**.

```javascript
/**
 * Google Apps Script: doPost
 * Procesa los registros del sistema de grúas y los organiza en la hoja 'GRUAS'
 */
function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);

    // 1. Filtro de Duplicados / Redundancia
    // Ignoramos el evento 'CONSOLIDATED_LIVE' para que no ensucie la hoja principal 'GRUAS'
    if (data.event_type === 'CONSOLIDATED_LIVE' || data.target_sheet === 'Consolidado_Live') {
      return ContentService.createTextOutput("Ignored: Consolidated record").setMimeType(ContentService.MimeType.TEXT);
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('GRUAS'); 
    if (!sheet) {
      return ContentService.createTextOutput("Error: Sheet 'GRUAS' not found").setMimeType(ContentService.MimeType.TEXT);
    }

    // 2. Mapeo de Acción (Columna D)
    var accion = 'MOVIMIENTO';
    var type = data.event_type;
    if (type === 'SESSION_START') accion = 'INICIO SESION';
    else if (type === 'SESSION_END_CRANE') accion = 'FINAL SESION';
    else if (type === 'YARD_CHANGE') accion = 'CAMBIO PREDIO';
    else if (type === 'WORKSHOP') accion = 'FALLA MECANICA';
    else if (type === 'CRANE_CHANGE') accion = 'CAMBIO EQUIPO';

    // 3. Normalización de Predio (Columna G)
    var predio = data.predio || data.yard || '';

    // 4. Normalización de Horómetro (Columna L)
    var horometro = data.horimetro_final || data.horimetro_inicial || data.startHourMeter || '';

    // 5. Construcción de la Fila (Orden exacto A-M)
    // A:FECHA, B:HORA, C:JORNADA, D:ACCION, E:OPERADOR, F:GRUA, G:PREDIO, 
    // H:CLIENTE, I:CONTENEDOR, J:MOTIVO, K:COMENTARIO_FALLA, L:HOROMETRO, M:VERIFICADOR
    var row = [
      data.fecha || '',                      // A
      data.hora || '',                       // B
      data.jornada || '',                    // C
      accion,                                // D
      data.operador || '',                   // E
      data.grua || data.crane || '',         // F
      predio,                                // G
      data.cliente || '',                    // H
      data.contenedor || '',                 // I
      data.razon || data.reason || '',       // J
      data.detalles_fallo || '',             // K
      horometro,                             // L
      data.request_id || ''                  // M
    ];

    sheet.appendRow(row);

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);

  } catch (error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}
```

### 2. Cambios en el Frontend (db.ts)

He actualizado todas las funciones de sincronización para que incluyan la **JORNADA** y el **OPERADOR** en cada registro, y utilicen los nombres de campo en español para que el script los reciba sin problemas.

