        .first();

    if (activeUsage) {
        const session = await db.sessions.get(activeUsage.sessionId);
        if (session) {
            return { operator: session.operator, yard: activeUsage.yard };
        }
    }
    return null;
};

export const getAllActiveCranes = async (): Promise<Record<string, { operator: string, yard: string }>> => {
    const activeUsages = await db.craneUsages.filter(cu => cu.endTime === undefined).toArray();
    const result: Record<string, { operator: string, yard: string }> = {};
    for (const usage of activeUsages) {
        const session = await db.sessions.get(usage.sessionId);
        if (session) {
            result[usage.crane] = { operator: session.operator, yard: usage.yard };
        }
    }
    return result;
};

export const startNewSession = async (
  operator: string, shift: string, workType: string, crane: string, yard: string, startHourMeter: number, client?: string
): Promise<{ session: Session; craneUsage: CraneUsage }> => {
  const now = new Date();
  const session: Session = { operator, shift, workType, client: workType === 'Operación de Barco' ? client : undefined, startTime: now };
  return await db.transaction('rw', [db.sessions, db.craneUsages, db.syncQueue], async () => {
      const sessionId = await db.sessions.add(session);
      session.id = sessionId;
      const craneUsage: CraneUsage = { sessionId, crane, yard, startHourMeter, startTime: now };
      const craneUsageId = await db.craneUsages.add(craneUsage);
      craneUsage.id = craneUsageId;
      await enqueueSync('SESSION_START', { 
          fecha: now.toLocaleDateString(), 
          hora: formatTime24h(now), 
          operador: operator, 
          turno: shift, 
          grua: crane, 
          predio: yard, 
          horimetro_inicial: startHourMeter, 
          jornada: workType,
          cliente: client || 'N/A'
      });
      return { session, craneUsage };
  });
};

export const getPendingHourMetersForSession = async (sessionId: number): Promise<CraneUsage[]> => {
    return await db.craneUsages.where('sessionId').equals(sessionId).filter(cu => cu.endHourMeter === undefined).toArray();
};

export const endCurrentSessionWithMeters = async (
  sessionId: number, finalMeters: Record<number, number>
): Promise<void> => {
  const now = new Date();
  await db.transaction('rw', [db.sessions, db.craneUsages, db.syncQueue], async () => {
    const session = await db.sessions.get(sessionId);
    await db.sessions.update(sessionId, { endTime: now });
    for (const [idStr, meter] of Object.entries(finalMeters)) {
        const id = parseInt(idStr);
        const usage = await db.craneUsages.get(id);
        if (usage) {
            await db.craneUsages.update(id, { endHourMeter: meter, endTime: usage.endTime || now });
            await enqueueSync('SESSION_END_CRANE', {
                sessionId,
                fecha: now.toLocaleDateString(),
                hora: formatTime24h(now),
                operador: session?.operator || 'Desconocido',
                jornada: session?.workType || 'N/A',
                grua: usage.crane,
                predio: usage.yard,
                horimetro_inicial: usage.startHourMeter,
                horimetro_final: meter,
                total_horas: (meter - usage.startHourMeter).toFixed(2)
            });
        }
    }
  });
};

export const addMovement = async (movement: Omit<Movement, 'id'>): Promise<number> => {
  const id = await db.movements.add(movement as Movement);
  const now = new Date(movement.timestamp);
  const session = await db.sessions.get(movement.sessionId);

  // Enviamos el movimiento real para la hoja principal 'GRUAS'
  // Aseguramos que 'contenedor' y 'razon' nunca viajen vacíos
  await enqueueSync('MOVEMENT', {
      target_sheet: 'Movimientos_Live',
      fecha: now.toLocaleDateString(),
      hora: formatTime24h(now),
      operador: movement.operator,
      grua: movement.crane,
      cliente: movement.client || 'Otro',
      contenedor: movement.containerNumber || '0000000',
      razon: movement.reason || 'Sin Motivo',
      predio: movement.yard,
      jornada: session?.workType || 'N/A'
  });

  // Este evento de consolidado será ignorado por el script de la hoja principal 'GRUAS'
  try {
      const config = await getAppConfig();
      const consolidatedPayload: any = {
          event_type: 'CONSOLIDATED_LIVE',
          target_sheet: 'Consolidado_Live',
          request_id: generateRequestId(),
          fecha: now.toLocaleDateString(),
          hora: formatTime24h(now),
          operador: movement.operator,
          turno: session?.shift || 'N/A',
          jornada: session?.workType || 'N/A',
          grua: movement.crane,
          predio: movement.yard,
          contenedor: movement.containerNumber
      };
      config.CLIENTS.forEach(c => { consolidatedPayload[`CLIENTE: ${c}`] = (movement.client === c) ? 1 : 0; });
      config.MOVEMENT_REASONS.forEach(r => { consolidatedPayload[`MOTIVO: ${r}`] = (movement.reason === r) ? 1 : 0; });
      await enqueueSync('CONSOLIDATED_LIVE', consolidatedPayload);
  } catch (err) { console.error(err); }

  return id;
};

export const addWorkshopRecord = async (record: Omit<WorkshopRecord, 'id'>): Promise<number> => {
  const id = await db.workshopRecords.add(record as WorkshopRecord);
  const now = new Date(record.timestamp);
  const session = await db.sessions.get(record.sessionId);
  const usage = await db.craneUsages.get(record.craneUsageId);
  await enqueueSync('WORKSHOP', { 
      target_sheet: 'Fallas_Mecanicas',
      fecha: now.toLocaleDateString(), 
      hora: formatTime24h(now), 
      operador: session?.operator || 'N/A',
      jornada: session?.workType || 'N/A',
      grua: record.crane, 
      predio: usage?.yard || 'N/A',
      detalles_fallo: record.details 
  });
  return id;
};

export const getRecentMovements = async (sessionId: number, limit = 5, craneUsageId?: number): Promise<Movement[]> => {
  if (craneUsageId) return db.movements.where('craneUsageId').equals(craneUsageId).reverse().limit(limit).toArray();
  return db.movements.where('sessionId').equals(sessionId).reverse().limit(limit).toArray();
};

export const countSessionMovements = async (sessionId: number): Promise<number> => {
    return await db.movements.where({ sessionId }).count();
}

export const changeCrane = async (
  oldCraneUsageId: number, changeReason: string, newCrane: string,
  newYard: string, newStartHourMeter: number, sessionId: number, oldEndHourMeter: number, changeReasonDetails?: string
): Promise<CraneUsage> => {
  const now = new Date();
  return await db.transaction('rw', [db.sessions, db.craneUsages, db.syncQueue], async () => {
    const oldUsage = await db.craneUsages.get(oldCraneUsageId);
    const session = await db.sessions.get(sessionId);

    await db.craneUsages.update(oldCraneUsageId, { changeReason, changeReasonDetails, endHourMeter: oldEndHourMeter, endTime: now });

    const newCraneUsage: CraneUsage = { sessionId, crane: newCrane, yard: newYard, startHourMeter: newStartHourMeter, startTime: now };
    const newCraneUsageId = await db.craneUsages.add(newCraneUsage);
    newCraneUsage.id = newCraneUsageId;

    if (oldUsage) {
        await enqueueSync('CRANE_CHANGE', {
            target_sheet: 'Cambios_Equipo',
            fecha: now.toLocaleDateString(),
            hora: formatTime24h(now),
            operador: session?.operator || 'N/A',
            jornada: session?.workType || 'N/A',
            grua: oldUsage.crane,
            predio: oldUsage.yard,
            horimetro_final: oldEndHourMeter,
            razon: changeReason, 
            detalles_fallo: changeReasonDetails || 'N/A',
            grua_entrante: newCrane,
            horimetro_inicial_entrante: newStartHourMeter
        });
    }
    return newCraneUsage;
  });
};

export const changeYard = async (craneUsageId: number, newYard: string): Promise<void> => {
    const usage = await db.craneUsages.get(craneUsageId);
    if (!usage) return;
    const session = await db.sessions.get(usage.sessionId);
    await db.craneUsages.update(craneUsageId, { yard: newYard });
    const now = new Date();
    await enqueueSync('YARD_CHANGE', { 
        fecha: now.toLocaleDateString(), 
        hora: formatTime24h(now), 
        operador: session?.operator || 'N/A',
        jornada: session?.workType || 'N/A',
        grua: usage.crane, 
        predio: newYard 
    });
};

export const findLastMovementByContainer = async (containerNumber: string): Promise<Movement | undefined> => {
    const movements = await db.movements.where('containerNumber').equals(containerNumber).toArray();
    if (movements.length === 0) return undefined;
    return movements.reduce((latest, current) => new Date(latest.timestamp) > new Date(current.timestamp) ? latest : current);
};

export const getAllDataForExport = async () => {
    const sessions = await db.sessions.toArray();
    const craneUsages = await db.craneUsages.toArray();
    const movements = await db.movements.toArray();
    const workshopRecords = await db.workshopRecords.toArray();
    return { sessions, craneUsages, movements, workshopRecords };
}

payload.text:
Para resolver definitivamente el problema de que no se registra información y corregir los errores de mapeo (columnas vacías, `SIN_CONT`, duplicados), debemos sincronizar perfectamente el **Frontend** con un **Script de Google** robusto.

### 1. El Código Correcto para Google Apps Script
Borra todo el código que tengas en tu proyecto de Google Apps Script y pega este. Está diseñado para seguir el orden exacto de tus columnas (A-M) y filtrar los duplicados que mencionaste.

```javascript
/**
 * Google Apps Script: doPost
 * Procesa los registros siguiendo el orden:
 * A:FECHA, B:HORA, C:JORNADA, D:ACCION, E:OPERADOR, F:GRUA, G:PREDIO, 
 * H:CLIENTE, I:CONTENEDOR, J:MOTIVO, K:COMENTARIO_FALLA, L:HOROMETRO, M:VERIFICADOR
 */
function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);

    // 1. FILTRO ANTIDUPLICADOS
    // Ignoramos eventos de consolidado para que no se repitan en la hoja principal 'GRUAS'
    if (data.event_type === 'CONSOLIDATED_LIVE' || data.target_sheet === 'Consolidado_Live') {
      return ContentService.createTextOutput("Registro de consolidado omitido para evitar duplicidad.");
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('GRUAS'); 
    if (!sheet) return ContentService.createTextOutput("Error: No se encontró la hoja 'GRUAS'");

    // 2. DETERMINAR ACCIÓN (Columna D)
    var accion = 'MOVIMIENTO';
    if (data.event_type === 'SESSION_START') accion = 'INICIO SESION';
    else if (data.event_type === 'SESSION_END_CRANE') accion = 'FINAL SESION';
    else if (data.event_type === 'YARD_CHANGE') accion = 'CAMBIO PREDIO';
    else if (data.event_type === 'WORKSHOP') accion = 'FALLA MECANICA';
    else if (data.event_type === 'CRANE_CHANGE') accion = 'CAMBIO EQUIPO';

    // 3. OBTENER HORÓMETRO (Columna L)
    // Buscamos en todas las variantes posibles que envía el frontend
    var horometro = data.horometro_final || data.horometro_inicial || data.horometro || '';

    // 4. CONSTRUIR FILA (ORDEN ESTRICTO A - M)
    var row = [
      data.fecha || '',           // A: FECHA
      data.hora || '',            // B: HORA
      data.jornada || '',         // C: JORNADA
      accion,                     // D: ACCION
      data.operador || '',        // E: OPERADOR
      data.grua || '',            // F: GRUA
      data.predio || '',          // G: PREDIO
      data.cliente || '',         // H: CLIENTE
      data.contenedor || '',      // I: CONTENEDOR
      data.razon || '',           // J: MOTIVO
      data.detalles_fallo || '',  // K: COMENTARIO_FALLA
      horometro,                  // L: HOROMETRO
      data.request_id || ''       // M: VERIFICADOR (Código único)
    ];

    sheet.appendRow(row);
    return ContentService.createTextOutput("Éxito: Registro guardado.");

  } catch (error) {
    return ContentService.createTextOutput("Error en Servidor: " + error.toString());
  }
}
```
**Importante:** Después de pegar el código, haz clic en **"Implementar" > "Nueva implementación"**, elige **"Aplicación Web"**, configura **"Quién tiene acceso: Cualquier persona"** y copia la **nueva URL**.

---

### 2. Actualización del Frontend (db.ts)

He ajustado `db.ts` para que los nombres de los datos coincidan exactamente con lo que el script de arriba espera, eliminando el uso de `SIN_CONT` o `SIN_MOTIVO` si el campo está vacío, y asegurando que el **Inicio de Sesión** envíe el nombre del operador y la jornada correctamente.

